#!/usr/bin/env bash
# GRE / Traffic Manager v1.5.2
# Generated by tools/build.py. Edit src/*.sh, then rebuild.
# gre-stable.sh is a separate, frozen legacy release.

# BEGIN MODULE: core
# Shared pure validation and explicit command execution.
GTM_VERSION=1.5.2

gtm_error() { printf 'Error: %s\n' "$*" >&2; return 1; }

gtm_uint() {
    [[ $1 =~ ^[0-9]{1,7}$ ]] || return 1
    (( 10#$1 >= $2 && 10#$1 <= $3 ))
}

gtm_port() { gtm_uint "$1" 1 65535; }

gtm_ipv4() {
    local ip=$1 octet
    [[ $ip =~ ^([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})$ ]] || return 1
    for octet in "${BASH_REMATCH[@]:1}"; do
        [[ $octet == 0 || $octet != 0* ]] || return 1
        (( 10#$octet <= 255 )) || return 1
    done
}

gtm_ipv6() {
    local ip=$1 left right part count=0
    [[ $ip == *:* && $ip =~ ^[0-9a-fA-F:]+$ && ${#ip} -le 39 && $ip != *:::* ]] || return 1
    if [[ $ip == *::* ]]; then
        left=${ip%%::*}; right=${ip#*::}
        [[ $right != *::* ]] || return 1
        # A single colon may not open or close either side (":1::2", "1::2:").
        [[ $left != :* && $left != *: && $right != :* && $right != *: ]] || return 1
        ip=${left:+$left:}$right
        for part in ${ip//:/ }; do [[ ${#part} -le 4 ]] || return 1; ((count+=1)); done
        (( count < 8 ))
    else
        [[ $ip != :* && $ip != *: ]] || return 1
        for part in ${ip//:/ }; do [[ ${#part} -le 4 ]] || return 1; ((count+=1)); done
        (( count == 8 ))
    fi
}

gtm_ip() { gtm_ipv4 "$1" || gtm_ipv6 "$1"; }

# A stable comparison key; equivalent IPv6 spellings must not evade ownership checks.
# gtm_key_of sets GTM_KEY without a subshell; hot validation loops must use it.
gtm_key_of() {
    local address=$1 left right part missing index key=''
    local -a words=() suffix=()
    GTM_KEY=''
    gtm_ip "$address" || return 1
    if [[ $address != *:* ]]; then GTM_KEY=$address; return 0; fi
    if [[ $address == *::* ]]; then
        left=${address%%::*}; right=${address#*::}
        [[ -z $left ]] || IFS=: read -r -a words <<< "$left"
        [[ -z $right ]] || IFS=: read -r -a suffix <<< "$right"
        missing=$((8-${#words[@]}-${#suffix[@]}))
        for ((index=0; index<missing; index++)); do words+=(0); done
        words+=("${suffix[@]}")
    else IFS=: read -r -a words <<< "$address"; fi
    for part in "${words[@]}"; do printf -v part '%04x' "$((16#$part))"; key+=$part; done
    GTM_KEY=$key
}
gtm_ip_key() { gtm_key_of "$1" && printf '%s' "$GTM_KEY"; }

# Unspecified binds mean every local address of that family (0.0.0.0 or ::).
gtm_wildcard_key() { [[ $1 == 0.0.0.0 || $1 == 00000000000000000000000000000000 ]]; }
gtm_wildcard() { gtm_key_of "$1" && gtm_wildcard_key "$GTM_KEY"; }
gtm_name() { [[ $1 =~ ^[a-zA-Z0-9][a-zA-Z0-9_.\ -]{0,39}$ ]]; }
gtm_id() { [[ $1 =~ ^F[0-9]{6}$ ]]; }
gtm_iface() { [[ $1 == any || $1 =~ ^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,14}$ ]]; }

# Sets EP_IP, EP_PORT and EP_WEIGHT. IPv6 endpoints use [address]:port@weight.
gtm_endpoint() {
    local value=$1 address port weight=1
    if [[ $value == *@* ]]; then weight=${value##*@}; value=${value%@*}; fi
    gtm_uint "$weight" 1 256 || return 1
    if [[ $value =~ ^\[([0-9a-fA-F:]+)\]:([0-9]+)$ ]]; then
        address=${BASH_REMATCH[1]}; port=${BASH_REMATCH[2]}
        gtm_ipv6 "$address" || return 1
    elif [[ $value =~ ^([0-9.]+):([0-9]+)$ ]]; then
        address=${BASH_REMATCH[1]}; port=${BASH_REMATCH[2]}
        gtm_ipv4 "$address" || return 1
    else return 1; fi
    gtm_port "$port" || return 1
    EP_IP=$address; EP_PORT=$((10#$port)); EP_WEIGHT=$((10#$weight))
}

gtm_address() { if [[ $1 == *:* ]]; then printf '[%s]:%s' "$1" "$2"; else printf '%s:%s' "$1" "$2"; fi; }

# A port or an ascending range of at most GTM_SPAN_MAX ports; sets PS_FIRST/PS_LAST.
GTM_SPAN_MAX=4096
gtm_port_span() {
    PS_FIRST='' PS_LAST=''
    if [[ $1 =~ ^([0-9]{1,5})-([0-9]{1,5})$ ]]; then
        local first=${BASH_REMATCH[1]} last=${BASH_REMATCH[2]}
        gtm_port "$first" && gtm_port "$last" || return 1
        PS_FIRST=$((10#$first)); PS_LAST=$((10#$last))
        (( PS_FIRST < PS_LAST && PS_LAST - PS_FIRST < GTM_SPAN_MAX ))
    else
        gtm_port "$1" || return 1
        PS_FIRST=$((10#$1)); PS_LAST=$PS_FIRST
    fi
}

# Lowercase DNS name with a letter top-level label; never an address in disguise.
gtm_hostname() {
    [[ ${#1} -le 253 && $1 =~ ^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]([a-z0-9-]{0,61}[a-z0-9])?$ ]]
}

# Record destinations: gtm_endpoint plus a DNS name (EP_HOST=1) and a port range
# (EP_LAST). Legacy parsers keep the strict gtm_endpoint.
gtm_target() {
    local value=$1 address port weight=1
    EP_HOST=0
    if [[ $value == *@* ]]; then weight=${value##*@}; value=${value%@*}; fi
    gtm_uint "$weight" 1 256 || return 1
    if [[ $value =~ ^\[([0-9a-fA-F:]+)\]:([0-9-]+)$ ]]; then
        address=${BASH_REMATCH[1]}; port=${BASH_REMATCH[2]}
        gtm_ipv6 "$address" || return 1
    elif [[ $value =~ ^([0-9.]+):([0-9-]+)$ ]]; then
        address=${BASH_REMATCH[1]}; port=${BASH_REMATCH[2]}
        gtm_ipv4 "$address" || return 1
    elif [[ $value =~ ^([a-z0-9.-]+):([0-9-]+)$ ]]; then
        address=${BASH_REMATCH[1]}; port=${BASH_REMATCH[2]}
        gtm_hostname "$address" && [[ ! $address =~ ^[0-9.]+$ ]] || return 1
        EP_HOST=1
    else return 1; fi
    gtm_port_span "$port" || return 1
    EP_IP=$address; EP_PORT=$PS_FIRST; EP_LAST=$PS_LAST; EP_WEIGHT=$((10#$weight))
}

# Port text for rules: "443" or "2000-2999" (nft) / "2000:2999" (iptables).
gtm_span_text() { if (( $1 == $2 )); then printf '%d' "$1"; else printf '%d%s%d' "$1" "${3:--}" "$2"; fi; }

gtm_need() { command -v "$1" >/dev/null 2>&1 || gtm_error "Install the required tool first: $1"; }

gtm_root() {
    [[ ${GTM_DEMO:-0} == 0 ]] || { gtm_error 'Demo mode does not apply changes.'; return 1; }
    (( EUID == 0 )) || gtm_error 'Run with sudo to change server settings.'
}

gtm_pause() { [[ -t 0 ]] && { printf '\n'; read -r -p 'Enter to continue... ' _; }; return 0; }

gtm_confirm() {
    local answer
    printf '\n  [1] Confirm\n  [0] Cancel\n'
    gtm_default 'Select option' answer 0 || return 1
    [[ $answer == 1 || $answer == y || $answer == Y || $answer == yes ]]
}

gtm_paths() {
    GTM_CONFIG_DIR=${GTM_CONFIG_DIR:-/etc/gre-manager}
    GTM_STATE="$GTM_CONFIG_DIR/connections.tsv"
    GTM_RUN_DIR=${GTM_RUN_DIR:-/run/gre-manager}
    GTM_SERVICE_DIR=${GTM_SERVICE_DIR:-/etc/systemd/system}
    GTM_RUNTIME=${GTM_RUNTIME:-/usr/local/lib/gre-manager/apply.sh}
    GTM_SYSCTL_DIR=${GTM_SYSCTL_DIR:-/etc/sysctl.d}
    # A relocated sysctl directory (tests, staging roots) keeps every optimization
    # file inside it; only the real one scans the system drop-in directories.
    if [[ $GTM_SYSCTL_DIR == /etc/sysctl.d ]]; then
        GTM_MODULES_DIR=/etc/modules-load.d
        GTM_SYSCTL_SCAN='/etc/sysctl.d /run/sysctl.d /usr/local/lib/sysctl.d /usr/lib/sysctl.d /lib/sysctl.d'
    else
        GTM_MODULES_DIR=$GTM_SYSCTL_DIR GTM_SYSCTL_SCAN=$GTM_SYSCTL_DIR
    fi
    GTM_MODULES_FILE="$GTM_MODULES_DIR/gre-manager-conntrack.conf"
    GTM_SIMPLE_SCRIPT=${GTM_SIMPLE_SCRIPT:-/opt/simple_gre_script.sh}
    GTM_SIMPLE_UNIT="$GTM_SERVICE_DIR/simple-gre.service"
}

gtm_prepare() {
    gtm_root && gtm_need flock || return 1
    umask 077
    mkdir -p "$GTM_CONFIG_DIR" "$GTM_CONFIG_DIR/backups" "$GTM_RUN_DIR" || return 1
    chmod 700 "$GTM_CONFIG_DIR" "$GTM_CONFIG_DIR/backups" "$GTM_RUN_DIR" || return 1
}

gtm_lock() {
    exec 9>"$GTM_CONFIG_DIR/manager.lock" || return 1
    flock -x -w 10 9 || { exec 9>&-; gtm_error 'Another operation is running. Try again.'; }
}
gtm_unlock() { flock -u 9; exec 9>&-; }

# Legacy validators now share the same bounded input checks.

# BEGIN MODULE: server_info
# Session-only header information. No files, services, probes or package installs.
gtm_info_text() {
    local LC_ALL=C value=$1
    # External text is display data: discard controls, escapes and non-ASCII bytes.
    value=${value//[^a-zA-Z0-9 .,:_@+\(\)\&\/-]/}
    printf '%s' "${value:0:120}"
}

gtm_info_string() {
    local key=$1 payload=$2 pattern
    # Only the API's small, unescaped string fields are accepted. Never eval JSON.
    pattern='"'"$key"'"[[:space:]]*:[[:space:]]*"([^"\\]*)"'
    [[ $payload =~ $pattern ]] || return 1
    printf '%s' "${BASH_REMATCH[1]}"
}

gtm_server_local_info() {
    local key value index iface family cidr rest address route preferred4='' preferred6='' candidate4='' candidate6=''
    GTM_HOST=$(gtm_info_text "$(hostname 2>/dev/null)")
    GTM_OS='Linux'; GTM_LOCAL4=''; GTM_LOCAL6=''
    if [[ -r /etc/os-release ]]; then
        while IFS='=' read -r key value; do
            [[ $key == PRETTY_NAME ]] || continue
            value=${value#\"}; value=${value%\"}
            GTM_OS=$(gtm_info_text "$value"); break
        done < /etc/os-release
    fi
    if command -v ip >/dev/null 2>&1; then
        while IFS= read -r route; do
            [[ $route =~ ^default[[:space:]].*dev[[:space:]]+([^[:space:]]+) ]] || continue
            preferred4=${BASH_REMATCH[1]}; break
        done < <(ip -4 route show default 2>/dev/null)
        while IFS= read -r route; do
            [[ $route =~ ^default[[:space:]].*dev[[:space:]]+([^[:space:]]+) ]] || continue
            preferred6=${BASH_REMATCH[1]}; break
        done < <(ip -6 route show default 2>/dev/null)
        while read -r index iface family cidr rest; do
            address=${cidr%/*}; iface=${iface%%@*}
            case $iface in lo|gre*|ip6gre*|sit*|docker*|veth*|br-*) continue;; esac
            if [[ $family == inet ]] && gtm_ipv4 "$address"; then
                [[ -n $candidate4 ]] || candidate4=$address
                [[ $iface != "$preferred4" || -n $GTM_LOCAL4 ]] || GTM_LOCAL4=$address
            elif [[ $family == inet6 ]] && gtm_ipv6 "$address" && [[ $rest != *tentative* && $rest != *deprecated* ]]; then
                [[ -n $candidate6 ]] || candidate6=$address
                [[ $iface != "$preferred6" || -n $GTM_LOCAL6 ]] || GTM_LOCAL6=$address
            fi
        done < <(ip -o address show scope global 2>/dev/null)
        GTM_LOCAL4=${GTM_LOCAL4:-$candidate4}; GTM_LOCAL6=${GTM_LOCAL6:-$candidate6}
    fi
}

gtm_server_lookup() {
    local payload address org country asn pattern='"success"[[:space:]]*:[[:space:]]*true([[:space:],}])'
    command -v curl >/dev/null 2>&1 || return 0
    # One best-effort HTTPS request, bounded to two seconds. Bypass HTTP proxies
    # so the address is the server's egress rather than a configured proxy's IP.
    payload=$(curl -q -fsS --noproxy '*' --proto '=https' --connect-timeout 1 --max-time 2 --max-filesize 8192 \
        'https://ipwho.is/?fields=success,ip,country,connection.org,connection.asn' 2>/dev/null) || return 0
    [[ ${#payload} -le 8192 && $payload =~ $pattern ]] || return 0
    address=$(gtm_info_string ip "$payload") || return 0
    gtm_ip "$address" || return 0
    GTM_PUBLIC_IP=$address
    org=$(gtm_info_string org "$payload") || org=''
    country=$(gtm_info_string country "$payload") || country=''
    GTM_PROVIDER=$(gtm_info_text "$org"); GTM_COUNTRY=$(gtm_info_text "$country")
    pattern='"asn"[[:space:]]*:[[:space:]]*([0-9]{1,10})([[:space:],}])'
    if [[ $payload =~ $pattern ]]; then asn=${BASH_REMATCH[1]}; GTM_ASN="AS$asn"; fi
}

gtm_server_info() {
    [[ ${GTM_SERVER_INFO_READY:-0} != 1 ]] || return 0
    GTM_SERVER_INFO_READY=1
    GTM_HOST=''; GTM_OS=''; GTM_LOCAL4=''; GTM_LOCAL6=''
    GTM_PUBLIC_IP=''; GTM_PROVIDER=''; GTM_COUNTRY=''; GTM_ASN=''
    if [[ ${GTM_DEMO:-0} == 1 ]]; then
        GTM_HOST=demo-server; GTM_OS='Ubuntu 24.04'; GTM_LOCAL4=203.0.113.10; GTM_LOCAL6=2001:db8::10
        GTM_PUBLIC_IP=$GTM_LOCAL4; GTM_PROVIDER='Example Hosting'; GTM_COUNTRY=Germany; GTM_ASN=AS64500
        return 0
    fi
    gtm_server_local_info
    if [[ -t 0 && -t 1 && ${GTM_SERVER_LOOKUP:-1} != 0 ]]; then gtm_server_lookup; fi
    return 0
}

gtm_header_address() {
    local label=$1 address=$2 style=${3:-$GTM_HIGHLIGHT}
    if ((${#label}+${#address}<=GTM_UI_WIDTH)); then
        gtm_panel_text "$label$address" "$style"
    else
        gtm_panel_text "$label" "$GTM_DIM"
        # Use the full window for a long IPv6 address before wrapping it.
        if ((${#address}<=GTM_UI_WIDTH+4)); then printf '%b%s%b\n' "$style" "$address" "$GTM_RESET"
        else gtm_panel_wrap "$address" "$style"; fi
    fi
}

gtm_server_header() {
    local host provider public4='' public6=''
    gtm_server_info
    host=${GTM_HOST:-unknown}
    if ((GTM_UI_WIDTH>=64)); then host+="  /  $GTM_OS"; fi
    gtm_panel_text "Host      $host" "$GTM_DIM"
    if [[ -n $GTM_PUBLIC_IP ]]; then
        if [[ $GTM_PUBLIC_IP == *:* ]]; then public6=$GTM_PUBLIC_IP; else public4=$GTM_PUBLIC_IP; fi
    fi
    # Addresses are never ellipsized or combined with another value on a line.
    if [[ -n $public4 ]]; then gtm_header_address 'Public v4 ' "$public4"
    else gtm_header_address 'Local v4  ' "${GTM_LOCAL4:-not detected}"; fi
    if [[ -n $GTM_LOCAL4 && -n $public4 && $GTM_LOCAL4 != "$public4" ]]; then gtm_header_address 'Local v4  ' "$GTM_LOCAL4" "$GTM_INK"; fi
    if [[ -n $public6 ]]; then gtm_header_address 'Public v6 ' "$public6"
    elif [[ -n $GTM_LOCAL6 ]]; then gtm_header_address 'Local v6  ' "$GTM_LOCAL6"; fi
    if [[ -n $GTM_LOCAL6 && -n $public6 && $GTM_LOCAL6 != "$public6" ]]; then gtm_header_address 'Local v6  ' "$GTM_LOCAL6" "$GTM_INK"; fi
    provider=${GTM_PROVIDER:-unavailable}
    [[ -z $GTM_ASN ]] || provider+=" / $GTM_ASN"
    [[ -z $GTM_COUNTRY ]] || provider+=" / $GTM_COUNTRY"
    gtm_panel_text "Provider  $provider" "$GTM_DIM"
}

# BEGIN MODULE: ui
# Fixed terminal styling. No themes, preferences, translations or background fills.
gtm_palette() {
    GTM_RESET=''; GTM_INK=''; GTM_DIM=''; GTM_HIGHLIGHT=''; GTM_BAD=''; GTM_GOOD=''; GTM_RULE=''; GTM_STRONG=''
    BOLD=''; RED=''; GREEN=''; YELLOW=''; BLUE=''; CYAN=''; PURPLE=''; WHITE=''; GREY=''; NC=''; HI_CYAN=''; HI_PINK=''; HI_GREEN=''
    [[ -z ${NO_COLOR:-} && ${TERM:-dumb} != dumb && ( -t 1 || ${GTM_FORCE_COLOR:-0} == 1 ) ]] || return 0
    GTM_RESET=$'\033[0m'; GTM_STRONG=$'\033[1m'; GTM_INK=$'\033[0;37m'
    GTM_DIM=$'\033[0;37m'; GTM_HIGHLIGHT=$'\033[0;96m'; GTM_RULE=$'\033[0;36m'
    GTM_BAD=$'\033[0;91m'; GTM_GOOD=$'\033[0;92m'
    BOLD=$GTM_STRONG; RED=$GTM_BAD; GREEN=$GTM_GOOD; YELLOW=$'\033[0;93m'; BLUE=$'\033[0;94m'
    CYAN=$GTM_HIGHLIGHT; PURPLE=$'\033[0;95m'; WHITE=$GTM_INK; GREY=$GTM_DIM
    NC=$GTM_RESET; HI_CYAN=$CYAN; HI_PINK=$PURPLE; HI_GREEN=$GREEN
}

gtm_text() {
    case $1 in
        forward) printf 'Use this server as the entry point.';;
        targets) printf 'Enter a target IP. IP:port is also accepted.';;
        delete) printf 'Select one or more rows, for example: 1 3 4.';;
        confirm) printf 'Check the details before applying.';;
        links) printf 'Use Kharej on one server and Iran on the other.';;
        relay) printf 'This tunnel runs its own service.';;
        reverse) printf 'Set up both servers with the same connection details.';;
        load) printf 'Use several servers for new connections.';;
        haproxy) printf 'TCP tunnel settings. Changes apply only after saving.';;
        tuning) printf 'These settings affect the whole server.';;
        *) printf '%s' "$1";;
    esac
}

gtm_help() { printf '\n  %s\n\n' "$(gtm_text "$1")"; }

gtm_terminal_size() {
    local cols=${COLUMNS:-80} rows=${LINES:-24} measured
    if [[ -t 1 ]] && command -v tput >/dev/null 2>&1; then
        measured=$(tput cols 2>/dev/null) && cols=$measured
        measured=$(tput lines 2>/dev/null) && rows=$measured
    fi
    gtm_uint "$cols" 20 65535 || cols=80
    gtm_uint "$rows" 10 65535 || rows=24
    GTM_UI_WIDTH=$((cols>84?80:cols-4)); GTM_UI_ROWS=$rows
}

gtm_panel_rule() {
    local line
    printf -v line '%*s' "$GTM_UI_WIDTH" ''
    printf '  %b%s%b\n' "$GTM_RULE" "${line// /-}" "$GTM_RESET"
}

gtm_panel_text() {
    local text=$1 style=${2:-$GTM_INK} room=$GTM_UI_WIDTH
    if ((${#text}>room)); then text="${text:0:room-3}..."; fi
    printf '  %b%s%b\n' "$style" "$text" "$GTM_RESET"
}

gtm_panel_wrap() {
    local text=$1 style=${2:-$GTM_INK} room=$GTM_UI_WIDTH
    while ((${#text}>room)); do gtm_panel_text "${text:0:room}" "$style"; text=${text:room}; done
    gtm_panel_text "$text" "$style"
}

gtm_panel_end() { :; }

gtm_header() {
    local title=$1 brand='GRE TUNNEL MANAGER'
    GTM_PAGE_TITLE=$title
    gtm_terminal_size
    if [[ -t 0 && -t 1 && -n $GTM_RESET ]]; then printf '\033[H\033[2J'; fi
    case $title in HAProxy*|HAPROXY*) brand='H A P R O X Y';; Realm*|REALM*) brand='R E A L M';; FRP*) brand='F R P';; rathole*) brand='R A T H O L E';; esac
    printf '\n'
    gtm_panel_rule
    if ((GTM_UI_WIDTH>=64 && GTM_UI_ROWS>=34)); then
        gtm_panel_text '  ___  ___  ___' "$HI_CYAN$BOLD"
        gtm_panel_text ' / __|| _ \| __|   T U N N E L   M A N A G E R' "$HI_CYAN$BOLD"
        gtm_panel_text '| (_ ||   /| _|' "$HI_CYAN$BOLD"
        gtm_panel_text " \___||_|_\\|___|   v$GTM_VERSION" "$HI_CYAN$BOLD"
        [[ $brand == 'GRE TUNNEL MANAGER' ]] || gtm_panel_text "$brand" "$HI_PINK$BOLD"
    else
        gtm_panel_text "$brand" "$HI_CYAN$BOLD"
        gtm_panel_text "Tunnel Manager v$GTM_VERSION" "$HI_PINK"
    fi
    gtm_server_header
    gtm_panel_rule
    gtm_panel_text "$title" "$BOLD$GTM_INK"
    [[ ${GTM_DEMO:-0} != 1 ]] || printf '  DEMO / no server changes\n'
    printf '\n'
}

gtm_option() {
    local label description=${3:-} room style=$GTM_INK
    case $2 in Add*|Save*|Start*) style=$GREEN;; Delete*|Stop*|Cleanup*) style=$RED;; Back|Cancel|Exit) style=$YELLOW;; esac
    [[ -n ${GTM_UI_WIDTH:-} ]] || gtm_terminal_size
    printf -v label '[%s] %s' "$1" "$2"
    room=$((GTM_UI_WIDTH-29-${#1}))
    if [[ -n $description && $room -ge 25 && ${#2} -le 25 ]]; then
        if ((${#description}>room)); then description="${description:0:room-3}..."; fi
        printf '  %b[%s]%b %-25s %b%s%b\n' "$HI_CYAN" "$1" "$style" "$2" "$GREY" "$description" "$GTM_RESET"
    else gtm_panel_text "$label" "$style"; fi
}

gtm_read() {
    printf '\n  %b%s%b\n  %b>%b ' "$HI_CYAN" "$1" "$GTM_RESET" "$HI_PINK" "$GTM_RESET"
    IFS= read -r "$2"
}

gtm_default() {
    local label=$1 variable=$2 default=$3 _gtm_input
    printf '\n  %b%s%b' "$HI_CYAN" "$label" "$GTM_RESET"
    [[ -z $default ]] || printf '  %b(Enter = %s)%b' "$GREY" "$default" "$GTM_RESET"
    printf '\n  %b>%b ' "$HI_PINK" "$GTM_RESET"
    IFS= read -r _gtm_input || return 1
    printf -v "$variable" '%s' "${_gtm_input:-$default}"
}

# label/value pairs; callers consume GTM_REPLY. No words need to be typed.
gtm_choose() {
    local title=$1 default=$2 entry number=1 selected=1
    local -a labels=() values=()
    shift 2
    while (($#>=2)); do labels+=("$1"); values+=("$2"); shift 2; done
    for entry in "${!values[@]}"; do [[ ${values[$entry]} != "$default" ]] || selected=$((entry+1)); done
    printf '\n  %b%s%b\n' "$HI_PINK$BOLD" "$title" "$GTM_RESET"
    for entry in "${labels[@]}"; do gtm_option "$number" "$entry"; ((number+=1)); done
    gtm_option 0 Cancel
    while true; do
        gtm_default 'Select option' number "$selected" || return 1
        [[ $number != 0 ]] || return 1
        if gtm_uint "$number" 1 "${#values[@]}"; then GTM_REPLY=${values[$((10#$number-1))]}; return 0; fi
        gtm_error 'Choose a number from the menu.'
    done
}

gtm_step() {
    # Redisplay the identity and IPs above each interactive setup step. Plain
    # transcripts keep their original flow, without repeated banners.
    if [[ -t 0 && -t 1 && $1 != 3 && -n ${GTM_PAGE_TITLE:-} ]]; then gtm_header "$GTM_PAGE_TITLE"; fi
    printf '\n  %bSTEP %s/%s  %s%b\n' "$HI_PINK$BOLD" "$1" "$2" "$3" "$GTM_RESET"
    gtm_panel_rule
}

gtm_connection_card() {
    local row=$1 state=$2 target
    [[ -n ${GTM_UI_WIDTH:-} ]] || gtm_terminal_size
    gtm_panel_wrap "[$row] $R_NAME  /  $R_ID" "$HI_CYAN$BOLD"
    gtm_panel_wrap "$R_ENGINE / $R_PROTO / $state" "$GTM_INK"
    gtm_panel_wrap "Local: $(gtm_address "$R_BIND" "$R_PORT")"
    local -a destinations=()
    IFS=, read -r -a destinations <<< "$R_TARGETS"
    for target in "${destinations[@]}"; do
        gtm_target "$target" || return 1
        gtm_panel_wrap "Remote: $(gtm_address "$EP_IP" "$EP_PORT")"
    done
    gtm_panel_rule
}

# BEGIN MODULE: haproxy_routing
# Closed routing schema v1, separate from TCP/health options. No raw directives.
gtm_routing_defaults() { H_ROUTE_MODE=tcp; H_CERT=-; H_ROUTES=-; }
gtm_routing_validate() {
    local input=$1 version mode cert routes extra rule host path target key
    local -a rules=() destinations=()
    local -A seen=()
    [[ $input != *$'\t'* && $input != *$'\n'* && $input != *$'\r'* ]] || return 1
    extra=${input//[^|]/}; ((${#extra}==3)) || return 1
    IFS='|' read -r version mode cert routes <<< "$input"
    [[ $version == 1 && $mode =~ ^(sni|http|https)$ ]] || return 1
    if [[ $mode == https ]]; then [[ $cert =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]{0,39}$ ]] || return 1
    else [[ $cert == - ]] || return 1; fi
    IFS=, read -r -a destinations <<< "$R_TARGETS"
    if [[ $routes != - ]]; then
        [[ -n $routes && $routes != ,* && $routes != *, && $routes != *,,* ]] || return 1
        IFS=, read -r -a rules <<< "$routes"
        ((${#rules[@]}<=16)) || return 1
        for rule in "${rules[@]}"; do
            extra=${rule//[^~]/}; ((${#extra}==2)) || return 1
            IFS='~' read -r host path target <<< "$rule"
            [[ $host =~ ^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$ && $host != *..* ]] || return 1
            [[ $path == - || ( $mode != sni && $path =~ ^/[a-zA-Z0-9/_.~-]{0,127}$ ) ]] || return 1
            gtm_uint "$target" 1 "${#destinations[@]}" || return 1
            key="$host~$path"; [[ ! ${seen[$key]+set} ]] || return 1; seen[$key]=1
        done
    fi
    H_ROUTE_MODE=$mode; H_CERT=$cert; H_ROUTES=$routes
}

gtm_haproxy_certificate() {
    local dir="$GTM_CONFIG_DIR/certificates" file
    [[ $H_ROUTE_MODE == https && $H_CERT =~ ^[a-zA-Z0-9][a-zA-Z0-9_-]{0,39}$ ]] || return 1
    file="$dir/$H_CERT.pem"
    # Root-provisioned PEM only. The HTTP process never reads or uploads keys.
    [[ -d $dir && ! -L $dir && -f $file && ! -L $file ]] &&
        [[ $(stat -c %u "$dir") == 0 && $(stat -c %a "$dir") == 700 &&
           $(stat -c %u "$file") == 0 && $(stat -c %a "$file") == 600 ]] || {
        gtm_error "Provision root-owned mode-600 PEM in mode-700 directory: $file"; return 1;
    }
    printf '%s' "$file"
}

gtm_haproxy_frontend() {
    local rule host path target index=0 cert
    local -a rules=()
    printf 'frontend entrance\n    bind %s' "$(gtm_address "$R_BIND" "$((10#$R_PORT))")"
    if [[ $H_ROUTE_MODE == https ]]; then
        # Offline preview only prints the reference. Native preflight checks PEM ownership.
        cert="$GTM_CONFIG_DIR/certificates/$H_CERT.pem"
        printf ' ssl crt %s ssl-min-ver TLSv1.2 alpn http/1.1' "$cert"
    fi
    printf '\n'
    ((10#$H_MAXCONN == 0)) || printf '    maxconn %d\n' "$((10#$H_MAXCONN))"
    if [[ $H_ROUTE_MODE == sni ]]; then
        printf '    tcp-request inspect-delay 5s\n    tcp-request content accept if { req.ssl_hello_type 1 }\n'
    fi
    if [[ $H_ROUTES != - ]]; then
        IFS=, read -r -a rules <<< "$H_ROUTES"
        for rule in "${rules[@]}"; do
            ((index+=1)); IFS='~' read -r host path target <<< "$rule"
            if [[ $H_ROUTE_MODE == sni ]]; then printf '    use_backend route%d if { req.ssl_sni -i %s }\n' "$index" "$host"
            else
                printf '    use_backend route%d if { hdr(host),lower,field(1,:) -m str %s }' "$index" "$host"
                [[ $path == - ]] || printf ' { path_beg %s }' "$path"
                printf '\n'
            fi
        done
    fi
    printf '    default_backend destinations\n'
}

gtm_haproxy_route_backends() {
    local rule host path target index=0
    local -a rules=()
    [[ $H_ROUTES != - ]] || return 0
    IFS=, read -r -a rules <<< "$H_ROUTES"
    for rule in "${rules[@]}"; do
        ((index+=1)); IFS='~' read -r host path target <<< "$rule"
        printf 'backend route%d\n' "$index"
        gtm_haproxy_servers "$target" || return 1
    done
}

# BEGIN MODULE: haproxy
# HAProxy TCP adapter. All knobs have bounded values; no raw config snippets.
gtm_haproxy_defaults() {
    H_CONNECT=5; H_IDLE=3600; H_QUEUE=30; H_MAXCONN=16384; H_SERVER_MAXCONN=0
    H_CHECK_INTERVAL=3; H_CHECK_TIMEOUT=5; H_CHECK_FALL=3; H_CHECK_RISE=2; H_CHECK_PORT=0
    H_SLOWSTART=0; H_PROXY=off; H_LOG=connections
    H_CHECK_MODE=tcp; H_CHECK_PATH=/health; H_CHECK_HOST=localhost; H_CHECK_STATUS=200
    H_STICK=off; H_STICK_SIZE=16384; H_STICK_EXPIRE=1800
    H_FIN=0; H_TUNNEL=0; H_RETRIES=3
    gtm_routing_defaults
}

gtm_haproxy_values_validate() {
    gtm_uint "$H_CONNECT" 1 300 && gtm_uint "$H_IDLE" 10 604800 && gtm_uint "$H_QUEUE" 1 3600 &&
        gtm_uint "$H_MAXCONN" 0 1000000 && gtm_uint "$H_SERVER_MAXCONN" 0 1000000 &&
        gtm_uint "$H_CHECK_INTERVAL" 1 300 && gtm_uint "$H_CHECK_TIMEOUT" 1 300 &&
        gtm_uint "$H_CHECK_FALL" 1 20 && gtm_uint "$H_CHECK_RISE" 1 20 &&
        gtm_uint "$H_CHECK_PORT" 0 65535 && gtm_uint "$H_SLOWSTART" 0 3600 &&
        [[ $H_PROXY =~ ^(off|v1|v2)$ && $H_LOG =~ ^(connections|errors|off)$ ]] &&
        [[ $H_CHECK_MODE =~ ^(off|tcp|http)$ && $H_CHECK_PATH =~ ^/[a-zA-Z0-9/_.~-]{0,127}$ &&
            $H_CHECK_HOST =~ ^[a-zA-Z0-9]([a-zA-Z0-9.-]{0,251}[a-zA-Z0-9])?$ ]] &&
        gtm_uint "$H_CHECK_STATUS" 200 599 &&
        { [[ $H_CHECK_MODE != http ]] || ((10#$H_CHECK_PORT > 0)); } &&
        [[ $H_STICK == off || $H_STICK == source ]] && gtm_uint "$H_STICK_SIZE" 1024 1000000 && gtm_uint "$H_STICK_EXPIRE" 30 86400 &&
        gtm_uint "$H_FIN" 0 300 && gtm_uint "$H_TUNNEL" 0 604800 && gtm_uint "$H_RETRIES" 0 5
}

gtm_haproxy_options_validate() {
    local options=$1 pair key value
    local -a pairs=()
    local -A seen=()
    [[ -n $options && $options != ';'* && $options != *';' && $options != *';;'* ]] || return 1
    gtm_haproxy_defaults
    IFS=';' read -r -a pairs <<< "$options"
    ((${#pairs[@]} <= 32)) || return 1
    for pair in "${pairs[@]}"; do
        [[ $pair == *=* ]] || return 1
        key=${pair%%=*}; value=${pair#*=}
        [[ -n $key && -n $value && ! ${seen[$key]+set} ]] || return 1
        seen[$key]=1
        case $key in
            fin) H_FIN=$value;; tunnel) H_TUNNEL=$value;; retries) H_RETRIES=$value;;
            connect) H_CONNECT=$value;; idle) H_IDLE=$value;; queue) H_QUEUE=$value;;
            maxconn) H_MAXCONN=$value;; server_maxconn) H_SERVER_MAXCONN=$value;;
            check_interval) H_CHECK_INTERVAL=$value;; check_timeout) H_CHECK_TIMEOUT=$value;;
            check_fall) H_CHECK_FALL=$value;; check_rise) H_CHECK_RISE=$value;; check_port) H_CHECK_PORT=$value;;
            slowstart) H_SLOWSTART=$value;; proxy) H_PROXY=$value;; log) H_LOG=$value;;
            check_mode) H_CHECK_MODE=$value;; check_path) H_CHECK_PATH=$value;;
            check_host) H_CHECK_HOST=$value;; check_status) H_CHECK_STATUS=$value;;
            stick) H_STICK=$value;; stick_size) H_STICK_SIZE=$value;; stick_expire) H_STICK_EXPIRE=$value;; *) return 1;;
        esac
    done
    gtm_haproxy_values_validate
}

gtm_haproxy_options() {
    gtm_haproxy_values_validate || return 1
    printf 'connect=%d;idle=%d;queue=%d;maxconn=%d;server_maxconn=%d;check_interval=%d;check_timeout=%d;check_fall=%d;check_rise=%d;check_port=%d;slowstart=%d;proxy=%s;log=%s' \
        "$((10#$H_CONNECT))" "$((10#$H_IDLE))" "$((10#$H_QUEUE))" "$((10#$H_MAXCONN))" "$((10#$H_SERVER_MAXCONN))" \
        "$((10#$H_CHECK_INTERVAL))" "$((10#$H_CHECK_TIMEOUT))" "$((10#$H_CHECK_FALL))" "$((10#$H_CHECK_RISE))" \
        "$((10#$H_CHECK_PORT))" "$((10#$H_SLOWSTART))" "$H_PROXY" "$H_LOG"
    # Omit the extension for baseline TCP records to keep their serialization stable.
    if [[ $H_CHECK_MODE != tcp || $H_CHECK_PATH != /health || $H_CHECK_HOST != localhost || $H_CHECK_STATUS != 200 ]]; then
        printf ';check_mode=%s;check_path=%s;check_host=%s;check_status=%d' "$H_CHECK_MODE" "$H_CHECK_PATH" "$H_CHECK_HOST" "$((10#$H_CHECK_STATUS))"
    fi
    if [[ $H_STICK != off || $H_STICK_SIZE != 16384 || $H_STICK_EXPIRE != 1800 ]]; then
        printf ';stick=%s;stick_size=%d;stick_expire=%d' "$H_STICK" "$((10#$H_STICK_SIZE))" "$((10#$H_STICK_EXPIRE))"
    fi
    if [[ $H_FIN != 0 || $H_TUNNEL != 0 || $H_RETRIES != 3 ]]; then
        printf ';fin=%d;tunnel=%d;retries=%d' "$((10#$H_FIN))" "$((10#$H_TUNNEL))" "$((10#$H_RETRIES))"
    fi
}

gtm_haproxy_socket() { gtm_id "$1" && printf '%s/haproxy/%s.sock' "$GTM_RUN_DIR" "$1"; }

gtm_haproxy_render() {
    local algorithm=$R_STRATEGY
    gtm_haproxy_values_validate || return 1
    case $algorithm in single|failover) algorithm=roundrobin;; esac
    printf 'global\n'
    [[ $H_LOG == off ]] || printf '    log stdout format raw local0\n'
    ((10#$H_MAXCONN == 0)) || printf '    maxconn %d\n' "$((10#$H_MAXCONN))"
    printf '    user nobody\n    group nogroup\n'
    printf '    stats socket %s mode 600 level user\n    stats timeout 3s\n' "$(gtm_haproxy_socket "$R_ID")"
    printf 'defaults\n    mode %s\n' "$([[ $H_ROUTE_MODE == http || $H_ROUTE_MODE == https ]] && printf http || printf tcp)"
    [[ $H_LOG == off ]] || printf '    log global\n    option %s\n' "$([[ $H_ROUTE_MODE == http || $H_ROUTE_MODE == https ]] && printf httplog || printf tcplog)"
    [[ $H_LOG != errors ]] || printf '    option dontlog-normal\n'
    printf '    option clitcpka\n    option srvtcpka\n    retries %d\n    option redispatch\n' "$((10#$H_RETRIES))"
    printf '    timeout connect %ds\n    timeout client %ds\n    timeout server %ds\n    timeout queue %ds\n    timeout check %ds\n' "$((10#$H_CONNECT))" "$((10#$H_IDLE))" "$((10#$H_IDLE))" "$((10#$H_QUEUE))" "$((10#$H_CHECK_TIMEOUT))"
    ((10#$H_FIN == 0)) || printf '    timeout client-fin %ds\n    timeout server-fin %ds\n' "$((10#$H_FIN))" "$((10#$H_FIN))"
    ((10#$H_TUNNEL == 0)) || printf '    timeout tunnel %ds\n' "$((10#$H_TUNNEL))"
    gtm_haproxy_frontend || return 1
    printf 'backend destinations\n    balance %s\n' "$algorithm"
    [[ $algorithm != source ]] || printf '    hash-type consistent\n'
    gtm_haproxy_servers 0 || return 1
    gtm_haproxy_route_backends
}

gtm_haproxy_servers() {
    local selected=${1:-0} target index=0
    local -a targets=()
    if [[ $H_STICK == source && $selected == 0 && $R_TARGETS == *,* ]]; then
        printf '    stick-table type ipv6 size %d expire %ds\n    stick on src\n' "$((10#$H_STICK_SIZE))" "$((10#$H_STICK_EXPIRE))"
    fi
    if [[ $H_CHECK_MODE == http ]]; then
        printf '    option httpchk\n    http-check send meth GET uri %s ver HTTP/1.1 hdr Host %s\n    http-check expect status %d\n' "$H_CHECK_PATH" "$H_CHECK_HOST" "$((10#$H_CHECK_STATUS))"
    fi
    IFS=, read -r -a targets <<< "$R_TARGETS"
    for target in "${targets[@]}"; do
        gtm_target "$target" || return 1; ((index+=1))
        ((selected==0 || index==10#$selected)) || continue
        printf '    server target%d %s weight %d' "$index" "$(gtm_address "$EP_IP" "$EP_PORT")" "$EP_WEIGHT"
        if [[ $H_CHECK_MODE != off ]]; then
            printf ' check inter %ds fall %d rise %d' "$((10#$H_CHECK_INTERVAL))" "$((10#$H_CHECK_FALL))" "$((10#$H_CHECK_RISE))"
            ((10#$H_CHECK_PORT == 0)) || printf ' port %d' "$((10#$H_CHECK_PORT))"
        fi
        ((10#$H_SERVER_MAXCONN == 0)) || printf ' maxconn %d' "$((10#$H_SERVER_MAXCONN))"
        ((10#$H_SLOWSTART == 0)) || printf ' slowstart %ds' "$((10#$H_SLOWSTART))"
        case $H_PROXY in v1) printf ' send-proxy';; v2) printf ' send-proxy-v2';; esac
        [[ $R_STRATEGY != failover || $index -le 1 || $selected != 0 ]] || printf ' backup'
        printf '\n'
    done
}

gtm_haproxy_unit() {
    local bin=$1 config=$2 id=$3
    local limit=$((2*10#$H_MAXCONN+2048))
    # An omitted maxconn delegates sizing to HAProxy and the inherited service
    # descriptor budget. Do not replace that budget with a small artificial cap.
    ((10#$H_MAXCONN != 0)) || limit=1048576
    cat <<EOF
# GTM HAProxy master-worker v1
[Unit]
Description=Traffic Manager HAProxy $id
Wants=network-online.target
After=network-online.target
[Service]
Type=simple
ExecStart=$bin -W -db -f $config
ExecReload=$bin -c -f $config
ExecReload=/bin/kill -USR2 \$MAINPID
KillMode=mixed
KillSignal=SIGUSR1
TimeoutStopSec=30
Restart=on-failure
RestartSec=5
LimitNOFILE=$limit
NoNewPrivileges=yes
ProtectHome=yes
ProtectSystem=strict
ReadWritePaths=$GTM_RUN_DIR
PrivateTmp=yes
RestrictSUIDSGID=yes
[Install]
WantedBy=multi-user.target
EOF
}

# Only read-only commands are exposed. No TCP admin/stats listener is created.
gtm_haproxy_query() {
    local id=$1 query=$2 socket
    [[ $query == 'show info' || $query == 'show stat' ]] || return 1
    socket=$(gtm_haproxy_socket "$id") || return 1
    [[ -S $socket ]] || { gtm_error "HAProxy socket unavailable: $socket"; return 1; }
    gtm_need socat && gtm_need timeout || return 1
    printf '%s\n' "$query" | timeout 5 socat -T 3 - "UNIX-CONNECT:$socket"
}

gtm_haproxy_pid() {
    local report pid
    report=$(gtm_haproxy_query "$1" 'show info') || return 1
    pid=$(awk -F': *' '$1 == "Pid" {gsub("\r", "", $2); print $2; exit}' <<< "$report")
    [[ $pid =~ ^[1-9][0-9]*$ ]] || return 1
    printf '%s' "$pid"
}

gtm_haproxy_wait() {
    local id=$1 previous=${2:-} pid attempt
    for ((attempt=0; attempt<15; attempt++)); do
        if systemctl is-active --quiet "gtm-$id" && pid=$(gtm_haproxy_pid "$id" 2>/dev/null) && [[ $pid != "$previous" ]]; then return 0; fi
        sleep 0.2
    done
    gtm_error "HAProxy did not expose a new ready worker: $id. Check its journal."
}

gtm_haproxy_status() {
    local id=$1 output
    gtm_id "$id" || return 1
    printf 'HAProxy %s / on-demand status\n' "$id"
    output=$(gtm_haproxy_query "$id" 'show stat') || return 1
    [[ $output == '# pxname,svname,'* ]] || { gtm_error 'Unexpected HAProxy stats response.'; return 1; }
    awk -F, 'NR == 1 {sub(/^# */, "", $1); for (i=1; i<=NF; i++) col[$i]=i; next}
        $1 == "destinations" && $2 != "BACKEND" {printf "  %-12s %-10s sessions=%s queued=%s total=%s check=%s\n", $2, $(col["status"]), $(col["scur"]), $(col["qcur"]), $(col["stot"]), $(col["check_status"])}' <<< "$output"
    printf 'Check results describe the configured TCP/HTTP readiness probe, not a VPN handshake. Counters reset on reload.\n'
}

gtm_haproxy_settings() {
    local choice line original id options replacement result health_port_default
    local -a rows=()
    gtm_records || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENGINE == haproxy ]] || continue
        rows+=("$line"); printf '  [%d] %s / %s\n' "${#rows[@]}" "$R_ID" "$R_NAME"
    done
    ((${#rows[@]})) || { printf 'Create a HAProxy connection first.\n'; return; }
    gtm_read 'Connection row [0 cancels]: ' choice || return
    gtm_uint "$choice" 1 "${#rows[@]}" || return
    original=${rows[$((10#$choice-1))]}
    gtm_record_validate "$original" || return 1; id=$R_ID
    while true; do
        gtm_header "HAProxy / $id / Advanced Settings"
        printf '  Changes stay in this form until Save & apply.\n\n'
        gtm_option 1 'Reset defaults'
        gtm_option 2 'VPN preset' 'Long connections / fewer logs'
        gtm_option 3 Timeouts
        gtm_option 4 'Health checks'
        gtm_option 5 'Connection limits'
        gtm_option 6 'PROXY protocol / logs'
        gtm_option 7 'Server status'
        gtm_option 8 'Save & apply'
        gtm_option 9 'Remember client IP' "$H_STICK"
        gtm_option 0 Cancel
        gtm_read 'Choose: ' choice || return
        case $choice in
            1) gtm_haproxy_defaults;;
            2) H_IDLE=86400; H_LOG=errors;;
            3) gtm_default 'Connect timeout [1-300s]' H_CONNECT "$H_CONNECT" && gtm_default 'Idle timeout [10-604800s]' H_IDLE "$H_IDLE" && gtm_default 'Queue timeout [1-3600s]' H_QUEUE "$H_QUEUE" || return;;
            4)
                gtm_choose 'Health probe' "$H_CHECK_MODE" 'TCP connect' tcp 'HTTP readiness (separate port)' http || continue
                H_CHECK_MODE=$GTM_REPLY
                if [[ $H_CHECK_MODE == http ]]; then
                    printf '  Use a separate plain HTTP readiness port. Data traffic stays TCP passthrough.\n'
                    health_port_default=$H_CHECK_PORT
                    ((10#$health_port_default > 0)) || health_port_default=8080
                    gtm_default 'Readiness port [1-65535]' H_CHECK_PORT "$health_port_default" &&
                        gtm_default 'Readiness path' H_CHECK_PATH "$H_CHECK_PATH" &&
                        gtm_default 'Host header' H_CHECK_HOST "$H_CHECK_HOST" &&
                        gtm_default 'Expected status [200-599]' H_CHECK_STATUS "$H_CHECK_STATUS" || return
                else
                    gtm_default 'Check port [0 = service port]' H_CHECK_PORT "$H_CHECK_PORT" || return
                fi
                gtm_default 'Check interval [1-300s]' H_CHECK_INTERVAL "$H_CHECK_INTERVAL" && gtm_default 'Check timeout [1-300s]' H_CHECK_TIMEOUT "$H_CHECK_TIMEOUT" && gtm_default 'Failed checks before down [1-20]' H_CHECK_FALL "$H_CHECK_FALL" && gtm_default 'Successful checks before up [1-20]' H_CHECK_RISE "$H_CHECK_RISE" || return;;
            5) gtm_default 'Connection cap [0 = automatic; up to 1000000]' H_MAXCONN "$H_MAXCONN" && gtm_default 'Per-target cap [0 = no explicit cap]' H_SERVER_MAXCONN "$H_SERVER_MAXCONN" && gtm_default 'Slow start [0-3600s]' H_SLOWSTART "$H_SLOWSTART" || return;;
            6)
                printf '  PROXY adds a header. Enable it on the destination first; otherwise traffic breaks.\n  It passes client metadata; it does not preserve the network source address.\n'
                gtm_choose 'PROXY protocol' "$H_PROXY" Off off 'Version 1' v1 'Version 2' v2 || continue
                H_PROXY=$GTM_REPLY
                gtm_choose Logs "$H_LOG" Connections connections 'Errors only' errors Off off || continue
                H_LOG=$GTM_REPLY;;
            7) (gtm_haproxy_status "$id"); gtm_pause;;
            9)
                gtm_choose 'Client affinity' "$H_STICK" Off off 'Remember source IP (memory)' source || continue
                H_STICK=$GTM_REPLY
                [[ $H_STICK == off ]] || { gtm_default 'Maximum stored IPs [1024-1000000]' H_STICK_SIZE "$H_STICK_SIZE" && gtm_default 'Idle expiry [30-86400s]' H_STICK_EXPIRE "$H_STICK_EXPIRE"; } || return;;
            8) break;; 0) return;; *) continue;;
        esac
    done
    options=$(gtm_haproxy_options) || { gtm_error 'Invalid HAProxy values. Nothing was saved.'; return 1; }
    gtm_record_validate "$original" || return 1
    [[ $R_VERSION == 4 ]] || R_VERSION=2; R_OPTIONS=$options; replacement=$(gtm_record_emit) || return 1
    [[ $replacement != "$original" ]] || { printf 'No changes.\n'; return; }
    printf 'Apply TCP settings to %s. A unit/FD-limit upgrade or engine change requires restart; compatible config changes use verified worker reload.\n' "$id"
    gtm_confirm && gtm_prepare && gtm_lock || return
    if ! { gtm_load_records && gtm_replace_record "$original" "$replacement"; }; then gtm_unlock; return 1; fi
    gtm_commit; result=$?
    gtm_unlock; gtm_pause
    return "$result"
}

# BEGIN MODULE: realm_options
# Bounded Realm 2.x network options. Native transports remain separate adapters.
gtm_realm_defaults() {
    M_TCP_TIMEOUT=5; M_UDP_TIMEOUT=30; M_KEEPALIVE=15; M_PROBES=3
    M_SEND_PROXY=false; M_PROXY_VERSION=2; M_ACCEPT_PROXY=false; M_ACCEPT_TIMEOUT=5; M_LOG=warn
    M_SEND_MPTCP=false; M_ACCEPT_MPTCP=false; M_IPV6_ONLY=false
    M_LISTEN_TRANSPORT=plain; M_REMOTE_TRANSPORT=plain; M_WS_HOST=localhost; M_WS_PATH=/
}
gtm_realm_options_validate() {
    local input=$1 pair key value
    local -a pairs=()
    local -A seen=()
    gtm_realm_defaults
    [[ -n $input && $input != ';'* && $input != *';' && $input != *';;'* ]] || return 1
    IFS=';' read -r -a pairs <<< "$input"
    ((${#pairs[@]}<=16)) || return 1
    for pair in "${pairs[@]}"; do
        [[ $pair == *=* ]] || return 1
        key=${pair%%=*}; value=${pair#*=}
        [[ -n $value && ! ${seen[$key]+set} ]] || return 1; seen[$key]=1
        case $key in
            tcp_timeout) gtm_uint "$value" 1 300 || return 1; M_TCP_TIMEOUT=$value;;
            udp_timeout) gtm_uint "$value" 1 3600 || return 1; M_UDP_TIMEOUT=$value;;
            tcp_keepalive) gtm_uint "$value" 0 3600 || return 1; M_KEEPALIVE=$value;;
            tcp_keepalive_probe) gtm_uint "$value" 1 30 || return 1; M_PROBES=$value;;
            send_proxy) [[ $value == true || $value == false ]] || return 1; M_SEND_PROXY=$value;;
            send_proxy_version) [[ $value == 1 || $value == 2 ]] || return 1; M_PROXY_VERSION=$value;;
            accept_proxy) [[ $value == true || $value == false ]] || return 1; M_ACCEPT_PROXY=$value;;
            accept_proxy_timeout) gtm_uint "$value" 1 300 || return 1; M_ACCEPT_TIMEOUT=$value;;
            log) [[ $value =~ ^(off|error|warn|info|debug|trace)$ ]] || return 1; M_LOG=$value;;
            send_mptcp|accept_mptcp|ipv6_only)
                [[ $value == true || $value == false ]] || return 1
                case $key in send_mptcp) M_SEND_MPTCP=$value;; accept_mptcp) M_ACCEPT_MPTCP=$value;; ipv6_only) M_IPV6_ONLY=$value;; esac;;
            listen_transport|remote_transport)
                [[ $value == plain || $value == ws ]] || return 1
                if [[ $key == listen_transport ]]; then M_LISTEN_TRANSPORT=$value; else M_REMOTE_TRANSPORT=$value; fi;;
            ws_host) [[ $value =~ ^[a-zA-Z0-9]([a-zA-Z0-9.-]{0,251}[a-zA-Z0-9])?$ ]] || return 1; M_WS_HOST=$value;;
            ws_path) [[ $value =~ ^/[a-zA-Z0-9/_.~-]{0,127}$ ]] || return 1; M_WS_PATH=$value;;
            *) return 1;;
        esac
    done
}

gtm_realm_profile_validate() {
    [[ $M_IPV6_ONLY != true || $R_BIND == *:* ]] || return 1
    [[ $R_PROTO != udp || ( $M_SEND_MPTCP == false && $M_ACCEPT_MPTCP == false ) ]] || return 1
    [[ $R_PROTO == tcp || ( $M_LISTEN_TRANSPORT == plain && $M_REMOTE_TRANSPORT == plain ) ]] || return 1
}

gtm_realm_profile_preflight() {
    local version
    if [[ $M_SEND_MPTCP == true || $M_ACCEPT_MPTCP == true || $M_IPV6_ONLY == true || $M_LISTEN_TRANSPORT != plain || $M_REMOTE_TRANSPORT != plain ]]; then
        version=$(realm --version) || return 1
        [[ $version =~ ^[Rr]ealm[[:space:]]+2\.9\.6([[:space:]]|$) ]] || { gtm_error 'Extended Realm profiles require the pinned Realm 2.9.6 binary.'; return 1; }
        if [[ $M_LISTEN_TRANSPORT != plain || $M_REMOTE_TRANSPORT != plain ]]; then
            [[ $version == *'[transport]'* ]] || { gtm_error 'This Realm binary was built without native transport support.'; return 1; }
        fi
    fi
    if [[ $M_SEND_MPTCP == true || $M_ACCEPT_MPTCP == true ]]; then
        [[ $(sysctl -n net.mptcp.enabled 2>/dev/null) == 1 ]] || { gtm_error 'MPTCP requires a compatible kernel with net.mptcp.enabled=1; no sysctl was changed.'; return 1; }
    fi
}

# BEGIN MODULE: metadata
# Optional display names. Callers hold the existing manager lock for all writes.
# Technical unit names, peer keys and tunnel addresses never change.
gtm_metadata_id() { [[ $1 =~ ^(gre-tun-([1-9][0-9]{0,2})|gtm-(frp|rathole)-(entrance|destination)-[a-zA-Z0-9_-]{1,32})$ ]]; }
gtm_metadata_load() {
    local file="$GTM_CONFIG_DIR/resource-names.tsv" line id fingerprint name extra
    local -A seen=()
    GTM_METADATA=()
    [[ -e $file || -L $file ]] || return 0
    [[ -f $file && ! -L $file && $(stat -c %s "$file") -le 131072 ]] || return 1
    while IFS= read -r line || [[ -n $line ]]; do
        extra=${line//[^$'\t']/}; ((${#extra}==2)) || return 1
        IFS=$'\t' read -r id fingerprint name <<< "$line"
        gtm_metadata_id "$id" && [[ $fingerprint =~ ^[a-f0-9]{64}$ ]] && gtm_name "$name" && [[ ! ${seen[$id]+set} ]] || return 1
        seen[$id]=1; GTM_METADATA+=("$line")
        ((${#GTM_METADATA[@]}<=512)) || return 1
    done < "$file"
}
gtm_metadata_save() {
    local file="$GTM_CONFIG_DIR/resource-names.tsv" tmp
    tmp=$(mktemp "$GTM_CONFIG_DIR/names.XXXXXX") || return 1
    if ((${#GTM_METADATA[@]})); then printf '%s\n' "${GTM_METADATA[@]}" > "$tmp" || { rm -f "$tmp"; return 1; }; fi
    if [[ -f $file ]]; then
        [[ ! -L $file.bak && ( ! -e $file.bak || -f $file.bak ) ]] && cp -p "$file" "$file.bak" || { rm -f "$tmp"; return 1; }
    fi
    chmod 600 "$tmp" && mv "$tmp" "$file" || { rm -f "$tmp"; return 1; }
}
gtm_metadata_forget() {
    local id=$1 line
    local -a kept=()
    gtm_metadata_load || return 1
    for line in "${GTM_METADATA[@]}"; do [[ ${line%%$'\t'*} == "$id" ]] || kept+=("$line"); done
    ((${#kept[@]}!=${#GTM_METADATA[@]})) || return 0
    GTM_METADATA=("${kept[@]}"); gtm_metadata_save
}
gtm_metadata_rename() {
    local id=$1 revision=$2 name=$3 file="$GTM_SERVICE_DIR/$1.service" unit_hash row_hash='-' line existing='' hash
    local -a kept=()
    gtm_metadata_id "$id" && [[ $revision =~ ^[a-f0-9]{64}:([a-f0-9]{64}|-)$ ]] && { [[ $name == - ]] || gtm_name "$name"; } || return 1
    [[ -f $file && ! -L $file ]] && gtm_metadata_load || return 1
    unit_hash=$(sha256sum "$file") || return 1; unit_hash=${unit_hash%% *}
    for line in "${GTM_METADATA[@]}"; do
        if [[ ${line%%$'\t'*} == "$id" ]]; then existing=$line; else kept+=("$line"); fi
    done
    if [[ -n $existing ]]; then hash=$(printf '%s' "$existing" | sha256sum) || return 1; row_hash=${hash%% *}; fi
    [[ $revision == "$unit_hash:$row_hash" ]] || { gtm_error 'Display name changed; refresh and try again.'; return 1; }
    [[ $name == - ]] || kept+=("$id"$'\t'"$unit_hash"$'\t'"$name")
    ((${#kept[@]}<=512)) || return 1
    GTM_METADATA=("${kept[@]}"); gtm_metadata_save
}

# BEGIN MODULE: state
# Versioned records: v1 has 12 fields, v2 appends validated HAProxy options.
# id name engine protocol bind port strategy enabled snat interface targets version
gtm_record_validate() {
    local line=$1 fields target count=0 family=4 key bind_key
    local -A seen_targets=()
    [[ $line != *$'\r'* && $line != *$'\n'* ]] || return 1
    fields=${line//[^$'\t']/}
    (( ${#fields} == 11 || ${#fields} == 12 || ${#fields} == 13 )) || return 1
    IFS=$'\t' read -r R_ID R_NAME R_ENGINE R_PROTO R_BIND R_PORT R_STRATEGY R_ENABLED R_SNAT R_IFACE R_TARGETS R_VERSION R_OPTIONS R_ROUTING <<< "$line"
    gtm_haproxy_defaults; gtm_realm_defaults; gtm_routing_defaults
    if (( ${#fields} == 11 )); then [[ $R_VERSION == 1 ]] || return 1
    elif (( ${#fields} == 13 )) && [[ $R_VERSION == 4 && $R_ENGINE == haproxy ]]; then
        gtm_haproxy_options_validate "$R_OPTIONS" && gtm_routing_validate "$R_ROUTING" || return 1
    elif (( ${#fields} == 12 )) && [[ $R_VERSION == 2 && $R_ENGINE == haproxy ]]; then gtm_haproxy_options_validate "$R_OPTIONS" || return 1
    elif (( ${#fields} == 12 )) && [[ $R_VERSION == 3 && $R_ENGINE == realm ]]; then gtm_realm_options_validate "$R_OPTIONS" || return 1
    else return 1; fi
    gtm_id "$R_ID" && gtm_name "$R_NAME" && gtm_ip "$R_BIND" && gtm_port_span "$R_PORT" && gtm_iface "$R_IFACE" || return 1
    R_FIRST=$PS_FIRST R_LAST=$PS_LAST
    [[ $R_ENABLED =~ ^[01]$ && $R_SNAT =~ ^(masquerade|preserve)$ ]] || return 1
    [[ $R_ENGINE =~ ^(iptables|nftables|realm|haproxy)$ && $R_PROTO =~ ^(tcp|udp|both)$ ]] || return 1
    # Port ranges are one kernel rule; relays keep one record per port.
    (( R_FIRST == R_LAST )) || [[ $R_ENGINE == iptables || $R_ENGINE == nftables ]] || return 1
    [[ $R_STRATEGY =~ ^(single|random|roundrobin|leastconn|source|failover)$ ]] || return 1
    [[ $R_ENGINE != haproxy || $R_STRATEGY != failover || $H_CHECK_MODE != off ]] || return 1
    [[ $R_TARGETS != ,* && $R_TARGETS != *, && $R_TARGETS != *,,* ]] || return 1
    [[ $R_BIND == *:* ]] && family=6
    gtm_key_of "$R_BIND" || return 1
    bind_key=$GTM_KEY
    local -a targets
    IFS=, read -r -a targets <<< "$R_TARGETS"
    (( ${#targets[@]} >= 1 && ${#targets[@]} <= 32 )) || return 1
    for target in "${targets[@]}"; do
        gtm_target "$target" || return 1
        if [[ $R_ENGINE == haproxy && $H_CHECK_MODE == http ]] && ((10#$EP_PORT == 10#$H_CHECK_PORT)); then
            gtm_error 'HTTP readiness needs a port different from every traffic destination port.'; return 1
        fi
        # A range maps one-to-one (same length) or every port to one remote port.
        if (( EP_LAST != EP_PORT )); then
            (( R_LAST > R_FIRST && EP_LAST - EP_PORT == R_LAST - R_FIRST )) || return 1
            # iptables keeps the original port only; shifted ranges need nftables.
            [[ $R_ENGINE != iptables ]] || (( EP_PORT == R_FIRST )) || return 1
        fi
        if ((EP_HOST)); then
            # Routing rules name destinations by position; names expand to many.
            [[ $R_VERSION != 4 ]] || return 1
            key="$EP_IP:$EP_PORT"
        else
            gtm_key_of "$EP_IP" || return 1
            key="$GTM_KEY:$EP_PORT"
            # A forward back to its own listener loops or hijacks the relay's socket.
            [[ $GTM_KEY != "$bind_key" ]] || (( EP_LAST < R_FIRST || EP_PORT > R_LAST )) || return 1
            if [[ $R_ENGINE == iptables || $R_ENGINE == nftables ]]; then
                # An unspecified kernel bind matches every local address of its family.
                if (( family == 6 )); then [[ $EP_IP == *:* ]] || return 1; else [[ $EP_IP != *:* ]] || return 1; fi
            fi
        fi
        [[ ! ${seen_targets[$key]+set} ]] || return 1
        seen_targets[$key]=1
        ((count+=1))
    done
    [[ $R_STRATEGY != single || $count == 1 ]] || return 1
    case $R_ENGINE in
        iptables) [[ $R_STRATEGY == single || $R_STRATEGY == random ]] || return 1 ;;
        nftables) [[ $R_STRATEGY =~ ^(single|random|roundrobin|source)$ ]] || return 1 ;;
        realm) [[ $R_STRATEGY == single || $R_STRATEGY == roundrobin || $R_STRATEGY == source ]] && gtm_realm_profile_validate || return 1 ;;
        haproxy) [[ $R_PROTO == tcp && $R_STRATEGY =~ ^(single|roundrobin|leastconn|source|failover)$ ]] || return 1 ;;
    esac
}

gtm_load_records() {
    local source=${1:-$GTM_STATE} line other
    GTM_RECORDS=()
    # Only an absent default state means a new installation. Never reconcile an
    # unreadable file, directory or dangling link as an empty desired state.
    if [[ ! -e $source && ! -L $source && $# == 0 ]]; then return 0; fi
    [[ -f $source && -r $source ]] || { gtm_error "State file is missing, unreadable or not a regular file: $source"; return 1; }
    local -A ids=() listeners=()
    local -a spans=()
    local port iface id bind_key entry span first last
    while IFS= read -r line || [[ -n $line ]]; do
        [[ -z $line || $line == '#'* ]] && continue
        gtm_record_validate "$line" || { gtm_error "Invalid connection record in $source"; return 1; }
        id=$R_ID; iface=$R_IFACE; first=$R_FIRST; last=$R_LAST
        [[ ! ${ids[$id]+set} ]] || { gtm_error "Duplicate ID: $id"; return 1; }; ids[$id]=1
        GTM_RECORDS+=("$line")
        [[ $R_ENABLED == 1 ]] || continue
        gtm_key_of "$R_BIND" || return 1
        bind_key=$GTM_KEY
        # Single ports are indexed by port and ranges kept apart, so loading stays
        # linear in the number of records plus the ports of range records.
        for span in "${spans[@]}"; do
            read -r port entry <<< "$span"
            (( first > ${entry%%/*} || last < port )) && continue
            gtm_listener_clash "${entry#*/}" || return 1
        done
        for ((port=first; port<=last; port++)); do
            for entry in ${listeners[$port]-}; do gtm_listener_clash "$entry" || return 1; done
        done
        entry="$id/$R_PROTO/$bind_key/$R_ENGINE/$iface"
        if (( first == last )); then listeners[$first]+="${listeners[$first]:+ }$entry"
        else spans+=("$first $last/$entry"); fi
    done < "$source"
}

# Rejects ambiguous listeners across engines, wildcard binds and interfaces.
# Uses the current record's R_PROTO/R_ENGINE, bind_key, iface and id.
gtm_listener_clash() {
    local O_ID O_PROTO O_KEY O_ENGINE O_IFACE
    IFS=/ read -r O_ID O_PROTO O_KEY O_ENGINE O_IFACE <<< "$1"
    [[ $R_PROTO == both || $O_PROTO == both || $R_PROTO == "$O_PROTO" ]] || return 0
    [[ $bind_key == "$O_KEY" ]] || gtm_wildcard_key "$bind_key" || gtm_wildcard_key "$O_KEY" || return 0
    # Relays bind sockets, not entrance interfaces. Only kernel rules can
    # safely distinguish identical listeners on two explicit interfaces.
    if [[ $R_ENGINE =~ ^(iptables|nftables)$ && $O_ENGINE =~ ^(iptables|nftables)$ ]]; then
        # Kernel rules are family-specific: IPv4 and IPv6 listeners never overlap.
        [[ $bind_key == *.* && $O_KEY != *.* || $bind_key != *.* && $O_KEY == *.* ]] && return 0
        [[ $iface == any || $O_IFACE == any || $iface == "$O_IFACE" ]] || return 0
    fi
    gtm_error "Listener conflicts: $id and $O_ID"
}

gtm_new_id() {
    local line id maximum=0 value serial
    if [[ -r $GTM_CONFIG_DIR/id-counter ]]; then
        IFS= read -r serial < "$GTM_CONFIG_DIR/id-counter" || return 1
        gtm_uint "$serial" 0 999999 || { gtm_error 'Invalid ID allocation counter.'; return 1; }
        maximum=$((10#$serial))
    fi
    for line in "${GTM_RECORDS[@]}"; do
        id=${line%%$'\t'*}; value=${id#F}; value=$((10#$value))
        (( value > maximum )) && maximum=$value
    done
    (( maximum < 999999 )) || return 1
    printf 'F%06d' "$((maximum+1))"
}

gtm_write_records() {
    local dest=$1
    { printf '# Traffic Manager records v1/v2/v3/v4\n'; printf '%s\n' "${GTM_RECORDS[@]}"; } > "$dest"
}

gtm_record_emit() {
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s' "$R_ID" "$R_NAME" "$R_ENGINE" "$R_PROTO" "$R_BIND" "$R_PORT" "$R_STRATEGY" "$R_ENABLED" "$R_SNAT" "$R_IFACE" "$R_TARGETS" "$R_VERSION"
    [[ $R_VERSION == 1 ]] || printf '\t%s' "$R_OPTIONS"
    [[ $R_VERSION != 4 ]] || printf '\t%s' "$R_ROUTING"
    return 0
}

# Caller reloads under lock. Refuse to overwrite another session's completed edit.
gtm_replace_record() {
    local expected=$1 replacement=$2 line found=0
    local id=${expected%%$'\t'*}
    local -a updated=()
    gtm_record_validate "$replacement" && [[ $R_ID == "$id" ]] || return 1
    for line in "${GTM_RECORDS[@]}"; do
        if [[ ${line%%$'\t'*} == "$id" ]]; then
            [[ $line == "$expected" ]] || { gtm_error 'Connection changed in another session. Reopen the editor.'; return 1; }
            updated+=("$replacement"); found=1
        else updated+=("$line"); fi
    done
    ((found)) || { gtm_error 'Connection was removed by another operation.'; return 1; }
    GTM_RECORDS=("${updated[@]}")
}

gtm_selection() {
    local value=$1 max=$2 token index
    local -a tokens=()
    GTM_SELECTED=()
    local -A seen=()
    read -r -a tokens <<< "$value"
    (( ${#tokens[@]} > 0 && ${#tokens[@]} <= max )) || return 1
    for token in "${tokens[@]}"; do
        gtm_uint "$token" 1 "$max" || return 1
        index=$((10#$token-1))
        [[ ${seen[$index]+set} ]] && continue
        seen[$index]=1; GTM_SELECTED+=("$index")
    done
}

gtm_install_runner() {
    local func tmp
    mkdir -p "${GTM_RUNTIME%/*}" || return 1
    tmp=$(mktemp "${GTM_RUNTIME}.XXXXXX") || return 1
    {
        printf '#!/usr/bin/env bash\n# Generated Traffic Manager kernel reconciler.\n'
        printf 'GTM_CONFIG_DIR=%q\nGTM_RUN_DIR=%q\nGTM_SERVICE_DIR=%q\nGTM_RUNTIME=%q\n' "$GTM_CONFIG_DIR" "$GTM_RUN_DIR" "$GTM_SERVICE_DIR" "$GTM_RUNTIME"
        declare -p GTM_VERSION GTM_SPAN_MAX GTM_DNS_MAX GTM_DNS_UNIT GTM_SYSDNS_UNIT
        while IFS= read -r func; do declare -f "$func"; done < <(compgen -A function gtm_)
        printf '\ngtm_paths\nif [[ ${1:-} == --dns-refresh ]]; then gtm_dns_refresh > /dev/null; exit $?; fi\ngtm_prepare && gtm_lock || exit 1\ngtm_kernel_apply\nresult=$?\ngtm_unlock\nexit "$result"\n'
    } > "$tmp"
    bash -n "$tmp" && chmod 700 "$tmp" && mv "$tmp" "$GTM_RUNTIME" || { rm -f "$tmp"; return 1; }
    cat > "$GTM_SERVICE_DIR/gre-manager-forwarding.service" <<EOF
[Unit]
Description=Traffic Manager owned kernel forwarding rules
Wants=network-online.target
After=network-online.target
[Service]
Type=oneshot
ExecStart=$GTM_RUNTIME
RemainAfterExit=yes
[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload && systemctl enable gre-manager-forwarding.service || return 1
}

# Keep the newest automatic forwarding restore points. Only exact generated names
# are considered; cleanup/tuning/legacy backups and manual files are never touched.
# GTM_RESTORE_POINTS=0 keeps every restore point.
gtm_prune_restore_points() {
    local keep=${GTM_RESTORE_POINTS:-100} file index
    local -a points=()
    gtm_uint "$keep" 0 100000 || { gtm_error 'GTM_RESTORE_POINTS must be 0-100000.'; return 1; }
    ((10#$keep > 0)) || return 0
    mapfile -t points < <(gtm_history_points)
    for ((index=10#$keep; index < ${#points[@]}; index++)); do
        rm -f -- "${points[$index]}" || return 1
    done
}

# Caller holds the manager lock. Restore only owned resources on failure.
gtm_restore_point_path() {
    local counter="$GTM_CONFIG_DIR/restore-counter" serial previous=0 tmp stamp
    serial=$(date +%s%N) && [[ $serial =~ ^[0-8][0-9]{18}$ ]] || return 1
    if [[ -e $counter || -L $counter ]]; then
        [[ -f $counter && ! -L $counter ]] && IFS= read -r previous < "$counter" && [[ $previous =~ ^[0-8][0-9]{18}$ ]] || return 1
    fi
    ((10#$serial > 10#$previous)) || serial=$((10#$previous + 1))
    stamp=$(date -u -d "@$((10#$serial / 1000000000))" +%Y%m%dT%H%M%S) || return 1
    tmp=$(mktemp "$counter.XXXXXX") || return 1
    printf '%019d\n' "$((10#$serial))" > "$tmp" && chmod 600 "$tmp" && mv "$tmp" "$counter" || { rm -f "$tmp"; return 1; }
    printf '%s/backups/%s-%019d-%d.tsv\n' "$GTM_CONFIG_DIR" "$stamp" "$((10#$serial))" "$$"
}

gtm_commit() {
    local backup candidate revision recovery=0
    candidate=$(mktemp "$GTM_CONFIG_DIR/state.XXXXXX") || return 1
    gtm_write_records "$candidate" && gtm_load_records "$candidate" || { rm -f "$candidate"; return 1; }
    if ! gtm_preflight; then rm -f "$candidate"; return 1; fi
    backup=$(gtm_restore_point_path) || { rm -f "$candidate"; return 1; }
    if [[ -f $GTM_STATE ]]; then
        cp "$GTM_STATE" "$backup" || { rm -f "$candidate"; return 1; }
    else printf '# Traffic Manager state v1\n' > "$backup" || { rm -f "$candidate"; return 1; }; fi
    chmod 600 "$candidate" "$backup" && mv "$candidate" "$GTM_STATE" || { rm -f "$candidate"; return 1; }
    if gtm_install_runner && gtm_kernel_apply && gtm_relays_apply; then
        gtm_dns_timer_sync || printf 'Warning: the domain refresh timer could not be updated.\n' >&2
        printf 'Saved and applied. Restore point: %s\n' "${backup##*/}"
        if [[ ${GTM_COMMIT_RECEIPT:-0} == 1 ]]; then
            revision=$(gtm_recovery_revision) && [[ $revision =~ ^[a-f0-9]{64}$ ]] || { gtm_error 'Saved, but the change receipt could not be read.'; return 1; }
            printf 'receipt\t%s\t%s\n' "${backup##*/}" "$revision"
        fi
        gtm_prune_restore_points || printf 'Warning: old restore points could not be pruned.\n' >&2
        return 0
    fi
    gtm_error 'Apply failed. Restoring the previous managed configuration.'
    candidate=$(mktemp "$GTM_CONFIG_DIR/recover.XXXXXX") || return 1
    cp "$backup" "$candidate" && chmod 600 "$candidate" && mv "$candidate" "$GTM_STATE" || { rm -f "$candidate"; return 1; }
    gtm_load_records || return 1
    gtm_kernel_apply || recovery=1
    gtm_relays_apply || recovery=1
    if ((recovery)); then
        gtm_error "Recovery needs attention. State restored at $GTM_STATE; check journalctl -u gre-manager-forwarding."
    fi
    return 1
}

# BEGIN MODULE: resolve
# Domain destinations. Records keep the DNS name; rules and relay configs use the
# last addresses that resolved, so the packet path never waits for DNS and a
# failed lookup keeps the previous addresses. A minute timer refreshes due names.
GTM_DNS_MAX=16
GTM_DNS_UNIT=gre-manager-dns

gtm_dns_paths() {
    GTM_DNS_CACHE="$GTM_CONFIG_DIR/dns-cache.tsv"
    GTM_DNS_POLICY="$GTM_CONFIG_DIR/dns-policy.tsv"
    GTM_DNS_PENDING="$GTM_CONFIG_DIR/dns-pending"
}

# Prints the usable addresses of NAME in FAMILY (4 or 6), sorted and unique.
# GTM_DNS_LOOKUP overrides the resolver in tests.
gtm_dns_lookup() {
    local name=$1 family=$2 address output database=ahostsv4 count=0
    local -A seen=()
    gtm_hostname "$name" && [[ $family == 4 || $family == 6 ]] || return 1
    [[ $family == 4 ]] || database=ahostsv6
    if [[ -n ${GTM_DNS_LOOKUP:-} ]]; then output=$("$GTM_DNS_LOOKUP" "$name" "$family") || return 1
    else output=$(timeout 5 getent "$database" "$name") || return 1; fi
    while read -r address _; do
        [[ -n $address && ! ${seen[$address]+set} ]] || continue
        if [[ $family == 4 ]]; then
            gtm_ipv4 "$address" && [[ $address != 0.* && $address != 127.* ]] || continue
            (( ${address%%.*} < 224 )) || continue
        else
            gtm_ipv6 "$address" && gtm_key_of "$address" || continue
            [[ $GTM_KEY != 0000000000000000000000000000000[01] && $GTM_KEY != ff* && $GTM_KEY != 00000000000000000000ffff* ]] || continue
        fi
        seen[$address]=1
        printf '%s\n' "$address"
        ((++count < GTM_DNS_MAX)) || break
    done <<< "$output" | sort -V
}

# Loads the cache once per process into GTM_DNS_ADDR[name/family] and
# GTM_DNS_CHECKED[name/family]; policies into GTM_DNS_EVERY and GTM_DNS_MODE.
gtm_dns_load() {
    local name family checked list every mode
    [[ ${GTM_DNS_LOADED:-} == "$GTM_CONFIG_DIR" ]] && return 0
    gtm_dns_paths
    declare -gA GTM_DNS_ADDR=() GTM_DNS_CHECKED=() GTM_DNS_EVERY=() GTM_DNS_MODE=()
    if [[ -f $GTM_DNS_CACHE && ! -L $GTM_DNS_CACHE ]]; then
        while IFS=$'\t' read -r name family checked list; do
            gtm_hostname "$name" && [[ $family =~ ^[46]$ && $checked =~ ^[0-9]{1,12}$ && $list =~ ^[0-9a-fA-F.:,]{1,1200}$ ]] || continue
            GTM_DNS_ADDR[$name/$family]=$list; GTM_DNS_CHECKED[$name/$family]=$checked
        done < "$GTM_DNS_CACHE"
    fi
    if [[ -f $GTM_DNS_POLICY && ! -L $GTM_DNS_POLICY ]]; then
        while IFS=$'\t' read -r name every mode; do
            gtm_hostname "$name" && gtm_uint "$every" 1 60 && [[ $mode == all || $mode == first ]] || continue
            GTM_DNS_EVERY[$name]=$((10#$every)); GTM_DNS_MODE[$name]=$mode
        done < "$GTM_DNS_POLICY"
    fi
    GTM_DNS_LOADED=$GTM_CONFIG_DIR
}

gtm_dns_save() {
    local key tmp
    gtm_dns_paths
    tmp=$(mktemp "$GTM_DNS_CACHE.XXXXXX") || return 1
    for key in "${!GTM_DNS_ADDR[@]}"; do
        printf '%s\t%s\t%s\t%s\n' "${key%/*}" "${key##*/}" "${GTM_DNS_CHECKED[$key]:-0}" "${GTM_DNS_ADDR[$key]}"
    done | sort > "$tmp" && chmod 600 "$tmp" && mv "$tmp" "$GTM_DNS_CACHE" || { rm -f "$tmp"; return 1; }
}

# Sets the refresh interval (minutes) and multi-address mode of NAME.
gtm_dns_policy_set() {
    local name=$1 every=$2 mode=$3 key tmp
    gtm_hostname "$name" && gtm_uint "$every" 1 60 && [[ $mode == all || $mode == first ]] || { gtm_error 'Invalid DNS policy.'; return 1; }
    gtm_dns_load || return 1
    GTM_DNS_EVERY[$name]=$((10#$every)); GTM_DNS_MODE[$name]=$mode
    tmp=$(mktemp "$GTM_DNS_POLICY.XXXXXX") || return 1
    for key in "${!GTM_DNS_EVERY[@]}"; do
        printf '%s\t%s\t%s\n' "$key" "${GTM_DNS_EVERY[$key]}" "${GTM_DNS_MODE[$key]:-all}"
    done | sort > "$tmp" && chmod 600 "$tmp" && mv "$tmp" "$GTM_DNS_POLICY" || { rm -f "$tmp"; return 1; }
    # Desired policy must be reconciled even when the address list is unchanged.
    [[ ! -L $GTM_DNS_PENDING && ( ! -e $GTM_DNS_PENDING || -f $GTM_DNS_PENDING ) ]] && : > "$GTM_DNS_PENDING"
}

# The address family a record's names resolve in: kernel rules follow the bind;
# relays use IPv4 unless they listen on IPv6 only.
gtm_dns_family() { if [[ $R_BIND == *:* ]]; then printf 6; else printf 4; fi; }

# Prints "name<TAB>family" for every enabled record with a DNS destination.
gtm_dns_needed() {
    local line target family
    local -a targets=()
    local -A seen=()
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 ]] || continue
        family=$(gtm_dns_family)
        IFS=, read -r -a targets <<< "$R_TARGETS"
        for target in "${targets[@]}"; do
            gtm_target "$target" && ((EP_HOST)) || continue
            [[ ${seen[$EP_IP/$family]+set} ]] && continue
            seen[$EP_IP/$family]=1
            printf '%s\t%s\n' "$EP_IP" "$family"
        done
    done
}

# Replaces R_TARGETS with literal destinations. A DNS name becomes its cached
# addresses (all, or the first with mode "first") with the name's port and weight.
# Returns 1 when no destination has an address yet; callers skip the record.
gtm_resolve_targets() {
    local target family list address port count=0 kept=0 skipped=''
    local -a targets=() out=() addresses=()
    local -A seen=()
    [[ $R_TARGETS =~ (^|,)[a-z0-9.-]*[a-z][a-z0-9.-]*: ]] || return 0
    gtm_dns_load || return 1
    family=$(gtm_dns_family)
    IFS=, read -r -a targets <<< "$R_TARGETS"
    for target in "${targets[@]}"; do
        gtm_target "$target" || return 1
        port=$(gtm_span_text "$EP_PORT" "$EP_LAST")
        if ((EP_HOST)); then
            list=${GTM_DNS_ADDR[$EP_IP/$family]-}
            [[ -n $list ]] || { skipped+=" $EP_IP"; continue; }
            IFS=, read -r -a addresses <<< "$list"
            [[ ${GTM_DNS_MODE[$EP_IP]:-all} == all ]] || addresses=("${addresses[0]}")
        else addresses=("$EP_IP"); fi
        for address in "${addresses[@]}"; do
            [[ ! ${seen[$address/$port]+set} ]] && ((count < 32)) || continue
            seen[$address/$port]=1; ((count+=1))
            out+=("$(gtm_address "$address" "$port")@$EP_WEIGHT")
        done
        ((kept+=1))
    done
    [[ -z $skipped ]] || printf 'Warning: %s has no resolved address yet for%s.\n' "$R_ID" "$skipped" >&2
    ((count)) || return 1
    R_TARGETS=$(IFS=,; printf '%s' "${out[*]}")
    # A name may resolve to fewer addresses than a balancing strategy needs.
    (( count > 1 )) || R_STRATEGY=single
    return 0
}

# Makes sure every DNS name in GTM_RECORDS has addresses; resolves new names now.
# A name that has never resolved fails the save so nothing silently forwards nowhere.
gtm_dns_ensure() {
    local name family list changed=0
    gtm_dns_load || return 1
    while IFS=$'\t' read -r name family; do
        [[ -n $name && -z ${GTM_DNS_ADDR[$name/$family]-} ]] || continue
        list=$(gtm_dns_lookup "$name" "$family" | paste -sd, -)
        [[ -n $list ]] || { gtm_error "Cannot resolve $name to an IPv$family address."; return 1; }
        GTM_DNS_ADDR[$name/$family]=$list; GTM_DNS_CHECKED[$name/$family]=$(date +%s); changed=1
    done < <(gtm_dns_needed)
    ((changed == 0)) || gtm_dns_save
}

# Timer entry point: re-resolves due names, keeps the last good answer on
# failure and reapplies rules and relays only when an address changed.
# Prints "name<TAB>family<TAB>status<TAB>addresses" per name.
gtm_dns_refresh() {
    local force=${1:-} name family list now due every changed=0 result=0 key attempted=0
    local -A needed=() previous_addr=() previous_checked=()
    gtm_prepare && gtm_lock || return 1
    if ! gtm_load_records; then gtm_unlock; return 1; fi
    GTM_DNS_LOADED=''; gtm_dns_load || { gtm_unlock; return 1; }
    for key in "${!GTM_DNS_ADDR[@]}"; do previous_addr[$key]=${GTM_DNS_ADDR[$key]}; previous_checked[$key]=${GTM_DNS_CHECKED[$key]}; done
    [[ ! -e $GTM_DNS_PENDING ]] || changed=1
    now=$(date +%s)
    while IFS=$'\t' read -r name family; do
        [[ -n $name ]] || continue
        needed[$name/$family]=1
        every=${GTM_DNS_EVERY[$name]:-5}
        due=$(( ${GTM_DNS_CHECKED[$name/$family]:-0} + every * 60 ))
        if [[ $force != --force ]] && (( now < due )) && [[ -n ${GTM_DNS_ADDR[$name/$family]-} ]]; then
            printf '%s\t%s\tcached\t%s\n' "$name" "$family" "${GTM_DNS_ADDR[$name/$family]}"; continue
        fi
        list=$(gtm_dns_lookup "$name" "$family" | paste -sd, -)
        if [[ -z $list ]]; then
            printf '%s\t%s\tfailed\t%s\n' "$name" "$family" "${GTM_DNS_ADDR[$name/$family]:--}"; continue
        fi
        GTM_DNS_CHECKED[$name/$family]=$now
        if [[ $list != "${GTM_DNS_ADDR[$name/$family]-}" ]]; then
            GTM_DNS_ADDR[$name/$family]=$list; changed=1
            printf '%s\t%s\tchanged\t%s\n' "$name" "$family" "$list"
        else printf '%s\t%s\tsame\t%s\n' "$name" "$family" "$list"; fi
    done < <(gtm_dns_needed)
    # Forget names no enabled record uses any more.
    for key in "${!GTM_DNS_ADDR[@]}"; do
        [[ ${needed[$key]+set} ]] || { unset 'GTM_DNS_ADDR[$key]' 'GTM_DNS_CHECKED[$key]'; }
    done
    if ((changed)); then
        [[ ! -L $GTM_DNS_PENDING && ( ! -e $GTM_DNS_PENDING || -f $GTM_DNS_PENDING ) ]] && : > "$GTM_DNS_PENDING" || result=1
        # Validate resolved endpoints as well as native syntax before publication.
        if ((result == 0)) && gtm_preflight && gtm_dns_save; then
            attempted=1
            gtm_kernel_apply && gtm_relays_apply || result=1
        else result=1; fi
        if ((result)); then
            GTM_DNS_ADDR=(); GTM_DNS_CHECKED=()
            for key in "${!previous_addr[@]}"; do GTM_DNS_ADDR[$key]=${previous_addr[$key]}; GTM_DNS_CHECKED[$key]=${previous_checked[$key]}; done
            gtm_dns_save || gtm_error 'DNS cache recovery failed; inspect dns-cache.tsv.'
            if ((attempted)); then
                gtm_kernel_apply || gtm_error 'DNS kernel recovery needs attention.'
                gtm_relays_apply || gtm_error 'DNS relay recovery needs attention.'
            fi
            gtm_error 'DNS reconciliation failed; it remains pending for retry.'
        else rm -f "$GTM_DNS_PENDING" || result=1; fi
    else gtm_dns_save || result=1; fi
    gtm_unlock
    return "$result"
}

# Prints the cache and, per enabled record with a DNS name, its resolved
# destinations: "name<TAB>family<TAB>checked<TAB>every<TAB>mode<TAB>addresses"
# and "record<TAB>id<TAB>targets".
gtm_dns_view() {
    local key line
    gtm_load_records && gtm_dns_load || return 1
    for key in "${!GTM_DNS_ADDR[@]}"; do
        printf 'name\t%s\t%s\t%s\t%s\t%s\t%s\n' "${key%/*}" "${key##*/}" "${GTM_DNS_CHECKED[$key]:-0}" "${GTM_DNS_EVERY[${key%/*}]:-5}" "${GTM_DNS_MODE[${key%/*}]:-all}" "${GTM_DNS_ADDR[$key]}"
    done | sort
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 && $R_TARGETS =~ (^|,)[a-z0-9.-]*[a-z][a-z0-9.-]*: ]] || continue
        if gtm_resolve_targets 2>/dev/null; then printf 'record\t%s\t%s\n' "$R_ID" "$R_TARGETS"; else printf 'record\t%s\t-\n' "$R_ID"; fi
    done
}

# Enables the refresh timer while a record uses a DNS name; removes it otherwise.
gtm_dns_timer_sync() {
    local service="$GTM_SERVICE_DIR/$GTM_DNS_UNIT.service" timer="$GTM_SERVICE_DIR/$GTM_DNS_UNIT.timer" wanted
    wanted=$(gtm_dns_needed) || return 1
    if [[ -z $wanted ]]; then
        [[ -e $timer ]] || return 0
        systemctl disable --now "$GTM_DNS_UNIT.timer" >/dev/null 2>&1 || true
        rm -f "$service" "$timer" && systemctl daemon-reload
        return
    fi
    [[ -e $timer ]] && return 0
    cat > "$service" <<EOF
[Unit]
Description=Traffic Manager domain destination refresh
After=network-online.target
[Service]
Type=oneshot
ExecStart=$GTM_RUNTIME --dns-refresh
EOF
    cat > "$timer" <<EOF
[Unit]
Description=Refresh Traffic Manager domain destinations every minute
[Timer]
OnBootSec=1min
OnUnitActiveSec=1min
AccuracySec=10s
[Install]
WantedBy=timers.target
EOF
    systemctl daemon-reload && systemctl enable --now "$GTM_DNS_UNIT.timer" >/dev/null
}

# BEGIN MODULE: portfw
# Port Forward Manager (h-zare-dev/iptables-forward-manager, "portfw"): read its
# saved rules for import and refuse entrance ports its active NAT already owns.
# Its files and tables are never changed here.
gtm_portfw_paths() {
    GTM_PORTFW_DIR=${GTM_PORTFW_DIR:-/etc/iptables-forward-manager}
    GTM_PORTFW_RULES="$GTM_PORTFW_DIR/rules.db"
}

# True while either portfw engine has NAT installed.
gtm_portfw_active() {
    command -v nft >/dev/null 2>&1 && nft list table ip ifm_portfw >/dev/null 2>&1 && return 0
    command -v iptables >/dev/null 2>&1 && iptables -w 2 -t nat -C PREROUTING -j IFM_DNAT >/dev/null 2>&1
}

# Prints "id<TAB>source<TAB>target<TAB>dest<TAB>proto" for each valid saved rule.
gtm_portfw_rules() {
    local line id source target dest proto count=0
    gtm_portfw_paths
    [[ -f $GTM_PORTFW_RULES && ! -L $GTM_PORTFW_RULES ]] || return 0
    while IFS= read -r line || [[ -n $line ]]; do
        [[ -n $line ]] || continue
        IFS='|' read -r id source target dest proto <<< "$line"
        [[ $id =~ ^[0-9]{1,6}$ && $source =~ ^[0-9,\ -]{1,1024}$ && $dest =~ ^[0-9,\ -]{1,1024}$ && $proto =~ ^(tcp|udp|both)$ ]] || continue
        gtm_ipv4 "$target" || gtm_hostname "$target" || continue
        printf '%s\t%s\t%s\t%s\t%s\n' "$id" "${source// /}" "$target" "${dest// /}" "$proto"
        ((++count < 1000)) || break
    done < "$GTM_PORTFW_RULES"
}

# Fails when an active portfw rule already forwards PORT (or span) for PROTOCOL.
gtm_portfw_listener_check() {
    local protocol=$1 bind=$2 port=$3 id source target dest proto word first last
    [[ $bind != *:* ]] || return 0
    gtm_portfw_paths
    [[ -f $GTM_PORTFW_RULES ]] && gtm_port_span "$port" || return 0
    first=$PS_FIRST last=$PS_LAST
    gtm_portfw_active || return 0
    while IFS=$'\t' read -r id source target dest proto; do
        [[ $protocol == both || $proto == both || $protocol == "$proto" ]] || continue
        for word in ${source//,/ }; do
            gtm_port_span "$word" || continue
            (( PS_LAST < first || PS_FIRST > last )) && continue
            gtm_error "Port Forward Manager (portfw) rule $id already forwards $word. Import it under Configuration, then remove it from portfw first."
            return 1
        done
    done < <(gtm_portfw_rules)
    return 0
}

# BEGIN MODULE: firewall
# Owned chains only. Never flush a host's ruleset or unrelated chains.
gtm_kernel_dependencies() {
    local line
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 ]] || continue
        case $R_ENGINE in
            iptables) gtm_need iptables && gtm_need iptables-restore || return 1
                [[ $R_BIND != *:* ]] || { gtm_need ip6tables && gtm_need ip6tables-restore || return 1; } ;;
            nftables) gtm_need nft || return 1 ;;
        esac
    done
}

# An additional IP with its own gateway uses source policy routing ("from X lookup
# N"). Forwarded replies are routed before un-DNAT restores X as their source, so
# they miss that rule and leave through the main gateway. Flows entering on such
# an address get a connection mark (mask 0xf000000), and owned fwmark rules at
# preference 31001-31015 route their replies through the same table.
# Sets GTM_RT_ADDRS ("family|address|mark|table|interface") and GTM_RT_RULES
# ("family|preference|mark|table"). Route lookups send no packets.
gtm_return_routes_detect() {
    local family probe address iface line table index=0
    local -a found=() names=()
    local -A marks=() seen=()
    GTM_RT_ADDRS=(); GTM_RT_RULES=()
    command -v ip >/dev/null 2>&1 || return 0
    for family in 4 6; do
        probe=1.1.1.1; [[ $family == 4 ]] || probe=2606:4700:4700::1111
        while read -r iface address; do
            address=${address%/*}
            line=$(ip -o -"$family" route get "$probe" from "$address" 2>/dev/null) || continue
            [[ $line =~ \ table\ ([A-Za-z0-9_.-]+)( |$) ]] || continue
            table=${BASH_REMATCH[1]}
            [[ $table != main && $table != local && $table != 254 && $table != 255 ]] || continue
            found+=("$family|$address|$table|$iface")
            [[ ${seen[$table]+set} ]] || { seen[$table]=1; names+=("$table"); }
        done < <(ip -o -"$family" address show scope global 2>/dev/null | awk '{print $2, $4}')
    done
    ((${#found[@]})) || return 0
    # Sorted table names keep marks stable across applies.
    while IFS= read -r table; do
        ((index < 15)) || { gtm_error "More than 15 source routing tables; return routing skips table $table."; continue; }
        index=$((index + 1)); marks[$table]=$(printf '0x%x' "$((index << 24))")
    done < <(printf '%s\n' "${names[@]}" | LC_ALL=C sort -u)
    seen=()
    for line in "${found[@]}"; do
        IFS='|' read -r family address table iface <<< "$line"
        [[ ${marks[$table]+set} ]] || continue
        GTM_RT_ADDRS+=("$family|$address|${marks[$table]}|$table|$iface")
        [[ ${seen[$family|$table]+set} ]] && continue
        seen[$family|$table]=1
        GTM_RT_RULES+=("$family|$((31000 + (${marks[$table]} >> 24)))|${marks[$table]}|$table")
    done
}

# Prints "address mark" for the current record's marked entrance addresses.
gtm_return_marks() {
    local wanted=$1 entry family address mark key=''
    gtm_wildcard "$R_BIND" || { gtm_key_of "$R_BIND" && key=$GTM_KEY; } || return 1
    for entry in ${GTM_RT_ADDRS[@]+"${GTM_RT_ADDRS[@]}"}; do
        IFS='|' read -r family address mark _ <<< "$entry"
        [[ $family == "$wanted" ]] || continue
        if [[ -n $key ]]; then gtm_key_of "$address" && [[ $GTM_KEY == "$key" ]] || continue; fi
        printf '%s %s\n' "$address" "$mark"
    done
}

# Prints each distinct reply mark of one family.
gtm_return_family_marks() {
    local entry family mark
    for entry in ${GTM_RT_RULES[@]+"${GTM_RT_RULES[@]}"}; do
        IFS='|' read -r family _ mark _ <<< "$entry"
        [[ -z $1 || $family == "$1" ]] && printf '%s\n' "$mark"
    done | LC_ALL=C sort -u
}

# Reconcile owned fwmark rules only; foreign rules are never touched.
gtm_return_rules_apply() {
    local family line entry pref mark table
    local -A wanted=()
    for entry in ${GTM_RT_RULES[@]+"${GTM_RT_RULES[@]}"}; do wanted[$entry]=1; done
    command -v ip >/dev/null 2>&1 || { ((${#wanted[@]} == 0)) && return 0; gtm_error 'ip is required for return routing.'; return 1; }
    for family in 4 6; do
        while IFS= read -r line; do
            [[ $line =~ ^(310(0[1-9]|1[0-5])):[[:space:]]+from\ all\ fwmark\ (0x[0-9a-f]+)/0xf000000\ lookup\ ([A-Za-z0-9_.-]+)[[:space:]]*$ ]] || continue
            pref=${BASH_REMATCH[1]}; mark=${BASH_REMATCH[3]}; table=${BASH_REMATCH[4]}
            entry="$family|$pref|$mark|$table"
            if [[ ${wanted[$entry]+set} ]]; then unset 'wanted[$entry]'; continue; fi
            ip -"$family" rule del pref "$pref" fwmark "$mark/0xf000000" lookup "$table" || return 1
        done < <(ip -"$family" rule show 2>/dev/null)
    done
    for entry in "${!wanted[@]}"; do
        IFS='|' read -r family pref mark table <<< "$entry"
        ip -"$family" rule add pref "$pref" fwmark "$mark/0xf000000" lookup "$table" || { gtm_error "Could not add the return route for table $table."; return 1; }
    done
}

# An unspecified bind (0.0.0.0 / ::) matches every address assigned to this host,
# including additional IPs. Explicit binds keep their exact destination match.
# Sets GTM_IPT_ENTRANCE / GTM_IPT_ORIGIN for the current record.
gtm_iptables_scope() {
    if gtm_wildcard "$R_BIND"; then
        GTM_IPT_ENTRANCE='-m addrtype --dst-type LOCAL'; GTM_IPT_ORIGIN=''
    else
        GTM_IPT_ENTRANCE="-d $R_BIND"; GTM_IPT_ORIGIN="--ctorigdst $R_BIND "
    fi
}

# Runtime-only destination exclusions written by the panel's health failover.
# The file lives in the run directory, which is cleared at boot, so every
# destination receives traffic again after a restart. An entry applies only
# while the record's destination list is exactly the one it was written for,
# and never removes every destination.
gtm_exclusions_file() { printf '%s/excluded.tsv' "$GTM_RUN_DIR"; }

# Sets GTM_ACTIVE to the 0-based indexes of the current record's destinations
# that receive new flows.
gtm_active_targets() {
    local count=$1 id saved list index file
    local -a parts=()
    local -A skip=()
    GTM_ACTIVE=()
    file=$(gtm_exclusions_file)
    if [[ -f $file && ! -L $file ]]; then
        while IFS=$'\t' read -r id saved list; do
            [[ $id == "$R_ID" && $saved == "$R_TARGETS" ]] || continue
            IFS=, read -r -a parts <<< "$list"
            for index in "${parts[@]}"; do [[ $index =~ ^[0-9]{1,2}$ ]] && skip[$((10#$index))]=1; done
        done < "$file"
    fi
    for ((index=1; index<=count; index++)); do [[ ${skip[$index]+set} ]] || GTM_ACTIVE+=("$((index-1))"); done
    ((${#GTM_ACTIVE[@]})) || for ((index=0; index<count; index++)); do GTM_ACTIVE+=("$index"); done
}

gtm_iptables_render() {
    local family=$1 table=$2 line proto target total remaining probability index address mark position listen remote
    local -a targets protocols
    local -A active=()
    printf '*%s\n' "$table"
    case $table in
        nat) printf ':GTM_PRE - [0:0]\n:GTM_POST - [0:0]\n-F GTM_PRE\n-F GTM_POST\n' ;;
        filter) printf ':GTM_FWD - [0:0]\n-F GTM_FWD\n' ;;
        mangle) printf ':GTM_MSS - [0:0]\n-F GTM_MSS\n:GTM_RTM - [0:0]\n-F GTM_RTM\n'
            # Replies of marked flows take their entrance address's routing table.
            while read -r mark; do
                printf -- '-A GTM_RTM -m conntrack --ctdir REPLY -m connmark --mark %s/0xf000000 -m comment --comment gtm-return -j MARK --set-xmark %s/0xf000000\n' "$mark" "$mark"
            done < <(gtm_return_family_marks "$family") ;;
    esac
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENGINE == iptables && $R_ENABLED == 1 ]] || continue
        if [[ $family == 4 ]]; then [[ $R_BIND != *:* ]] || continue; else [[ $R_BIND == *:* ]] || continue; fi
        gtm_resolve_targets || continue
        listen=$(gtm_span_text "$R_FIRST" "$R_LAST" :)
        IFS=, read -r -a targets <<< "$R_TARGETS"
        protocols=("$R_PROTO"); [[ $R_PROTO == both ]] && protocols=(tcp udp)
        gtm_iptables_scope || return 1
        # Excluded destinations get no new flows; their accept, NAT and MSS
        # rules stay so established flows continue if the destination answers.
        gtm_active_targets "${#targets[@]}"
        active=(); total=0
        for index in "${GTM_ACTIVE[@]}"; do active[$index]=1; gtm_target "${targets[$index]}" || return 1; ((total+=EP_WEIGHT)); done
        for proto in "${protocols[@]}"; do
            remaining=$total; index=0; position=0
            for target in "${targets[@]}"; do
                gtm_target "$target" || return 1
                remote=$(gtm_span_text "$EP_PORT" "$EP_LAST" :)
                if [[ $table == nat ]]; then
                    if ((index == 0)); then
                        while read -r address mark; do
                            printf -- '-A GTM_PRE -d %s' "$address"
                            [[ $R_IFACE == any ]] || printf ' -i %s' "$R_IFACE"
                            printf ' -p %s --dport %s -m comment --comment gtm-%s -j CONNMARK --set-xmark %s/0xf000000\n' "$proto" "$listen" "$R_ID" "$mark"
                        done < <(gtm_return_marks "$family")
                    fi
                    if [[ ${active[$index]+set} ]]; then
                        printf -- '-A GTM_PRE %s' "$GTM_IPT_ENTRANCE"
                        [[ $R_IFACE == any ]] || printf ' -i %s' "$R_IFACE"
                        printf ' -p %s --dport %s -m comment --comment gtm-%s' "$proto" "$listen" "$R_ID"
                        if (( position < ${#GTM_ACTIVE[@]}-1 )); then
                            probability=$(awk -v weight="$EP_WEIGHT" -v rest="$remaining" 'BEGIN {printf "%.10f", weight/rest}')
                            printf ' -m statistic --mode random --probability %s' "$probability"
                        fi
                        # A one-to-one range keeps each original port (validation
                        # allows only same-port ranges for iptables).
                        if (( EP_LAST > EP_PORT )); then printf ' -j DNAT --to-destination %s\n' "$EP_IP"
                        else printf ' -j DNAT --to-destination %s\n' "$(gtm_address "$EP_IP" "$EP_PORT")"; fi
                        ((remaining-=EP_WEIGHT)); ((position+=1))
                    fi
                    if [[ $R_SNAT == masquerade ]]; then
                        printf -- '-A GTM_POST -p %s -d %s --dport %s -m conntrack --ctstate DNAT --ctdir ORIGINAL %s--ctorigdstport %s -m comment --comment gtm-%s -j MASQUERADE\n' "$proto" "$EP_IP" "$remote" "$GTM_IPT_ORIGIN" "$listen" "$R_ID"
                    fi
                elif [[ $table == filter ]]; then
                    printf -- '-A GTM_FWD -p %s -d %s --dport %s -m conntrack --ctstate DNAT --ctdir ORIGINAL %s--ctorigdstport %s -m comment --comment gtm-%s -j ACCEPT\n' "$proto" "$EP_IP" "$remote" "$GTM_IPT_ORIGIN" "$listen" "$R_ID"
                    printf -- '-A GTM_FWD -p %s -s %s --sport %s -m conntrack --ctstate ESTABLISHED --ctdir REPLY %s--ctorigdstport %s -m comment --comment gtm-%s -j ACCEPT\n' "$proto" "$EP_IP" "$remote" "$GTM_IPT_ORIGIN" "$listen" "$R_ID"
                elif [[ $proto == tcp ]]; then
                    printf -- '-A GTM_MSS -p tcp -d %s --dport %s --tcp-flags SYN,RST SYN -m conntrack --ctstate DNAT --ctdir ORIGINAL %s--ctorigdstport %s -j TCPMSS --clamp-mss-to-pmtu\n' "$EP_IP" "$remote" "$GTM_IPT_ORIGIN" "$listen"
                fi
                ((index+=1))
            done
        done
    done
    printf 'COMMIT\n'
}

gtm_iptables_apply() {
    local family=$1 tool=iptables restore=iptables-restore file table chain hook
    [[ $family == 6 ]] && { tool=ip6tables; restore=ip6tables-restore; }
    command -v "$tool" >/dev/null 2>&1 || return 0
    file=$(mktemp "$GTM_RUN_DIR/iptables.XXXXXX") || return 1
    for table in nat filter mangle; do
        gtm_iptables_render "$family" "$table" > "$file" || { rm -f "$file"; return 1; }
        "$restore" -w 5 --noflush --test < "$file" && "$restore" -w 5 --noflush < "$file" || { rm -f "$file"; return 1; }
    done
    rm -f "$file"
    for table in nat filter mangle; do
        case $table in nat) local -a hooks=(PREROUTING:GTM_PRE POSTROUTING:GTM_POST);; filter) hooks=(FORWARD:GTM_FWD);; mangle) hooks=(FORWARD:GTM_MSS PREROUTING:GTM_RTM);; esac
        for hook in "${hooks[@]}"; do
            chain=${hook#*:}; hook=${hook%%:*}
            "$tool" -w 5 -t "$table" -C "$hook" -j "$chain" 2>/dev/null || "$tool" -w 5 -t "$table" -I "$hook" 1 -j "$chain" || return 1
        done
    done
}

# Prints the DNAT statement for the current target (EP_*) of record R_*:
# a single port, every port to one remote port, the same ports, or a shifted
# one-to-one range through an anonymous port map.
gtm_nft_dnat() {
    local family=$1 proto=$2 port sep='' address=$EP_IP
    if (( EP_LAST == EP_PORT )); then printf 'dnat %s to %s' "$family" "$(gtm_address "$EP_IP" "$EP_PORT")"; return; fi
    if (( EP_PORT == R_FIRST )); then printf 'dnat %s to %s' "$family" "$address"; return; fi
    printf 'dnat %s to %s dport map { ' "$family" "$proto"
    for ((port=R_FIRST; port<=R_LAST; port++)); do
        printf '%s%d : %s . %d' "$sep" "$port" "$address" "$((EP_PORT + port - R_FIRST))"; sep=', '
    done
    printf ' }'
}

gtm_nft_render() {
    local line family number proto target index total offset end entrance origin address mark listen remote created=0
    local -a targets protocols
    # One atomic batch replaces only our table. Deleting it (instead of flushing)
    # also removes balancing chains left by deleted records or removed targets.
    # Existing flows keep their conntrack NAT mappings.
    printf 'add table inet gre_manager\ndelete table inet gre_manager\n'
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENGINE == nftables && $R_ENABLED == 1 ]] || continue
        gtm_resolve_targets || continue
        listen=$(gtm_span_text "$R_FIRST" "$R_LAST")
        if ((created == 0)); then
            created=1
            printf 'add table inet gre_manager\n'
            printf 'add chain inet gre_manager pre { type nat hook prerouting priority -105; policy accept; }\n'
            printf 'add chain inet gre_manager post { type nat hook postrouting priority 95; policy accept; }\n'
            printf 'add chain inet gre_manager forward { type filter hook forward priority -5; policy accept; }\n'
            # Avoid reserved parser tokens; some releases reject quoted names too.
            printf 'add chain inet gre_manager gtm_mss { type filter hook forward priority -150; policy accept; }\n'
            # Replies of marked flows take their entrance address's routing table.
            while read -r mark; do
                ((created == 2)) || { created=2; printf 'add chain inet gre_manager rtmark { type filter hook prerouting priority -150; policy accept; }\n'; }
                printf 'add rule inet gre_manager rtmark ct direction reply ct mark and 0xf000000 == %s meta mark set meta mark and 0xf0ffffff or %s comment "gtm-return"\n' "$mark" "$mark"
            done < <(gtm_return_family_marks '')
        fi
        family=ip number=4; [[ $R_BIND == *:* ]] && { family=ip6; number=6; }
        # Unspecified binds match every local address (additional IPs included).
        if gtm_wildcard "$R_BIND"; then
            entrance='meta nfproto ipv4 fib daddr type local'; origin=''
            [[ $family == ip ]] || entrance='meta nfproto ipv6 fib daddr type local'
        else
            entrance="$family daddr $R_BIND"; origin="ct original $family daddr $R_BIND "
        fi
        IFS=, read -r -a targets <<< "$R_TARGETS"
        # Excluded destinations keep their chain (and their established flows)
        # but leave the distribution map until the panel restores them.
        gtm_active_targets "${#targets[@]}"
        total=0; for index in "${GTM_ACTIVE[@]}"; do gtm_target "${targets[$index]}" || return 1; ((total+=EP_WEIGHT)); done
        protocols=("$R_PROTO"); [[ $R_PROTO == both ]] && protocols=(tcp udp)
        for proto in "${protocols[@]}"; do
            if (( ${#targets[@]} > 1 )); then
                index=0
                for target in "${targets[@]}"; do
                    gtm_target "$target" || return 1
                    # The counter sees each flow's first packet only (NAT hook),
                    # so it counts new connections per destination since apply.
                    printf 'add chain inet gre_manager b_%s_%s_%d\n' "$R_ID" "$proto" "$index"
                    printf 'add rule inet gre_manager b_%s_%s_%d meta l4proto %s counter ' "$R_ID" "$proto" "$index" "$proto"
                    gtm_nft_dnat "$family" "$proto"; printf '\n'
                    ((index+=1))
                done
            fi
            while read -r address mark; do
                printf 'add rule inet gre_manager pre %s daddr %s' "$family" "$address"
                [[ $R_IFACE == any ]] || printf ' iifname "%s"' "$R_IFACE"
                printf ' %s dport %s ct mark set ct mark and 0xf0ffffff or %s comment "gtm-%s"\n' "$proto" "$listen" "$mark" "$R_ID"
            done < <(gtm_return_marks "$number")
            printf 'add rule inet gre_manager pre %s' "$entrance"
            [[ $R_IFACE == any ]] || printf ' iifname "%s"' "$R_IFACE"
            printf ' %s dport %s counter ' "$proto" "$listen"
            if (( ${#targets[@]} == 1 )); then
                gtm_target "${targets[0]}" || return 1
                gtm_nft_dnat "$family" "$proto"
            else
                case $R_STRATEGY in
                    source) printf 'jhash %s saddr mod %d seed 0 vmap { ' "$family" "$total";;
                    roundrobin) printf 'numgen inc mod %d vmap { ' "$total";;
                    *) printf 'numgen random mod %d vmap { ' "$total";;
                esac
                offset=0
                for index in "${GTM_ACTIVE[@]}"; do
                    gtm_target "${targets[$index]}" || return 1; (( offset > 0 )) && printf ', '
                    end=$((offset+EP_WEIGHT-1)); if (( offset == end )); then printf '%d' "$offset"; else printf '%d-%d' "$offset" "$end"; fi
                    printf ' : jump b_%s_%s_%d' "$R_ID" "$proto" "$index"; offset=$((end+1))
                done
                printf ' }'
            fi
            printf ' comment "gtm-%s"\n' "$R_ID"
            for target in "${targets[@]}"; do
                gtm_target "$target" || return 1
                remote=$(gtm_span_text "$EP_PORT" "$EP_LAST")
                if [[ $proto == tcp ]]; then
                    # Match only owned DNAT flows and reduce (never increase) an
                    # existing MSS using the outgoing route's advertised MSS.
                    printf 'add rule inet gre_manager gtm_mss meta l4proto tcp %s daddr %s tcp dport %s ct status dnat ct direction original %sct original proto-dst %s tcp flags & (syn | rst) == syn tcp option maxseg size set rt mtu counter comment "gtm-%s"\n' "$family" "$EP_IP" "$remote" "$origin" "$listen" "$R_ID"
                fi
                if [[ $R_SNAT == masquerade ]]; then
                    printf 'add rule inet gre_manager post meta l4proto %s %s daddr %s %s dport %s ct status dnat %sct original proto-dst %s counter masquerade comment "gtm-%s"\n' "$proto" "$family" "$EP_IP" "$proto" "$remote" "$origin" "$listen" "$R_ID"
                fi
                printf 'add rule inet gre_manager forward meta l4proto %s %s daddr %s %s dport %s ct status dnat %sct original proto-dst %s counter accept comment "gtm-%s"\n' "$proto" "$family" "$EP_IP" "$proto" "$remote" "$origin" "$listen" "$R_ID"
                printf 'add rule inet gre_manager forward meta l4proto %s %s saddr %s %s sport %s ct state established ct direction reply %sct original proto-dst %s counter accept comment "gtm-%s"\n' "$proto" "$family" "$EP_IP" "$proto" "$remote" "$origin" "$listen" "$R_ID"
            done
        done
    done
}

# Deletes only the tracked flows that one kernel forward DNATed to its own
# targets: original destination port (and address unless the bind is a
# wildcard) plus the target as reply source. Other host flows are untouched.
# An optional comma-separated list of 1-based destination positions limits the
# reset to those destinations (health failover clears flows of a dead one).
# Prints the original destination ports inside the current range record that
# have tracked flows answered by the current destination (EP_IP).
gtm_flows_ports() {
    local family=$1 proto=$2 line
    local -A seen=()
    while IFS= read -r line; do
        [[ $line =~ dport=([0-9]+) ]] || continue
        (( BASH_REMATCH[1] >= R_FIRST && BASH_REMATCH[1] <= R_LAST )) || continue
        [[ ${seen[${BASH_REMATCH[1]}]+set} ]] && continue
        seen[${BASH_REMATCH[1]}]=1; printf '%d\n' "${BASH_REMATCH[1]}"
    done < <(conntrack -L -f "$family" -p "$proto" --reply-src "$EP_IP" 2>/dev/null)
}

gtm_flows_reset() {
    local id=$1 only=${2:-} line proto target family output count total=0 matched=0 index port
    local -a targets protocols args
    gtm_id "$id" || { gtm_error 'Invalid connection ID.'; return 2; }
    [[ -z $only || $only =~ ^[0-9]{1,2}(,[0-9]{1,2}){0,31}$ ]] || { gtm_error 'Invalid destination list.'; return 2; }
    gtm_need conntrack || { printf 'Install conntrack (package conntrack) to reset tracked flows.\n' >&2; return 1; }
    gtm_load_records || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ID == "$id" ]] || continue
        matched=1
        [[ $R_ENGINE == nftables || $R_ENGINE == iptables ]] || { gtm_error 'Only kernel forwards keep conntrack mappings.'; return 1; }
        [[ $R_ENABLED == 1 ]] || { gtm_error 'Connection is disabled.'; return 1; }
        family=ipv4; [[ $R_BIND == *:* ]] && family=ipv6
        protocols=("$R_PROTO"); [[ $R_PROTO == both ]] && protocols=(tcp udp)
        gtm_resolve_targets || { gtm_error 'No resolved destination.'; return 1; }
        IFS=, read -r -a targets <<< "$R_TARGETS"
        for proto in "${protocols[@]}"; do
            index=0
            for target in "${targets[@]}"; do
                ((index+=1))
                [[ -z $only || ,$only, == *",$index,"* ]] || continue
                gtm_target "$target" || return 1
                local -a ports=("$R_FIRST")
                # conntrack filters one original port; a range record clears the
                # ports that currently have flows to this destination.
                (( R_LAST == R_FIRST )) || mapfile -t ports < <(gtm_flows_ports "$family" "$proto")
                for port in "${ports[@]}"; do
                    args=(-D -f "$family" -p "$proto" --orig-port-dst "$port" --reply-src "$EP_IP")
                    (( EP_LAST > EP_PORT )) || args+=(--reply-port-src "$EP_PORT")
                    gtm_wildcard "$R_BIND" || args+=(--orig-dst "$R_BIND")
                    # conntrack exits non-zero when nothing matched; the count is authoritative.
                    output=$(conntrack "${args[@]}" 2>&1 >/dev/null) || true
                    if [[ $output =~ ([0-9]+)\ flow\ entries\ have\ been\ deleted ]]; then
                        count=${BASH_REMATCH[1]}; total=$((total + count))
                    else
                        gtm_error "conntrack failed: ${output:0:200}"; return 1
                    fi
                done
            done
        done
        break
    done
    ((matched)) || { gtm_error 'Connection not found.'; return 1; }
    printf 'Cleared %d tracked flow(s) for %s; clients reconnect on their next packet.\n' "$total" "$id"
}

# Health failover: replaces one forward's runtime exclusion list ("-" clears it),
# reapplies owned kernel rules and clears tracked flows of newly excluded
# destinations so their clients reconnect to a live one. Caller locks.
gtm_forward_exclude() {
    local id=$1 list=$2 line matched=0 count index saved='' previous='' file tmp previous_targets previous_list
    local -a parts=() sorted=() fresh=()
    local -A seen=() before=()
    gtm_id "$id" && [[ $list == - || $list =~ ^[0-9]{1,2}(,[0-9]{1,2}){0,31}$ ]] || { gtm_error 'Invalid failover request.'; return 2; }
    gtm_load_records || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ID == "$id" ]] && { matched=1; break; }
    done
    ((matched)) || { gtm_error 'Connection not found.'; return 1; }
    [[ ( $R_ENGINE == nftables || $R_ENGINE == iptables ) && $R_ENABLED == 1 ]] || { gtm_error 'Failover applies to enabled kernel forwards.'; return 1; }
    # Positions refer to the resolved destinations (a DNS name may be several).
    gtm_resolve_targets || { gtm_error 'No resolved destination.'; return 1; }
    saved=$R_TARGETS
    IFS=, read -r -a parts <<< "$saved"; count=${#parts[@]}
    parts=()
    if [[ $list != - ]]; then
        IFS=, read -r -a parts <<< "$list"
        for index in "${parts[@]}"; do
            index=$((10#$index))
            ((index >= 1 && index <= count)) || { gtm_error 'Destination is not part of this connection.'; return 2; }
            [[ ${seen[$index]+set} ]] || { seen[$index]=1; sorted+=("$index"); }
        done
        ((${#sorted[@]} < count)) || { gtm_error 'At least one destination must keep receiving traffic.'; return 1; }
        mapfile -t sorted < <(printf '%s\n' "${sorted[@]}" | sort -n)
    fi
    file=$(gtm_exclusions_file)
    [[ ! -L $file ]] || return 1
    tmp=$(mktemp "$GTM_RUN_DIR/excluded.XXXXXX") || return 1
    if [[ -f $file ]]; then
        while IFS=$'\t' read -r line previous_targets previous_list; do
            if [[ $line == "$id" ]]; then
                [[ $previous_targets == "$saved" ]] && previous=$previous_list
                continue
            fi
            gtm_id "$line" && printf '%s\t%s\t%s\n' "$line" "$previous_targets" "$previous_list"
        done < "$file" > "$tmp"
    fi
    ((${#sorted[@]} == 0)) || printf '%s\t%s\t%s\n' "$id" "$saved" "$(IFS=,; printf '%s' "${sorted[*]}")" >> "$tmp"
    chmod 600 "$tmp" && mv "$tmp" "$file" || { rm -f "$tmp"; return 1; }
    gtm_kernel_apply || return 1
    IFS=, read -r -a parts <<< "$previous"
    for index in "${parts[@]}"; do before[$index]=1; done
    for index in "${sorted[@]}"; do [[ ${before[$index]+set} ]] || fresh+=("$index"); done
    if ((${#sorted[@]} == 0)); then
        printf 'All destinations of %s receive new flows again.\n' "$id"
    else
        printf 'Destinations %s of %s receive no new flows until they recover.\n' "$(IFS=,; printf '%s' "${sorted[*]}")" "$id"
    fi
    ((${#fresh[@]})) || return 0
    if command -v conntrack >/dev/null 2>&1; then
        gtm_flows_reset "$id" "$(IFS=,; printf '%s' "${fresh[*]}")" || printf 'Stale flows were kept; they expire with the conntrack timeout.\n'
    else
        printf 'Install conntrack to move existing clients off a dead destination at once.\n'
    fi
    return 0
}

gtm_kernel_apply() {
    local line v4=0 v6=0 ipt4=0 ipt6=0 nft=0 file
    gtm_load_records && gtm_kernel_dependencies || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 && ( $R_ENGINE == iptables || $R_ENGINE == nftables ) ]] || continue
        if [[ $R_BIND == *:* ]]; then v6=1; [[ $R_ENGINE == iptables ]] && ipt6=1
        else v4=1; [[ $R_ENGINE == iptables ]] && ipt4=1; fi
        [[ $R_ENGINE == nftables ]] && nft=1
    done
    GTM_RT_ADDRS=(); GTM_RT_RULES=()
    if (( v4 || v6 )); then gtm_return_routes_detect || return 1; fi
    # Also clear previously owned chains/tables after disabling/deleting records.
    if (( ipt4 )) || { command -v iptables >/dev/null && iptables -t nat -S GTM_PRE >/dev/null 2>&1; }; then gtm_iptables_apply 4 || return 1; fi
    if (( ipt6 )) || { command -v ip6tables >/dev/null && ip6tables -t nat -S GTM_PRE >/dev/null 2>&1; }; then gtm_iptables_apply 6 || return 1; fi
    if (( nft )) || { command -v nft >/dev/null && nft list table inet gre_manager >/dev/null 2>&1; }; then
        file=$(mktemp "$GTM_RUN_DIR/nft.XXXXXX") || return 1
        gtm_nft_render > "$file" && nft -c -f "$file" && nft -f "$file" || { rm -f "$file"; return 1; }
        rm -f "$file"
    fi
    gtm_return_rules_apply || return 1
    (( v4 == 0 )) || sysctl -w net.ipv4.ip_forward=1 || return 1
    # Do not silently disable RA on an IPv6 host. Require the operator's routing setup.
    if (( v6 )) && [[ $(sysctl -n net.ipv6.conf.all.forwarding) != 1 ]]; then
        gtm_error 'Enable IPv6 forwarding and preserve Router Advertisements where required, then apply again.'; return 1
    fi
}

# BEGIN MODULE: components
# Explicit engine maintenance. Never restart active tunnels during a binary update.
gtm_component_policy() {
    (($#==1)) && [[ $1 =~ ^(iptables|nftables|haproxy)$ ]] && gtm_need apt-cache || return 1
    LC_ALL=C apt-cache policy "$1"
}

# Stage every fixed binary before replacing any; keep previous binaries for recovery.
gtm_component_publish() (
    local source=$1 binary target staged backup result=0
    shift
    local -a names=("$@") published=() candidates=()
    local directory="$GTM_CONFIG_DIR/engine-backups"
    mkdir -p "$directory" && chmod 700 "$directory" || return 1
    backup=$(mktemp -d "$directory/update.XXXXXX") || return 1
    trap 'for staged in "${candidates[@]}"; do [[ ! -f $staged ]] || rm -f "$staged"; done' EXIT
    for binary in "${names[@]}"; do
        [[ $binary =~ ^(realm|frpc|frps|rathole)$ && -f $source/$binary && ! -L $source/$binary ]] || return 1
        target="/usr/local/bin/$binary"
        [[ ! -L $target && ( ! -e $target || -f $target ) ]] || return 1
        if [[ -e $target ]]; then cp -p "$target" "$backup/$binary" || return 1; fi
        staged=$(mktemp "/usr/local/bin/.gtm-engine-$binary.XXXXXX.tmp") || return 1
        candidates+=("$staged")
        install -m 755 "$source/$binary" "$staged" || return 1
        printf '%s\n' "$staged" > "$backup/$binary.staged" || return 1
    done
    for binary in "${names[@]}"; do
        IFS= read -r staged < "$backup/$binary.staged" || { result=1; break; }
        if mv -f "$staged" "/usr/local/bin/$binary"; then published+=("$binary"); else result=1; break; fi
    done
    if ((result)); then
        for binary in "${published[@]}"; do
            if [[ -f $backup/$binary ]]; then
                install -m 755 "$backup/$binary" "/usr/local/bin/$binary" || gtm_error "Partial engine recovery: restore $backup/$binary manually."
            else rm -f "/usr/local/bin/$binary" || gtm_error "Partial engine recovery: inspect /usr/local/bin/$binary."; fi
        done
        return 1
    fi
    for binary in "${names[@]}"; do rm -f "$backup/$binary.staged" || return 1; done
)

gtm_component_update() (
    set -o pipefail
    local component=$1 expected=${2:-} expected_peer=${3:-} actual binary current candidate package_version
    [[ $component =~ ^(iptables|nftables|haproxy|realm|frp|rathole)$ ]] && gtm_prepare && gtm_lock || return 1
    trap gtm_unlock EXIT
    case $component in
        iptables|nftables|haproxy)
            [[ $expected =~ ^[a-f0-9]{64}$ ]] || return 1
            actual=$(gtm_component_policy "$component" | sha256sum); actual=${actual%% *}
            [[ $actual == "$expected" ]] || { gtm_error 'Package metadata changed; check versions again.'; return 1; }
            candidate=$(gtm_component_policy "$component" | awk '$1 == "Candidate:" {print $2; exit}')
            [[ $candidate =~ ^[a-zA-Z0-9.+:~_-]+$ && $candidate != '(none)' ]] || return 1
            gtm_need dpkg && gtm_need dpkg-query || return 1
            package_version=$(dpkg-query -W -f='${Version}' "$component") && dpkg --compare-versions "$candidate" gt "$package_version" || { gtm_error 'No newer installed-package candidate is available.'; return 1; }
            # Respect existing package policy; use a no-start policy when absent.
            # No repositories, upstream PPAs or host firewall policies are added.
            GTM_PACKAGE_REFRESH=0 gtm_install_packages --only-upgrade "$component=$candidate";;
        *)
            binary=$component; [[ $component != frp ]] || binary=frpc
            current=$(command -v "$binary") || return 1
            [[ $current == "/usr/local/bin/$binary" ]] || { gtm_error 'This binary is externally managed; update it using its original installer.'; return 1; }
            [[ $expected =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}([-+~][a-zA-Z0-9.+~_-]{1,40})?$ ]] || return 1
            actual=$("$current" --version) || return 1
            if [[ $component == rathole && $actual == *'Build Version:'* ]]; then actual=$(awk '$1 == "Build" && $2 == "Version:" {print $3; exit}' <<< "$actual")
            elif [[ $actual =~ ([0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}([-+~][a-zA-Z0-9.+~_-]{1,40})?) ]]; then actual=${BASH_REMATCH[1]}; fi
            [[ $actual == "$expected" ]] || { gtm_error 'Engine changed; check versions again.'; return 1; }
            if [[ $component == frp ]]; then
                [[ $(command -v frps) == /usr/local/bin/frps && $expected_peer =~ ^[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}$ ]] || return 1
                actual=$(/usr/local/bin/frps --version) && [[ $actual == "$expected_peer" ]] || { gtm_error 'FRP server binary changed; check versions again.'; return 1; }
            fi
            gtm_confirm() { return 0; }
            gtm_install_component "$component" update;;
    esac
)

# BEGIN MODULE: relays
# Optional, explicitly selected services. The manager itself is not resident.
gtm_install_component() {
    local component=$1 mode=${2:-install} arch archive url sha tmp member candidate_version
    [[ $mode == install || $mode == update ]] || return 1
    if [[ $mode == install ]]; then case $component in
        iptables) command -v iptables >/dev/null 2>&1 && return 0 ;;
        nftables) command -v nft >/dev/null 2>&1 && return 0 ;;
        haproxy) command -v haproxy >/dev/null 2>&1 && command -v socat >/dev/null 2>&1 && return 0 ;;
        realm)
            if command -v realm >/dev/null 2>&1; then
                local installed_version
                installed_version=$(realm --version 2>/dev/null) || { gtm_error 'The installed realm command is not a supported network relay. No binary was replaced.'; return 1; }
                [[ $installed_version =~ ^[Rr]ealm[[:space:]]+2\. ]] || { gtm_error 'Expected Realm relay 2.x; check the existing realm command before continuing.'; return 1; }
                return 0
            fi ;;
        frp) command -v frpc >/dev/null 2>&1 && command -v frps >/dev/null 2>&1 && return 0 ;;
        rathole) if command -v rathole >/dev/null 2>&1; then gtm_rathole_binary; return $?; fi ;;
        *) return 1 ;;
    esac; fi
    gtm_root || return 1
    printf '\nInstall optional component: %s\n' "$component"
    gtm_confirm || return 1
    if [[ $component == rathole ]]; then gtm_rathole_download; return $?; fi
    case $component in
        iptables|nftables|haproxy)
            gtm_need apt-get || return 1
            local -a packages=("$component")
            [[ $component != haproxy ]] || packages+=(socat)
            gtm_install_packages "${packages[@]}" || return 1
            # HAProxy uses per-connection units, not the distribution's default unit.
            return 0 ;;
    esac
    gtm_need curl && gtm_need tar && gtm_need sha256sum && gtm_need install || return 1
    arch=$(uname -m)
    case $component:$arch in
        realm:x86_64) archive=realm-x86_64-unknown-linux-musl.tar.gz; sha=b1cc335547bea8bb2a88178bef12ec7f2363e36200e7ea1d4e1e67627929bf65 ;;
        realm:aarch64) archive=realm-aarch64-unknown-linux-musl.tar.gz; sha=f4c0318dd86854da483dcb7645b4f39cae2cc3f91c688fef969d53220b949488 ;;
        frp:x86_64) archive=frp_0.71.1_linux_amd64.tar.gz; sha=1d9875210972a5d1a62b2dc4c48df45ab0af05d3ca1b5e494a014428259df803 ;;
        frp:aarch64) archive=frp_0.71.1_linux_arm64.tar.gz; sha=8edf590b0c396fa42f9c147121a76af83cfc2002b08f5aef0ea1008c43482019 ;;
        *) gtm_error "Unsupported binary architecture: $arch"; return 1 ;;
    esac
    if [[ $component == realm ]]; then url="https://github.com/zhboner/realm/releases/download/v2.9.6/$archive"
    else url="https://github.com/fatedier/frp/releases/download/v0.71.1/$archive"; fi
    tmp=$(mktemp -d "$GTM_RUN_DIR/download.XXXXXX") || return 1
    if ! curl --proto '=https' --tlsv1.2 -fL --connect-timeout 15 --max-time 180 "$url" -o "$tmp/archive.tar.gz"; then rm -rf "$tmp"; return 1; fi
    if ! printf '%s  %s\n' "$sha" "$tmp/archive.tar.gz" | sha256sum -c -; then rm -rf "$tmp"; return 1; fi
    tar -xzf "$tmp/archive.tar.gz" -C "$tmp" || { rm -rf "$tmp"; return 1; }
    if [[ $component == realm ]]; then
        candidate_version=$("$tmp/realm" --version) && [[ $candidate_version =~ ^[Rr]ealm[[:space:]]+2\.9\.6([[:space:]]|$) ]] && gtm_component_publish "$tmp" realm || { rm -rf "$tmp"; return 1; }
    else
        member=${archive%.tar.gz}
        [[ $("$tmp/$member/frpc" --version) == 0.71.1 && $("$tmp/$member/frps" --version) == 0.71.1 ]] && gtm_component_publish "$tmp/$member" frpc frps || { rm -rf "$tmp"; return 1; }
    fi
    rm -rf "$tmp"
}

# Do not start distribution services just because optional binaries are installed.
# An existing local policy is respected. This temporary policy is removed on exit.
gtm_install_packages() (
    local owned=0 policy=/usr/sbin/policy-rc.d package had_haproxy=0
    command -v haproxy >/dev/null 2>&1 && had_haproxy=1
    if [[ ! -e $policy && ! -L $policy ]]; then
        if (set -o noclobber; printf '#!/bin/sh\n# GTM temporary install policy\nexit 101\n' > "$policy") 2>/dev/null; then
            owned=1; chmod 755 "$policy" || exit 1
        fi
    fi
    trap 'if ((owned)); then rm -f "$policy"; fi' EXIT
    if [[ ${GTM_PACKAGE_REFRESH:-1} != 0 ]]; then apt-get update || exit 1; fi
    apt-get install -y "$@" || exit 1
    if ((had_haproxy==0)); then
        for package in "$@"; do
            [[ $package != haproxy ]] || systemctl disable --now haproxy.service || exit 1
        done
    fi
)

gtm_realm_render() {
    local target remote index=0 weights='' algorithm=roundrobin
    local -a targets
    IFS=, read -r -a targets <<< "$R_TARGETS"
    [[ $R_STRATEGY == source ]] && algorithm=iphash
    printf '[log]\nlevel = "%s"\noutput = "stdout"\n\n[network]\nno_tcp = %s\nuse_udp = %s\n' "$M_LOG" "$([[ $R_PROTO == udp ]] && echo true || echo false)" "$([[ $R_PROTO == tcp ]] && echo false || echo true)"
    printf 'tcp_timeout = %d\nudp_timeout = %d\ntcp_keepalive = %d\n' "$((10#$M_TCP_TIMEOUT))" "$((10#$M_UDP_TIMEOUT))" "$((10#$M_KEEPALIVE))"
    if [[ $R_VERSION == 3 ]]; then
        printf 'tcp_keepalive_probe = %d\nsend_proxy = %s\nsend_proxy_version = %d\naccept_proxy = %s\naccept_proxy_timeout = %d\n' "$((10#$M_PROBES))" "$M_SEND_PROXY" "$M_PROXY_VERSION" "$M_ACCEPT_PROXY" "$((10#$M_ACCEPT_TIMEOUT))"
    fi
    [[ $M_SEND_MPTCP != true ]] || printf 'send_mptcp = true\n'
    [[ $M_ACCEPT_MPTCP != true ]] || printf 'accept_mptcp = true\n'
    [[ $M_IPV6_ONLY != true ]] || printf 'ipv6_only = true\n'
    printf '\n[[endpoints]]\nlisten = "%s"\n' "$(gtm_address "$R_BIND" "$((10#$R_PORT))")"
    [[ $M_LISTEN_TRANSPORT != ws ]] || printf 'listen_transport = "ws;host=%s;path=%s"\n' "$M_WS_HOST" "$M_WS_PATH"
    [[ $M_REMOTE_TRANSPORT != ws ]] || printf 'remote_transport = "ws;host=%s;path=%s"\n' "$M_WS_HOST" "$M_WS_PATH"
    for target in "${targets[@]}"; do
        gtm_target "$target" || return 1; remote=$(gtm_address "$EP_IP" "$EP_PORT")
        if (( index == 0 )); then printf 'remote = "%s"\n' "$remote"
        else (( index == 1 )) && printf 'extra_remotes = ['; (( index > 1 )) && printf ', '; printf '"%s"' "$remote"; fi
        weights+="${weights:+, }$EP_WEIGHT"; ((index+=1))
    done
    if (( index > 1 )); then printf ']\nbalance = "%s: %s"\n' "$algorithm" "$weights"; fi
}

gtm_relay_unit() {
    local bin=$1 config=$2 id=$3
    cat <<EOF
[Unit]
Description=Traffic Manager $id
Wants=network-online.target
After=network-online.target
[Service]
Type=simple
ExecStart=$bin -c $config
Restart=on-failure
RestartSec=5
LimitNOFILE=65536
NoNewPrivileges=yes
ProtectHome=yes
ProtectSystem=strict
PrivateTmp=yes
RestrictSUIDSGID=yes
[Install]
WantedBy=multi-user.target
EOF
}

# Realm has no readiness protocol. Wait for its TCP listener, and fail fast if
# the service exits or enters an auto-restart loop. UDP-only endpoints and hosts
# without ss keep the previous one-second settle check.
gtm_realm_wait() {
    local id=$1 protocol=$2 port=$3 tries=50
    if [[ $protocol == udp ]] || ! command -v ss >/dev/null 2>&1; then
        sleep 1; systemctl is-active --quiet "gtm-$id"; return
    fi
    while ((tries-- > 0)); do
        systemctl is-active --quiet "gtm-$id" || return 1
        [[ -z $(ss -H -n -l -t "( sport = :$((10#$port)) )" 2>/dev/null) ]] || return 0
        sleep 0.1
    done
    return 1
}

# FRP WSS entrance gateway: HAProxy master-worker tied to its FRP entrance unit.
# Shared by terminal setup, the API and recovery so the unit text stays identical.
gtm_wss_gateway_unit() {
    local bin=$1 config=$2 name=$3 id=$4
    gtm_relay_unit "$bin" "$config" "$name" | sed "s|^ExecStart=.*|ExecStart=$bin -Ws -f $config|; /After=network-online.target/a PartOf=$id.service\nAfter=$id.service"
}

gtm_relays_apply() {
    local line config unit bin old file changed=0 result=0 unit_tmp previous action item id engine protocol port
    local -A wanted=()
    local -a pending=()
    mkdir -p "$GTM_CONFIG_DIR/generated" || return 1
    # Pass 1 renders/checks every relay and publishes only changed files, so
    # systemd is reloaded once for the whole batch instead of once per relay.
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 && ( $R_ENGINE == realm || $R_ENGINE == haproxy ) ]] || continue
        gtm_need "$R_ENGINE" || return 1
        wanted[$R_ID]=1
        # A domain that has not resolved yet keeps the relay's current files.
        gtm_resolve_targets || continue
        config="$GTM_CONFIG_DIR/generated/$R_ID.conf"; unit="$GTM_SERVICE_DIR/gtm-$R_ID.service"
        file=$(mktemp "$GTM_RUN_DIR/relay.XXXXXX") || return 1
        if [[ $R_ENGINE == haproxy ]]; then
            mkdir -p "$GTM_RUN_DIR/haproxy" && chmod 700 "$GTM_RUN_DIR/haproxy" || { rm -f "$file"; return 1; }
            gtm_haproxy_render > "$file" && haproxy -c -f "$file" || { rm -f "$file"; return 1; }
        else gtm_realm_render > "$file" || { rm -f "$file"; return 1; }; fi
        bin=$(command -v "$R_ENGINE")
        unit_tmp=$(mktemp "$GTM_RUN_DIR/unit.XXXXXX") || { rm -f "$file"; return 1; }
        if [[ $R_ENGINE == haproxy ]]; then
            gtm_haproxy_unit "$bin" "$config" "$R_ID" > "$unit_tmp" || { rm -f "$file" "$unit_tmp"; return 1; }
        else gtm_relay_unit "$bin" "$config" "$R_ID" > "$unit_tmp" || { rm -f "$file" "$unit_tmp"; return 1; }; fi
        action=restart; previous=''
        if cmp -s "$unit_tmp" "$unit" && systemctl is-active --quiet "gtm-$R_ID"; then
            if cmp -s "$file" "$config"; then rm -f "$file" "$unit_tmp"; continue; fi
            if [[ $R_ENGINE == haproxy ]]; then previous=$(gtm_haproxy_pid "$R_ID" 2>/dev/null) || previous=''; [[ -z $previous ]] || action=reload; fi
        fi
        chmod 600 "$file" "$unit_tmp" && mv "$file" "$config" && mv "$unit_tmp" "$unit" || { rm -f "$file" "$unit_tmp"; return 1; }
        pending+=("$R_ID/$R_ENGINE/$action/${previous:--}/$R_PROTO/$R_PORT")
    done
    # Pass 2 starts or reloads changed relays after a single daemon reload.
    if ((${#pending[@]})); then systemctl daemon-reload || return 1; fi
    for item in "${pending[@]}"; do
        IFS=/ read -r id engine action previous protocol port <<< "$item"
        [[ $previous != - ]] || previous=''
        systemctl enable "gtm-$id" && systemctl "$action" "gtm-$id" || return 1
        if [[ $engine == haproxy ]]; then gtm_haproxy_wait "$id" "$previous" || { journalctl -u "gtm-$id" -n 15 --no-pager; return 1; }
        else gtm_realm_wait "$id" "$protocol" "$port" || { journalctl -u "gtm-$id" -n 15 --no-pager; return 1; }; fi
        systemctl is-active --quiet "gtm-$id" || { journalctl -u "gtm-$id" -n 15 --no-pager; return 1; }
    done
    # Stop only names from our closed ID namespace. FRP has a separate namespace.
    for old in "$GTM_SERVICE_DIR"/gtm-F??????.service; do
        [[ -f $old ]] || continue
        old=${old##*/}; old=${old#gtm-}; old=${old%.service}
        gtm_id "$old" || continue
        [[ ${wanted[$old]+set} ]] && continue
        systemctl disable --now "gtm-$old" || return 1
        rm -f "$GTM_SERVICE_DIR/gtm-$old.service" "$GTM_CONFIG_DIR/generated/$old.conf" || return 1
        rm -f "$GTM_RUN_DIR/haproxy/$old.sock" || return 1
        changed=1
    done
    (( changed == 0 )) || systemctl daemon-reload || return 1
    return "$result"
}

# BEGIN MODULE: transports
# FRP transport is separate from the service's TCP/UDP protocol.
# TCPMUX here means FRP stream multiplexing (tcpMux), NOT HTTP CONNECT tcpmux proxies.
gtm_frp_validate() {
    [[ $P_ROLE == entrance || $P_ROLE == destination ]] && gtm_name "$P_NAME" && gtm_ip "$P_HOST" && gtm_ip "$P_LOCAL_IP" || return 1
    gtm_port "$P_CONTROL" && gtm_port "$P_PUBLIC" && gtm_port "$P_LOCAL_PORT" || return 1
    (( 10#$P_CONTROL != 10#$P_PUBLIC )) || return 1
    [[ $P_TRANSPORT =~ ^(tcp|websocket|wss|quic|kcp)$ && $P_PROTO =~ ^(tcp|udp)$ && $P_MUX =~ ^(true|false)$ ]] || return 1
    [[ $P_TOKEN =~ ^[a-zA-Z0-9_-]{24,128}$ && $P_GROUP =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    if [[ $P_TRANSPORT == wss ]]; then
        if [[ $P_ROLE == entrance ]]; then
            gtm_port "${P_INTERNAL:-7001}" && [[ ${P_GATEWAY_CERT:-} =~ ^/[a-zA-Z0-9_./-]+$ ]] || return 1
            (( 10#${P_INTERNAL:-7001} != 10#$P_PUBLIC && 10#${P_INTERNAL:-7001} != 10#$P_CONTROL )) || return 1
        else [[ ${P_TLS_CA:-} =~ ^/[a-zA-Z0-9_./-]+$ ]] || return 1; fi
    fi
}

gtm_frp_render() {
    gtm_frp_validate || return 1
    printf 'log.to = "console"\n'
    if [[ $P_ROLE == entrance ]]; then
        if [[ $P_TRANSPORT == wss ]]; then printf 'bindAddr = "127.0.0.1"\nbindPort = %d\n' "$((10#${P_INTERNAL:-7001}))"
        else printf 'bindAddr = "%s"\nbindPort = %d\n' "$P_HOST" "$((10#$P_CONTROL))"; fi
        [[ $P_TRANSPORT != quic ]] || printf 'quicBindPort = %d\n' "$((10#$P_CONTROL))"
        [[ $P_TRANSPORT != kcp ]] || printf 'kcpBindPort = %d\n' "$((10#$P_CONTROL))"
        printf 'proxyBindAddr = "%s"\nallowPorts = [{ single = %d }]\n' "$P_HOST" "$((10#$P_PUBLIC))"
        printf 'auth.method = "token"\nauth.token = "%s"\ntransport.tls.force = %s\ntransport.tcpMux = %s\n' "$P_TOKEN" "$([[ $P_TRANSPORT == wss ]] && echo false || echo true)" "$P_MUX"
    else
        printf 'serverAddr = "%s"\nserverPort = %d\nauth.method = "token"\nauth.token = "%s"\n' "$P_HOST" "$((10#$P_CONTROL))" "$P_TOKEN"
        printf 'transport.protocol = "%s"\ntransport.tcpMux = %s\ntransport.tls.enable = true\n' "$P_TRANSPORT" "$P_MUX"
        [[ $P_TRANSPORT != wss ]] || printf 'transport.tls.trustedCaFile = "%s"\n' "$P_TLS_CA"
        printf '\n[[proxies]]\nname = "%s"\ntype = "%s"\nlocalIP = "%s"\nlocalPort = %d\nremotePort = %d\n' "$P_NAME" "$P_PROTO" "$P_LOCAL_IP" "$((10#$P_LOCAL_PORT))" "$((10#$P_PUBLIC))"
        if [[ $P_PROTO == tcp ]]; then
            printf 'loadBalancer.group = "%s"\nloadBalancer.groupKey = "%s"\nhealthCheck.type = "tcp"\nhealthCheck.timeoutSeconds = 3\nhealthCheck.maxFailed = 3\nhealthCheck.intervalSeconds = 10\n' "$P_GROUP" "$P_TOKEN"
        fi
    fi
}

gtm_wss_haproxy_render() {
    printf 'global\n    log stdout format raw local0\n    user nobody\n    group nogroup\ndefaults\n    mode tcp\n    timeout connect 5s\n    timeout client 1h\n    timeout server 1h\nfrontend wss_entrance\n    bind %s ssl crt %s\n    default_backend local_frps\nbackend local_frps\n    server local 127.0.0.1:%d\n' "$(gtm_address "$P_HOST" "$P_CONTROL")" "$P_GATEWAY_CERT" "$((10#${P_INTERNAL:-7001}))"
}

gtm_frp_menu() {
    local choice id file unit bin name
    gtm_header 'FRP Manager'
    gtm_option 1 'Setup Server' 'Public entry server'
    gtm_option 2 'Setup Client' 'Server running your service'
    gtm_option 3 'List / remove' 'Managed FRP connections'
    gtm_option 0 Back
    gtm_read 'Choose: ' choice || return
    [[ $choice == 0 ]] && return
    [[ $choice != 3 ]] || { gtm_frp_remove; return; }
    case $choice in 1) P_ROLE=entrance;; 2) P_ROLE=destination;; *) return;; esac
    gtm_step 1 3 Ports
    gtm_ask_port 'Public port (users connect here)' 443 || return; P_PUBLIC=$GTM_REPLY
    gtm_ask_port 'Tunnel control port (same on both servers)' 7000 || return; P_CONTROL=$GTM_REPLY
    gtm_step 2 3 'Server & connection'
    gtm_ask_ip 'Public server IP' '' || return; P_HOST=$GTM_REPLY
    gtm_choose Transport tcp TCP tcp WebSocket websocket WSS wss QUIC quic KCP kcp || return; P_TRANSPORT=$GTM_REPLY
    gtm_choose 'TCP multiplexing' true Enabled true Disabled false || return; P_MUX=$GTM_REPLY
    P_LOCAL_IP=127.0.0.1; P_LOCAL_PORT=$P_PUBLIC; P_PROTO=tcp; P_GROUP=default
    printf '  Use the SAME token on both sides (24-128 letters/digits/_/-).\n'
    read -r -s -p '  Shared token: ' P_TOKEN || return; printf '\n'
    if [[ $P_ROLE == destination ]]; then
        gtm_ask_ip 'Service IP' 127.0.0.1 || return; P_LOCAL_IP=$GTM_REPLY
        gtm_ask_port 'Service port' "$P_PUBLIC" || return; P_LOCAL_PORT=$GTM_REPLY
        gtm_choose Protocol tcp TCP tcp UDP udp || return; P_PROTO=$GTM_REPLY
        gtm_read 'Load balance group [default]: ' P_GROUP || return; P_GROUP=${P_GROUP:-default}
    fi
    if [[ $P_TRANSPORT == wss ]]; then
        if [[ $P_ROLE == entrance ]]; then
            printf '  WSS uses HAProxy for TLS and a loopback-only FRP listener.\n'
            gtm_read 'Internal FRP control port [7001]: ' P_INTERNAL || return; P_INTERNAL=${P_INTERNAL:-7001}
            gtm_read 'TLS PEM path (certificate chain + private key; under /etc): ' P_GATEWAY_CERT || return
            [[ $P_GATEWAY_CERT == /etc/* && -r $P_GATEWAY_CERT ]] || { gtm_error 'Use a readable PEM file under /etc (service sandbox restriction).'; return; }
        else
            gtm_read 'Trusted CA / server certificate path (under /etc): ' P_TLS_CA || return
            [[ $P_TLS_CA == /etc/* && -r $P_TLS_CA ]] || { gtm_error 'Use a readable trusted certificate under /etc (service sandbox restriction).'; return; }
        fi
    fi
    gtm_default 'Connection name (same on both servers)' name "tunnel-$P_PUBLIC" || return
    [[ $name =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || { gtm_error 'Use 1-32 letters, digits, dash or underscore.'; return; }
    P_NAME=$name
    gtm_frp_validate || { gtm_error 'Invalid connection settings.'; return; }
    gtm_step 3 3 Review
    printf '\n  %s / %s / %s / public port %s\n' "$P_ROLE" "$P_NAME" "$P_TRANSPORT" "$P_PUBLIC"
    printf '  Allow the control port and public service port in the host firewall.\n'
    if [[ $P_TRANSPORT == wss ]]; then printf '  WSS verifies the entrance certificate using the selected CA. Use an IP SAN matching the entrance IP.\n'
    else printf '  TLS encrypts the connection. This preset uses token authentication; custom CA verification is not configured.\n'; fi
    gtm_confirm || return
    gtm_prepare && gtm_install_component frp || return
    [[ $P_TRANSPORT != wss ]] || gtm_install_component haproxy || return
    gtm_lock || return
    id="gtm-frp-$P_ROLE-$P_NAME"
    if [[ $P_ROLE == entrance ]]; then
        if ! { gtm_local_address "$P_HOST" && gtm_port_available tcp "$P_HOST" "$P_CONTROL" && gtm_port_available both "$P_HOST" "$P_PUBLIC"; }; then gtm_unlock; return 1; fi
        if [[ $P_TRANSPORT == quic || $P_TRANSPORT == kcp ]] && ! gtm_port_available udp "$P_HOST" "$P_CONTROL"; then gtm_unlock; return 1; fi
        if [[ $P_TRANSPORT == wss ]] && ! gtm_port_available tcp 127.0.0.1 "$P_INTERNAL"; then gtm_unlock; return 1; fi
    fi
    file="$GTM_CONFIG_DIR/$id.toml"; unit="$GTM_SERVICE_DIR/$id.service"
    if [[ -e $file || -e $unit ]]; then gtm_error 'Name already exists. Remove it or choose a new name.'; gtm_unlock; return; fi
    if [[ $P_ROLE == entrance ]]; then bin=$(command -v frps); else bin=$(command -v frpc); fi
    if ! { gtm_frp_render > "$file.tmp" && "$bin" verify -c "$file.tmp"; }; then rm -f "$file.tmp"; gtm_unlock; return 1; fi
    local gateway="gtm-gateway-$P_NAME" gateway_config="$GTM_CONFIG_DIR/gtm-gateway-$P_NAME.conf"
    if [[ $P_TRANSPORT == wss && $P_ROLE == entrance ]]; then
        if ! { gtm_wss_haproxy_render > "$gateway_config.tmp" && haproxy -c -f "$gateway_config.tmp"; }; then rm -f "$file.tmp" "$gateway_config.tmp"; gtm_unlock; return 1; fi
        mv "$gateway_config.tmp" "$gateway_config"; chmod 600 "$gateway_config"
        gtm_wss_gateway_unit "$(command -v haproxy)" "$gateway_config" "$P_NAME" "$id" > "$GTM_SERVICE_DIR/$gateway.service"
    fi
    mv "$file.tmp" "$file" && chmod 600 "$file" || { gtm_unlock; return 1; }
    gtm_relay_unit "$bin" "$file" "$P_NAME" > "$unit"
    [[ $P_TRANSPORT != wss || $P_ROLE != entrance ]] || sed -i "/After=network-online.target/a Wants=$gateway.service" "$unit"
    if ! { systemctl daemon-reload && systemctl enable --now "$id"; }; then
        systemctl disable --now "$id" 2>/dev/null
        [[ $P_TRANSPORT != wss || $P_ROLE != entrance ]] || { systemctl disable --now "$gateway" 2>/dev/null; rm -f "$GTM_SERVICE_DIR/$gateway.service" "$gateway_config"; }
        rm -f "$unit" "$file"; systemctl daemon-reload; gtm_unlock; return 1
    fi
    sleep 1
    if ! systemctl is-active --quiet "$id"; then
        journalctl -u "$id" -n 15 --no-pager
        systemctl disable --now "$id"
        [[ $P_TRANSPORT != wss || $P_ROLE != entrance ]] || { systemctl disable --now "$gateway" 2>/dev/null; rm -f "$GTM_SERVICE_DIR/$gateway.service" "$gateway_config"; }
        rm -f "$unit" "$file"; systemctl daemon-reload; gtm_unlock; return 1
    fi
    if [[ $P_TRANSPORT == wss && $P_ROLE == entrance ]] && ! systemctl is-active --quiet "$gateway"; then
        gtm_error 'FRP started but the TLS gateway failed. Check its journal.'
        systemctl disable --now "$id" "$gateway"; rm -f "$unit" "$file" "$GTM_SERVICE_DIR/$gateway.service" "$gateway_config"; systemctl daemon-reload; gtm_unlock; return 1
    fi
    gtm_unlock
    printf 'Connection service is running. Verify the public service from another host.\n'
}

gtm_frp_remove() {
    local file choice id index=0
    local -a files=()
    for file in "$GTM_SERVICE_DIR"/gtm-frp-*.service; do
        [[ -f $file && ${file##*/} =~ ^gtm-frp-(entrance|destination)-[a-zA-Z0-9_-]+\.service$ ]] || continue
        files+=("$file"); ((index+=1)); printf '  [%d] %s\n' "$index" "${file##*/}"
    done
    (( index > 0 )) || { printf 'No managed FRP connections.\n'; return; }
    gtm_read 'Remove row [0 cancels]: ' choice || return
    gtm_uint "$choice" 1 "$index" || return
    file=${files[$((10#$choice-1))]}; id=${file##*/}; id=${id%.service}
    printf 'Remove %s\n' "$id"
    gtm_confirm && gtm_prepare && gtm_lock || return
    if systemctl disable --now "$id"; then
        local gateway="gtm-gateway-${id#gtm-frp-entrance-}"
        if [[ $id == gtm-frp-entrance-* && -f $GTM_SERVICE_DIR/$gateway.service ]]; then
            systemctl disable --now "$gateway" || { gtm_unlock; return 1; }
            rm -f "$GTM_SERVICE_DIR/$gateway.service" "$GTM_CONFIG_DIR/$gateway.conf"
        fi
        rm -f "$file" "$GTM_CONFIG_DIR/$id.toml"; systemctl daemon-reload
    else gtm_error 'Could not stop service; files kept.'; fi
    gtm_unlock
}

# BEGIN MODULE: rathole
# Optional reverse connections. This preset always uses authenticated Noise NK.
# RATH_* settings are validated data; configurations are never sourced.
gtm_rathole_key() { [[ $1 =~ ^[a-zA-Z0-9+/]{42}[AEIMQUYcgkosw048]=$ ]]; }

gtm_rathole_binary() {
    local version
    command -v rathole >/dev/null 2>&1 || return 1
    version=$(rathole --version 2>/dev/null) || return 1
    # Official 0.5.0 archives print a multiline build report, whereas local
    # builds can use clap's short version line.
    if [[ $version == rathole* && $(awk '$1 == "Build" && $2 == "Version:" {print $3; exit}' <<< "$version") == 0.5.0 ]]; then return 0; fi
    [[ $version == 'rathole 0.5.0' || $version == 'rathole v0.5.0' ]] || {
        gtm_error 'This adapter is tested with rathole 0.5.0. Existing binaries are kept.'; return 1;
    }
}

gtm_rathole_download() {
    local archive sha tmp
    gtm_need curl && gtm_need unzip && gtm_need sha256sum && gtm_need install || return 1
    case $(uname -m) in
        x86_64) archive=rathole-x86_64-unknown-linux-gnu.zip; sha=3e7d0d0f365120cd3cd351d147d1a12ee960c8068b464d4dd533a3821873b80e ;;
        aarch64) archive=rathole-aarch64-unknown-linux-musl.zip; sha=fa4a6fc63d86f8f1faa7c103a845e4715ce79a048455c0eec897b27237576564 ;;
        *) gtm_error 'The rathole installer supports x86_64 and aarch64 Linux.'; return 1 ;;
    esac
    tmp=$(mktemp -d "$GTM_RUN_DIR/rathole-download.XXXXXX") || return 1
    if ! { curl --proto '=https' --tlsv1.2 -fL --connect-timeout 15 --max-time 180 "https://github.com/rathole-org/rathole/releases/download/v0.5.0/$archive" -o "$tmp/archive.zip" &&
        printf '%s  %s\n' "$sha" "$tmp/archive.zip" | sha256sum -c - &&
        unzip -p "$tmp/archive.zip" rathole > "$tmp/rathole" && chmod 700 "$tmp/rathole" &&
        "$tmp/rathole" --version >/dev/null && gtm_component_publish "$tmp" rathole; }; then
        rm -rf "$tmp"; return 1
    fi
    rm -rf "$tmp"
    gtm_rathole_binary
}

gtm_rathole_validate() {
    [[ $RATH_ROLE =~ ^(entrance|destination)$ && $RATH_NAME =~ ^[a-zA-Z0-9_-]{1,32}$ && $RATH_PROTO =~ ^(tcp|udp|both)$ ]] || return 1
    gtm_ip "$RATH_HOST" && gtm_ip "$RATH_LOCAL_IP" && gtm_port "$RATH_CONTROL" && gtm_port "$RATH_PUBLIC" && gtm_port "$RATH_LOCAL_PORT" || return 1
    ((10#$RATH_CONTROL != 10#$RATH_PUBLIC)) || return 1
    [[ $RATH_TOKEN =~ ^[a-zA-Z0-9_-]{24,128}$ ]] && gtm_rathole_key "$RATH_KEY" || return 1
    if [[ $RATH_ROLE == destination ]]; then
        # Reject client loops back into the remote control or public listener.
        if [[ $(gtm_ip_key "$RATH_HOST") == "$(gtm_ip_key "$RATH_LOCAL_IP")" ]]; then
            ((10#$RATH_LOCAL_PORT != 10#$RATH_CONTROL && 10#$RATH_LOCAL_PORT != 10#$RATH_PUBLIC)) || return 1
        fi
    fi
}

gtm_rathole_render() {
    gtm_rathole_validate || return 1
    local role=client proto
    local -a protocols=("$RATH_PROTO")
    [[ $RATH_PROTO != both ]] || protocols=(tcp udp)
    [[ $RATH_ROLE != entrance ]] || role=server
    printf '[%s]\n' "$role"
    if [[ $role == server ]]; then printf 'bind_addr = "%s"\n' "$(gtm_address "$RATH_HOST" "$((10#$RATH_CONTROL))")"
    else printf 'remote_addr = "%s"\nretry_interval = 3\n' "$(gtm_address "$RATH_HOST" "$((10#$RATH_CONTROL))")"; fi
    printf '\n[%s.transport]\ntype = "noise"\n\n[%s.transport.tcp]\nnodelay = true\nkeepalive_secs = 20\nkeepalive_interval = 8\n' "$role" "$role"
    printf '\n[%s.transport.noise]\npattern = "Noise_NK_25519_ChaChaPoly_BLAKE2s"\n' "$role"
    if [[ $role == server ]]; then printf 'local_private_key = "%s"\n' "$RATH_KEY"
    else printf 'remote_public_key = "%s"\n' "$RATH_KEY"; fi
    for proto in "${protocols[@]}"; do
        printf '\n[%s.services."%s_%s"]\ntype = "%s"\ntoken = "%s"\n' "$role" "$RATH_NAME" "$proto" "$proto" "$RATH_TOKEN"
        if [[ $role == server ]]; then printf 'bind_addr = "%s"\n' "$(gtm_address "$RATH_HOST" "$((10#$RATH_PUBLIC))")"
        else printf 'local_addr = "%s"\n' "$(gtm_address "$RATH_LOCAL_IP" "$((10#$RATH_LOCAL_PORT))")"; fi
    done
}

gtm_rathole_unit() {
    local bin=$1 config=$2
    cat <<EOF
[Unit]
Description=Traffic Manager rathole reverse connection
Wants=network-online.target
After=network-online.target
[Service]
Type=simple
ExecStart=$bin $config
Environment=RUST_LOG=warn
Restart=on-failure
RestartSec=5
LimitNOFILE=65536
NoNewPrivileges=yes
ProtectHome=yes
ProtectSystem=strict
PrivateTmp=yes
RestrictSUIDSGID=yes
[Install]
WantedBy=multi-user.target
EOF
}

# The shared lock is held by the caller. Existing instances are never overwritten.
gtm_rathole_create() {
    local id="gtm-rathole-$RATH_ROLE-$RATH_NAME" config unit tmp bin
    config="$GTM_CONFIG_DIR/$id.toml"; unit="$GTM_SERVICE_DIR/$id.service"
    [[ ! -e $config && ! -L $config && ! -e $unit && ! -L $unit ]] || { gtm_error 'Name already exists. Choose another name or remove that instance.'; return 1; }
    gtm_rathole_validate && gtm_rathole_binary || return 1
    if [[ $RATH_ROLE == entrance ]]; then
        gtm_local_address "$RATH_HOST" && gtm_port_available tcp "$RATH_HOST" "$RATH_CONTROL" &&
            gtm_port_available "$RATH_PROTO" "$RATH_HOST" "$RATH_PUBLIC" || return 1
    fi
    tmp=$(mktemp "$GTM_RUN_DIR/rathole-config.XXXXXX") || return 1
    bin=$(command -v rathole)
    if ! { gtm_rathole_render > "$tmp" && chmod 600 "$tmp" && mv "$tmp" "$config" && gtm_rathole_unit "$bin" "$config" > "$unit" &&
        systemctl daemon-reload && systemctl enable --now "$id"; }; then
        rm -f "$tmp"
        gtm_rathole_cleanup "$id" || return 1
        return 1
    fi
    sleep 1
    if ! systemctl is-active --quiet "$id"; then
        journalctl -u "$id" -n 15 --no-pager
        gtm_rathole_cleanup "$id" || return 1
        return 1
    fi
    printf 'Created %s. A running process does not prove the peer is connected.\n' "$id"
}

gtm_rathole_cleanup() {
    local id=$1
    [[ $id =~ ^gtm-rathole-(entrance|destination)-[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    systemctl disable --now "$id" || { gtm_error 'Could not stop service. Config and unit were kept for recovery.'; return 1; }
    rm -f "$GTM_SERVICE_DIR/$id.service" "$GTM_CONFIG_DIR/$id.toml" || return 1
    systemctl daemon-reload
}

gtm_rathole_remove() {
    local file id choice
    local -a ids=()
    for file in "$GTM_SERVICE_DIR"/gtm-rathole-*.service; do
        [[ -f $file ]] || continue
        id=${file##*/}; id=${id%.service}
        [[ $id =~ ^gtm-rathole-(entrance|destination)-[a-zA-Z0-9_-]{1,32}$ ]] || continue
        ids+=("$id"); printf '  [%d] %s\n' "${#ids[@]}" "$id"
    done
    ((${#ids[@]})) || { printf 'No managed rathole instances.\n'; return; }
    gtm_read 'Remove row [0 cancels]: ' choice || return
    gtm_uint "$choice" 1 "${#ids[@]}" || return
    id=${ids[$((10#$choice-1))]}
    printf 'Remove local instance %s. Configure the other server separately.\n' "$id"
    gtm_confirm && gtm_prepare && gtm_lock || return
    gtm_rathole_cleanup "$id"; local result=$?
    gtm_unlock
    return "$result"
}

gtm_rathole_setup() {
    local role=$1 keys public_key result
    RATH_ROLE=$role; RATH_LOCAL_IP=127.0.0.1; RATH_LOCAL_PORT=443
    gtm_step 1 3 Ports
    gtm_ask_port 'Public port (users connect here)' 443 || return; RATH_PUBLIC=$GTM_REPLY
    gtm_ask_port 'Tunnel control port (same on both servers)' 2333 || return; RATH_CONTROL=$GTM_REPLY
    gtm_step 2 3 'Server & connection'
    gtm_ask_ip 'Public server IP' '' || return; RATH_HOST=$GTM_REPLY
    gtm_choose Protocol tcp TCP tcp UDP udp 'TCP + UDP' both || return; RATH_PROTO=$GTM_REPLY
    gtm_default 'Connection name (same on both servers)' RATH_NAME "tunnel-$RATH_PUBLIC" || return
    printf '  Use the same service name, protocol and token on both servers.\n'
    read -r -s -p '  Shared token [24-128 letters/digits/_/-]: ' RATH_TOKEN || return; printf '\n'
    if [[ $role == entrance ]]; then
        # Validation placeholder only; replaced by a generated key before creation.
        RATH_KEY=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=
    else
        gtm_read 'Entrance Noise public key (copy over a trusted channel): ' RATH_KEY || return
        gtm_ask_ip 'Service IP' 127.0.0.1 || return; RATH_LOCAL_IP=$GTM_REPLY
        gtm_ask_port 'Service port' "$RATH_PUBLIC" || return; RATH_LOCAL_PORT=$GTM_REPLY
    fi
    gtm_rathole_validate || { gtm_error 'Invalid rathole settings.'; return 1; }
    gtm_step 3 3 Review
    printf '\n  %s / %s / %s / Noise over TCP\n  Control %s:%s | Public port %s\n' "$role" "$RATH_NAME" "$RATH_PROTO" "$RATH_HOST" "$RATH_CONTROL" "$RATH_PUBLIC"
    printf '  UDP services also travel over TCP: packet loss can delay other datagrams.\n'
    printf '  Allow the control TCP port and selected public service protocols in the host firewall.\n'
    gtm_confirm && gtm_prepare && gtm_install_component rathole || return
    if [[ $role == entrance ]]; then
        keys=$(rathole --genkey) || return 1
        RATH_KEY=$(awk '/^Private Key:/ {getline; print; exit}' <<< "$keys")
        public_key=$(awk '/^Public Key:/ {getline; print; exit}' <<< "$keys")
        gtm_rathole_key "$public_key" && gtm_rathole_validate || { gtm_error 'Could not generate valid Noise keys.'; return 1; }
    fi
    gtm_lock || return
    gtm_rathole_create; result=$?
    gtm_unlock
    if ((result==0)) && [[ $role == entrance ]]; then
        printf '\nEntrance public key (copy to destination):\n%s\n' "$public_key"
    fi
    # Do not retain credentials in shell globals after returning to the menu.
    unset RATH_KEY RATH_TOKEN keys
    return "$result"
}

gtm_rathole_menu() {
    local choice
    gtm_header 'rathole Manager'
    gtm_option 1 'Setup Server' 'Public entry server'
    gtm_option 2 'Setup Client' 'Server running your service'
    gtm_option 3 'List / remove' 'Managed rathole instances on this server'
    gtm_option 0 Back
    gtm_read 'Choose: ' choice || return
    case $choice in 1) gtm_rathole_setup entrance;; 2) gtm_rathole_setup destination;; 3) gtm_rathole_remove;; esac
    unset RATH_KEY RATH_TOKEN
}

# BEGIN MODULE: catalog
# A small decision guide. Capabilities describe implemented adapters, not every
# upstream feature, and never infer performance from the implementation language.
gtm_catalog() {
    printf 'Connection guide / implemented presets\n\n'
    printf '  Kernel forwarding: iptables / nftables\n    Direct TCP/UDP ports, optional GRE path, weighted random. No target health checks.\n'
    printf '  Checked TCP balancing: HAProxy\n    Round robin, least connections, consistent source hash or primary/backup failover.\n    Timeouts, caps, slow start, health settings, opt-in PROXY, local status and worker reload.\n'
    printf '  TCP/UDP relay: Realm\n    Single target or weighted round robin / source hashing.\n'
    printf '  Reverse connections: FRP\n    TCP, stream mux, WebSocket, verified WSS gateway or QUIC; TCP destination groups.\n'
    printf '  Reverse connections: rathole\n    Authenticated Noise over TCP; TCP/UDP/both services; one destination per instance.\n'
    printf '  Network links: GRE / ip6gre\n    Join IP networks, then forward service ports separately. GRE itself is not encrypted.\n\n'
    printf 'Selection notes\n'
    printf '  Start with kernel NAT when the destination is directly reachable.\n'
    printf '  Use HAProxy when TCP health checks and failover are required.\n'
    printf '  Use a reverse connection when only the destination can initiate the link.\n'
    printf '  For UDP on a lossy path, compare native UDP/GRE and FRP QUIC with TCP transports.\n'
    printf '  TCP Mux means FRP stream mux here, not HTTP CONNECT tcpmux.\n'
    printf '  Encryption, authentication and reachability are separate properties.\n'
    printf '  Measure CPU, RAM, loss, RTT and jitter on the actual route; no engine always wins.\n\n'
    printf 'Planned / not implemented\n'
    printf '  WireGuard/AmneziaWG link provisioning, GOST chains, GRE-over-UDP, IPVS,\n'
    printf '  HTTP CONNECT tcpmux, automatic cross-host deployment and a web dashboard.\n'
}

gtm_reverse_menu() {
    local choice
    gtm_header 'Reverse Tunnel'
    gtm_help reverse
    gtm_option 1 FRP 'TCP / WS / WSS / QUIC'
    gtm_option 2 rathole 'Noise tunnel'
    gtm_option 3 Help 'Which one should I use?'
    gtm_option 0 Back
    gtm_read 'Choose: ' choice || return
    case $choice in 1) gtm_frp_menu;; 2) gtm_rathole_menu;; 3) gtm_catalog; gtm_pause;; esac
}

# BEGIN MODULE: inspect
# Inspection, preflight and dependency checks. No resident monitoring process.
# Used for new reverse listeners: socket checks alone miss kernel DNAT rules.
gtm_port_available() {
    local protocol=$1 bind=$2 port=$3 line key other
    gtm_listener_check "$protocol" "$bind" "$port" && gtm_legacy_listener_check "$protocol" "$bind" "$port" && gtm_load_records || return 1
    key=$(gtm_ip_key "$bind") || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 ]] && ((R_FIRST <= 10#$port && 10#$port <= R_LAST)) || continue
        [[ $protocol == both || $R_PROTO == both || $protocol == "$R_PROTO" ]] || continue
        other=$(gtm_ip_key "$R_BIND") || return 1
        if [[ $key == "$other" || $key == 0.0.0.0 || $other == 0.0.0.0 || $key == 00000000000000000000000000000000 || $other == 00000000000000000000000000000000 ]]; then
            gtm_error "Port is reserved by managed connection $R_ID ($R_NAME)."; return 1
        fi
    done
    return 0
}

gtm_local_address() {
    local wanted=$1 key address listing
    key=$(gtm_ip_key "$wanted") || return 1
    [[ $key != 0.0.0.0 && $key != 00000000000000000000000000000000 ]] || return 0
    listing=$(ip -o address show) || return 1
    while read -r address; do
        address=${address%/*}
        [[ $(gtm_ip_key "$address") != "$key" ]] || return 0
    done < <(awk '$3 == "inet" || $3 == "inet6" {print $4}' <<< "$listing")
    gtm_error "Entrance IP is not assigned locally: $wanted"
}

gtm_relay_address_key() {
    local key
    key=$(gtm_ip_key "$1") || return 1
    # A hexadecimal IPv4-mapped IPv6 address still connects to an IPv4 socket.
    if [[ ${key:0:24} == 00000000000000000000ffff ]]; then
        printf '%d.%d.%d.%d' "$((16#${key:24:2}))" "$((16#${key:26:2}))" "$((16#${key:28:2}))" "$((16#${key:30:2}))"
    else printf '%s' "$key"; fi
}

# Relays must not loop into their own listener, including mapped address aliases.
gtm_relay_loop_check() {
    local bind_key target address key listing
    local -a fields=() targets=()
    bind_key=$(gtm_relay_address_key "$R_BIND") || return 1
    listing=''
    IFS=, read -r -a targets <<< "$R_TARGETS"
    for target in "${targets[@]}"; do
        gtm_target "$target" || return 1
        # Overlapping port spans loop; unresolved names cannot be checked here.
        (( EP_HOST == 0 && EP_PORT <= R_LAST && EP_LAST >= R_FIRST )) || continue
        key=$(gtm_relay_address_key "$EP_IP") || return 1
        if [[ $bind_key != 0.0.0.0 && $bind_key != 00000000000000000000000000000000 ]]; then
            [[ $bind_key != "$key" ]] || { gtm_error "Tunnel $R_ID points back to its own listening port."; return 1; }
            continue
        fi
        [[ $bind_key != 0.0.0.0 || $key == *.* ]] || continue
        [[ -n $listing ]] || listing=$(ip -o address show) || return 1
        while read -r -a fields; do
            [[ ${fields[2]:-} == inet || ${fields[2]:-} == inet6 ]] || continue
            address=${fields[3]%/*}
            if [[ $(gtm_relay_address_key "$address") == "$key" ]]; then
                gtm_error "Tunnel $R_ID points back to its own listening port. Choose a different remote port or server."
                return 1
            fi
        done <<< "$listing"
    done
    return 0
}

# Called before replacing desired state. Temporary files contain no executable input.
gtm_preflight_checks() {
    local file=$1 line family table tool has4=0 has6=0 hasnft=0
    gtm_kernel_dependencies && gtm_dns_ensure || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_ENABLED == 1 ]] || continue
        gtm_resolve_targets || { gtm_error "$R_ID has no resolved destination."; return 1; }
        gtm_need ip && gtm_local_address "$R_BIND" || return 1
        # Resolved names must obey the same loop guard as literal endpoints,
        # including kernel forwards bound to a specific local address.
        gtm_relay_loop_check || return 1
        if [[ $R_ENGINE == iptables || $R_ENGINE == nftables ]]; then
            # An all-addresses DNAT to one of this host's own addresses on the
            # same port would capture its own target; reuse the relay check.
            [[ $R_IFACE == any ]] || ip link show dev "$R_IFACE" >/dev/null || return 1
            if [[ $R_BIND == *:* ]] && [[ $(sysctl -n net.ipv6.conf.all.forwarding) != 1 ]]; then
                gtm_error 'IPv6 forwarding is disabled; configure forwarding and Router Advertisements first.'; return 1
            fi
        fi
        case $R_ENGINE in
            iptables) if [[ $R_BIND == *:* ]]; then has6=1; else has4=1; fi ;;
            nftables) hasnft=1 ;;
            haproxy) [[ $H_ROUTE_MODE != https ]] || gtm_haproxy_certificate >/dev/null || return 1; gtm_need haproxy && gtm_need socat && gtm_need timeout && gtm_haproxy_render > "$file" && haproxy -c -f "$file" || return 1 ;;
            realm) gtm_need realm && gtm_realm_profile_preflight && gtm_realm_render > "$file" || return 1 ;;
        esac
    done
    # Check the same return-route marks that apply will install.
    GTM_RT_ADDRS=(); GTM_RT_RULES=()
    if ((has4 || has6 || hasnft)); then gtm_return_routes_detect || return 1; fi
    for family in 4 6; do
        tool=iptables; [[ $family == 4 ]] || tool=ip6tables
        if { [[ $family == 4 ]] && ((has4)); } || { [[ $family == 6 ]] && ((has6)); } ||
            { command -v "$tool" >/dev/null && "$tool" -t nat -S GTM_PRE >/dev/null 2>&1; }; then
            gtm_need "$tool-restore" || return 1
            for table in nat filter mangle; do
                gtm_iptables_render "$family" "$table" > "$file" && "$tool-restore" -w 5 --noflush --test < "$file" || return 1
            done
        fi
    done
    if ((hasnft)) || { command -v nft >/dev/null && nft list table inet gre_manager >/dev/null 2>&1; }; then
        gtm_nft_render > "$file" && nft -c -f "$file" || return 1
    fi
    return 0
}

gtm_preflight() {
    local file result
    file=$(mktemp "$GTM_RUN_DIR/preflight.XXXXXX") || return 1
    gtm_preflight_checks "$file"; result=$?
    rm -f "$file"
    (( result == 0 )) || gtm_error 'Preflight failed. The saved configuration and live services were kept.'
    return "$result"
}

gtm_inspect_state() {
    local file=${1:-$GTM_STATE}
    [[ -f $file && -r $file ]] || { gtm_error "State file is missing or unreadable: $file"; return 1; }
    gtm_load_records "$file" || return 1
    printf 'Valid state: %d connection(s), supported record versions v1/v2/v3/v4.\n' "${#GTM_RECORDS[@]}"
}

# Offline deterministic preview: no root, package installs, temp files or probes.
gtm_config_render() {
    local line extra family table
    IFS= read -r line || return 1
    if IFS= read -r extra; then return 1; fi
    gtm_record_validate "$line" || return 1
    # Rendering an inactive record shows its desired config without enabling it.
    R_ENABLED=1
    GTM_RECORDS=("$(gtm_record_emit)")
    case $R_ENGINE in
        haproxy) gtm_haproxy_render;;
        realm) gtm_realm_render;;
        nftables) gtm_nft_render;;
        iptables)
            family=4; [[ $R_BIND != *:* ]] || family=6
            for table in nat filter mangle; do gtm_iptables_render "$family" "$table" || return 1; done;;
        *) return 1;;
    esac
}

gtm_plan() {
    local line engine family table has4=0 has6=0 hasnft=0
    gtm_inspect_state "${1:-$GTM_STATE}" || return 1
    printf '\nConfiguration preview / nothing applied\n'
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        printf '\n%s  %s  enabled=%s\n  %s / %s / %s\n  %s -> %s\n' "$R_ID" "$R_NAME" "$R_ENABLED" "$R_ENGINE" "$R_PROTO" "$R_STRATEGY" "$(gtm_address "$R_BIND" "$R_PORT")" "$R_TARGETS"
        [[ $R_ENABLED == 1 ]] || continue
        case $R_ENGINE in
            iptables) if [[ $R_BIND == *:* ]]; then has6=1; else has4=1; fi ;;
            nftables) hasnft=1 ;;
            realm|haproxy) engine=$R_ENGINE; printf '\n# %s %s\n' "$R_ID" "$engine"; "gtm_${engine}_render" || return 1 ;;
        esac
    done
    for family in 4 6; do
        if { [[ $family == 4 ]] && ((has4)); } || { [[ $family == 6 ]] && ((has6)); }; then
            printf '\n# iptables family %s: owned chain contents (parent hooks installed on apply)\n' "$family"
            for table in nat filter mangle; do gtm_iptables_render "$family" "$table" || return 1; done
        fi
    done
    if ((hasnft)); then printf '\n# Native nftables owned table\n'; gtm_nft_render || return 1; fi
    printf '\nPreview excludes host-policy changes, global tuning, old-resource cleanup and FRP/rathole instances.\nOffline validation does not test routing, backend syntax or target health.\n'
}

# Multi-address hosts: per-address routing tables, strict reverse-path filters
# and kernel forwards that still accept on one address only. Read-only.
gtm_doctor_addresses() {
    local entry family address mark table iface main state value strict line count key header=0
    gtm_return_routes_detect || :
    printf '\nAddresses with their own routing table (kernel-forward replies follow it):\n'
    ((${#GTM_RT_ADDRS[@]})) || printf '  none\n'
    for entry in ${GTM_RT_ADDRS[@]+"${GTM_RT_ADDRS[@]}"}; do
        IFS='|' read -r family address mark table iface <<< "$entry"
        state='not installed (applied with kernel forwards)'
        [[ $(ip -"$family" rule show 2>/dev/null) != *"fwmark $mark/0xf000000 lookup $table"* ]] || state=active
        printf '  %s on %s / table %s / return rule %s\n' "$address" "$iface" "$table" "$state"
        [[ $family == 4 ]] || continue
        main=$(ip -o -4 route get 1.1.1.1 2>/dev/null) || main=''
        [[ $main =~ \ dev\ ([^ ]+) && ${BASH_REMATCH[1]} != "$iface" ]] || continue
        strict=0
        for value in all "$iface"; do
            [[ $(cat "/proc/sys/net/ipv4/conf/$value/rp_filter" 2>/dev/null) != 1 ]] || strict=1
        done
        ((strict == 0)) || printf '    Strict rp_filter drops forwarded flows that enter on %s; set net.ipv4.conf.%s.rp_filter=2 (loose).\n' "$iface" "$iface"
    done
    for line in ${GTM_RECORDS[@]+"${GTM_RECORDS[@]}"}; do
        gtm_record_validate "$line" || continue
        [[ $R_ENABLED == 1 && $R_ENGINE =~ ^(iptables|nftables)$ ]] && ! gtm_wildcard "$R_BIND" || continue
        family=4; [[ $R_BIND == *:* ]] && family=6
        gtm_key_of "$R_BIND" || continue
        key=$GTM_KEY
        count=0
        while read -r address; do
            gtm_key_of "${address%/*}" && [[ $GTM_KEY != "$key" ]] && count=$((count + 1))
        done < <(ip -o -"$family" address show scope global 2>/dev/null | awk '{print $4}')
        ((count)) || continue
        ((header)) || { header=1; printf '\nKernel forwards limited to one local address:\n'; }
        printf '  %s listens only on %s; %d other local IPv%s address(es) are not forwarded.\n' "$R_ID" "$R_BIND" "$count" "$family"
    done
    ((header == 0)) || printf '  Set Listen address to all local addresses to accept on every IP.\n'
}

gtm_doctor() {
    local tool line state used maximum errors=0
    printf 'Traffic Manager %s / read-only health report\n' "$GTM_VERSION"
    printf 'No packets are sent and no settings are changed.\n\n'
    if [[ -e $GTM_STATE || -L $GTM_STATE ]]; then gtm_inspect_state || errors=1
    else GTM_RECORDS=(); printf 'No managed forwarding state yet.\n'; fi
    for tool in ip ss iptables nft realm haproxy socat frpc frps rathole systemctl; do
        if command -v "$tool" >/dev/null 2>&1; then printf '  %-12s %s\n' "$tool" "$(command -v "$tool")"
        else printf '  %-12s unavailable (may be optional)\n' "$tool"; fi
    done
    if [[ $(uname -s) != Linux ]]; then printf '\nLive host checks require Linux.\n'; return "$errors"; fi
    if command -v sysctl >/dev/null; then
        printf '\nIPv4 forwarding: '; sysctl -n net.ipv4.ip_forward 2>/dev/null || printf 'unavailable\n'
        printf 'IPv6 forwarding: '; sysctl -n net.ipv6.conf.all.forwarding 2>/dev/null || printf 'unavailable\n'
        used=$(sysctl -n net.netfilter.nf_conntrack_count 2>/dev/null)
        maximum=$(sysctl -n net.netfilter.nf_conntrack_max 2>/dev/null)
        printf 'Conntrack entries / limit: %s / %s\n' "${used:-unavailable}" "${maximum:-unavailable}"
    fi
    if command -v ip >/dev/null; then
        printf '\nGRE interfaces (includes current MTU):\n'
        ip -d link show type gre; ip -d link show type ip6gre
        gtm_doctor_addresses
    fi
    if command -v systemctl >/dev/null; then
        printf '\nManaged relay state (configuration / service):\n'
        for line in "${GTM_RECORDS[@]}"; do
            gtm_record_validate "$line" || continue
            [[ $R_ENGINE == realm || $R_ENGINE == haproxy ]] || continue
            state=$(systemctl is-active "gtm-$R_ID" 2>/dev/null) || :
            printf '  %s  enabled=%s  service=%s\n' "$R_ID" "$R_ENABLED" "${state:-unknown}"
        done
        systemctl list-units 'gtm-frp-*' 'gtm-rathole-*' 'gtm-gateway-*' 'gre-manager-forwarding*' --all --no-pager 2>/dev/null || :
    fi
    printf '\nFor packet drops: check UFW/Docker base-chain policies and return routes.\nFor stalls: inspect path MTU/ICMP; this report does not measure throughput or jitter.\n'
    return "$errors"
}

# Protect known GRE address/interface dependencies, including disabled records.
gtm_link_dependents() {
    local tid=$1 line target key prefix reason
    local -a targets=()
    GTM_DEPENDENTS=()
    gtm_uint "$tid" 1 250 || return 1
    tid=$((10#$tid))
    gtm_load_records || return 1
    prefix=$(gtm_ip_key "fd00:$tid::") || return 1
    prefix=${prefix:0:16}
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        reason=''
        [[ $R_IFACE != "gre$tid" && $R_IFACE != "gre-out-$tid" ]] || reason=interface
        IFS=, read -r -a targets <<< "$R_TARGETS"
        targets+=("$(gtm_address "$R_BIND" "$R_PORT")")
        for target in "${targets[@]}"; do
            gtm_target "$target" || return 1
            ((EP_HOST == 0)) || continue
            key=$(gtm_ip_key "$EP_IP") || return 1
            if [[ $key == "10.0.$tid."[0-3] || ( $EP_IP == *:* && ${key:0:16} == "$prefix" ) ]]; then reason=address; fi
        done
        [[ -z $reason ]] || GTM_DEPENDENTS+=("$R_ID / $R_NAME / $reason")
    done
}

gtm_link_remove_guard() {
    gtm_link_dependents "$1" || return 1
    if (( ${#GTM_DEPENDENTS[@]} )); then
        printf '\nLink is referenced by managed connections:\n'
        printf '  %s\n' "${GTM_DEPENDENTS[@]}"
        gtm_error 'Edit or delete these connections before removing the GRE link (disabled records count too).'
        return 1
    fi
    printf '\nNo known managed dependencies. Check manual/legacy rules and custom routes too.\n'
    gtm_confirm
}

# BEGIN MODULE: forms
# Numbered, staged forms. Collection is read-only; saving reloads full state under lock.
# With "spans" (kernel engines) a range stays one item of up to 4096 ports;
# otherwise ranges expand to single ports. Either way at most 32 items.
gtm_parse_ports() {
    local input=$1 spans=${2:-} repeat=${3:-} word first last port
    local -a words=()
    local -A seen=()
    GTM_PORTS=()
    [[ -n $input && ${#input} -le 1024 && $input != ,* && $input != *, && $input != *,,* ]] || return 1
    read -r -a words <<< "${input//,/ }"
    for word in "${words[@]}"; do
        gtm_port_span "$word" || return 1
        first=$PS_FIRST; last=$PS_LAST
        if [[ -n $spans ]]; then
            # Remote ports may repeat (several local ranges to one port).
            [[ -n $repeat ]] || for ((port=first; port<=last; port++)); do [[ ! ${seen[$port]+set} ]] || return 1; seen[$port]=1; done
            GTM_PORTS+=("$(gtm_span_text "$first" "$last")")
            ((${#GTM_PORTS[@]}<=32)) || return 1
            continue
        fi
        ((last-first<32)) || return 1
        for ((port=first; port<=last; port++)); do
            [[ ! ${seen[$port]+set} ]] || continue
            GTM_PORTS+=("$port"); seen[$port]=1
            ((${#GTM_PORTS[@]}<=32)) || return 1
        done
    done
    ((${#GTM_PORTS[@]}>0))
}

gtm_ask_port() {
    local label=$1 default=$2 port_input
    while true; do
        gtm_default "$label" port_input "$default" || return 1
        [[ $port_input != 0 ]] || return 1
        if gtm_port "$port_input"; then GTM_REPLY=$((10#$port_input)); return 0; fi
        gtm_error 'Use a port from 1 to 65535. Enter 0 to cancel.'
    done
}

gtm_ask_ip() {
    local label=$1 default=$2 ip_input
    while true; do
        gtm_default "$label" ip_input "$default" || return 1
        [[ $ip_input != 0 ]] || return 1
        if gtm_ip "$ip_input"; then GTM_REPLY=$ip_input; return 0; fi
        gtm_error 'Enter a valid IPv4 or IPv6 address. Enter 0 to cancel.'
    done
}

gtm_form_ports() {
    local input
    local spans=''
    [[ $W_ENGINE != iptables && $W_ENGINE != nftables ]] || spans=1
    gtm_step 1 3 'Local port(s)'
    if [[ -n $spans ]]; then printf '  Example: 443, 8443 or 2000-2999 (up to 4096 ports in one rule). Enter 0 to cancel.\n'
    else printf '  Example: 443, 8443 or 8000-8003. Enter 0 to cancel.\n'; fi
    while true; do
        gtm_default 'Local port(s)' input "$(IFS=,; printf '%s' "${W_PORTS[*]:-443}")" || return 1
        [[ $input != 0 ]] || return 1
        if gtm_parse_ports "$input" "$spans"; then
            if [[ -n $W_EDIT && ${#GTM_PORTS[@]} != 1 ]]; then gtm_error 'Edit one port at a time. Use Add tunnel for more ports.'; continue; fi
            W_PORTS=("${GTM_PORTS[@]}"); return 0
        fi
        if [[ -n $spans ]]; then gtm_error 'Use ports 1-65535; up to 32 ports or ranges, without overlaps.'
        else gtm_error 'Use ports 1-65535; up to 32 ports per setup.'; fi
    done
}

gtm_form_target() {
    local input port_default=$1
    port_default=${port_default%-*}
    while true; do
        gtm_default 'Remote IP or domain (IP:port also works)' input '' || return 1
        [[ $input != 0 ]] || return 1
        input=${input,,}
        if gtm_ip "$input" || gtm_hostname "$input"; then
            W_REMOTE_IP=$input
            gtm_ask_port 'Remote port' "$port_default" || return 1
            W_REMOTE_PORT=$GTM_REPLY; W_REMOTE_WEIGHT=1
        elif gtm_target "$input" && ((EP_LAST == EP_PORT)); then
            W_REMOTE_IP=$EP_IP; W_REMOTE_PORT=$EP_PORT; W_REMOTE_WEIGHT=$EP_WEIGHT
        else
            gtm_error 'Enter a valid IP, domain or IP:port. IPv6 with a port: [2001:db8::1]:443.'; continue
        fi
        if gtm_hostname "$W_REMOTE_IP" && [[ $W_REMOTE_IP != *:* ]]; then
            printf '  Checking %s ...\n' "$W_REMOTE_IP"
            if ! gtm_dns_lookup "$W_REMOTE_IP" 4 | paste -sd' ' - | grep -q .; then
                gtm_error "$W_REMOTE_IP does not resolve to an IPv4 address."; continue
            fi
            printf '  Resolves to: %s (refreshed every 5 minutes)\n' "$(gtm_dns_lookup "$W_REMOTE_IP" 4 | paste -sd' ' -)"
        fi
        return 0
    done
}

gtm_form_targets() {
    local count=0 key family='' current_family
    local -A seen=()
    gtm_step 2 3 'Remote server'
    if [[ -n $W_TARGETS ]]; then
        printf '  Current: %s\n' "$W_TARGETS"
        gtm_choose 'Remote server' keep 'Keep current' keep 'Change' change || return 1
        [[ $GTM_REPLY != keep ]] || return 0
    fi
    W_TARGETS=''
    while true; do
        gtm_form_target "${W_PORTS[0]}" || return 1
        current_family=4; [[ $W_REMOTE_IP != *:* ]] || current_family=6
        if [[ $W_ENGINE == iptables || $W_ENGINE == nftables ]] && ! gtm_hostname "$W_REMOTE_IP"; then
            if [[ -n $family && $family != "$current_family" ]]; then gtm_error 'Use the same IP version for all kernel targets.'; continue; fi
            family=$current_family
        fi
        key=$W_REMOTE_IP; gtm_hostname "$key" || key=$(gtm_ip_key "$W_REMOTE_IP")
        key+=":$W_REMOTE_PORT"
        if [[ ${seen[$key]+set} ]]; then gtm_error 'That server and port are already in the list.'; continue; fi
        seen[$key]=1
        W_TARGETS+="${W_TARGETS:+,}$(gtm_address "$W_REMOTE_IP" "$W_REMOTE_PORT")@$W_REMOTE_WEIGHT"
        ((count+=1))
        [[ $W_MODE == balance && $count -lt 32 ]] || break
        if ((count<2)); then printf '\n  Add the second server.\n'; continue; fi
        gtm_choose 'Remote servers' 'done' 'Continue' 'done' 'Add another server' add || return 1
        [[ $GTM_REPLY == add ]] || break
    done
    if [[ $W_ENGINE != haproxy ]]; then
        gtm_choose 'Protocol' "$W_PROTO" TCP tcp UDP udp 'TCP + UDP' both || return 1
        W_PROTO=$GTM_REPLY
    fi
    if [[ $W_TARGETS == *,* ]]; then
        case $W_ENGINE in
            haproxy) gtm_choose 'Load balancing' "$W_STRATEGY" 'Round robin' roundrobin 'Least connections' leastconn 'Same client, same server' source 'Primary / backup' failover || return 1; W_STRATEGY=$GTM_REPLY;;
            realm) gtm_choose 'Load balancing' "$W_STRATEGY" 'Round robin' roundrobin 'Same client, same server' source || return 1; W_STRATEGY=$GTM_REPLY;;
            nftables) gtm_choose 'Load balancing' "$W_STRATEGY" 'Weighted random' random 'Round robin (new flows)' roundrobin 'Same source IP, same server' source || return 1; W_STRATEGY=$GTM_REPLY;;
            *) W_STRATEGY=random;;
        esac
    else W_STRATEGY=single; fi
    if ((${#W_PORTS[@]}>1)) || [[ ${W_PORTS[0]} == *-* ]]; then
        if [[ $W_ENGINE == nftables ]]; then
            gtm_choose 'Remote ports' one 'Use the remote port(s) entered above' one 'Use the same port number as local' same 'Mapped: enter remote ports in the same order' map || return 1
        else
            gtm_choose 'Remote ports' one 'Use the remote port(s) entered above' one 'Use the same port number as local' same || return 1
        fi
        W_MAP=$GTM_REPLY
        [[ $W_MAP != map ]] || gtm_form_mapped || return 1
    fi
}

# One-to-one remote ports: the same number of items, each the same length.
gtm_form_mapped() {
    local input index local_first local_last
    printf '  Local: %s\n' "$(IFS=,; printf '%s' "${W_PORTS[*]}")"
    while true; do
        gtm_default 'Remote ports (same order)' input "$(IFS=,; printf '%s' "${W_MAPPED[*]}")" || return 1
        [[ $input != 0 ]] || return 1
        if gtm_parse_ports "$input" 1 1 && ((${#GTM_PORTS[@]} == ${#W_PORTS[@]})); then
            for ((index=0; index<${#W_PORTS[@]}; index++)); do
                gtm_port_span "${W_PORTS[$index]}"; local_first=$PS_FIRST local_last=$PS_LAST
                gtm_port_span "${GTM_PORTS[$index]}"
                ((PS_LAST - PS_FIRST == local_last - local_first)) || break
            done
            if ((index == ${#W_PORTS[@]})); then W_MAPPED=("${GTM_PORTS[@]}"); return 0; fi
        fi
        gtm_error 'Enter the same number of ports or ranges as local, each the same size (2000-2999 -> 3000-3999).'
    done
}

# Kernel forwards default to every local address of the destination family, so
# servers with additional IPs accept the forward on each of them. A specific
# local IP remains available under optional settings.
gtm_form_bind() {
    local family=4 any=0.0.0.0 first=${W_TARGETS%%,*}
    if [[ $W_ENGINE == haproxy || $W_ENGINE == realm ]]; then W_BIND=${W_BIND:-0.0.0.0}; return 0; fi
    gtm_target "$first" || return 1
    [[ $EP_IP != *:* ]] || { family=6; any=::; }
    if [[ -n $W_BIND ]] && { [[ $family == 6 && $W_BIND != *:* ]] || [[ $family == 4 && $W_BIND == *:* ]]; }; then W_BIND=''; fi
    W_BIND=${W_BIND:-$any}
    until gtm_ip "$W_BIND" && { [[ $family == 4 && $W_BIND != *:* ]] || [[ $family == 6 && $W_BIND == *:* ]]; }; do
        printf '  Use a local IPv%s address, or %s for all local addresses.\n' "$family" "$any"
        gtm_ask_ip 'Local IP' '' || return 1
        W_BIND=$GTM_REPLY
    done
}

gtm_form_advanced() {
    local selection input current
    while true; do
        gtm_header "$W_TITLE / Optional settings"
        gtm_option 1 'Tunnel name' "$W_NAME"
        gtm_option 2 'Listen address' "$W_BIND"
        [[ $W_ENGINE != iptables && $W_ENGINE != nftables ]] || gtm_option 3 'Client IP / interface'
        [[ $W_ENGINE == haproxy ]] || gtm_option 4 Protocol "$W_PROTO"
        gtm_option 0 'Back to review'
        gtm_read 'Select option' selection || return 1
        case $selection in
            0) return 0;;
            1) while true; do
                   gtm_default 'Name (optional)' input "$W_NAME" || return 1
                   if gtm_name "$input"; then W_NAME=$input; break; fi
                   gtm_error 'Use up to 40 letters, digits, spaces, dot, dash or underscore.'
               done;;
            2)
                current=$W_BIND
                [[ $current == 0.0.0.0 || $current == :: ]] || current=custom
                if [[ $W_ENGINE == haproxy || $W_ENGINE == realm ]]; then
                    gtm_choose 'Listen on' "$current" 'All IPv4 addresses' 0.0.0.0 'Specific local IP' custom 'All IPv6 addresses' :: || continue
                    if [[ $GTM_REPLY != custom ]]; then W_BIND=$GTM_REPLY; continue; fi
                else
                    # Kernel rules stay within the destination address family.
                    input=0.0.0.0; [[ ${W_TARGETS%%,*} != \[* ]] || input=::
                    [[ $current == custom ]] || current=$input
                    gtm_choose 'Listen on' "$current" 'All local addresses (additional IPs included)' "$input" 'Specific local IP' custom || continue
                    if [[ $GTM_REPLY != custom ]]; then W_BIND=$GTM_REPLY; continue; fi
                fi
                gtm_ask_ip 'Local IP' "$W_BIND" || continue
                W_BIND=$GTM_REPLY
                gtm_form_bind || return 1;;
            3)
                [[ $W_ENGINE == iptables || $W_ENGINE == nftables ]] || continue
                gtm_choose 'Client IP' "$W_SNAT" 'Normal forwarding' masquerade 'Keep client IP (requires return route)' preserve || continue
                W_SNAT=$GTM_REPLY
                current=custom; [[ $W_IFACE != any ]] || current=any
                gtm_choose 'Network interface' "$current" 'All interfaces' any 'Specific interface' custom || continue
                if [[ $GTM_REPLY == any ]]; then W_IFACE=any
                else
                    gtm_default 'Interface name (example: eth0)' input "$W_IFACE" || return 1
                    if gtm_iface "$input"; then W_IFACE=$input; else gtm_error 'Invalid interface name.'; fi
                fi;;
            4) [[ $W_ENGINE != haproxy ]] || continue
                gtm_choose Protocol "$W_PROTO" TCP tcp UDP udp 'TCP + UDP' both || continue
                W_PROTO=$GTM_REPLY;;
        esac
    done
}

gtm_form_rows() {
    local port target targets name index=0 remote
    local -a destinations=()
    GTM_FORM_ROWS=()
    IFS=, read -r -a destinations <<< "$W_TARGETS"
    for port in "${W_PORTS[@]}"; do
        targets=$W_TARGETS remote=''
        case $W_MAP in same) remote=$port;; map) remote=${W_MAPPED[$index]};; esac
        ((index+=1))
        if [[ -n $remote ]]; then
            targets=''
            for target in "${destinations[@]}"; do
                gtm_target "$target" || return 1
                targets+="${targets:+,}$(gtm_address "$EP_IP" "$remote")@$EP_WEIGHT"
            done
        fi
        name=$W_NAME
        if ((${#W_PORTS[@]}>1)); then
            if [[ $W_NAME == "$W_ENGINE-${W_PORTS[0]}" ]]; then name="$W_ENGINE-$port"
            else name="${W_NAME:0:32}-$port"; fi
        fi
        local row
        row=$(printf 'F000000\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s' "$name" "$W_ENGINE" "$W_PROTO" "$W_BIND" "$port" "$W_STRATEGY" "$W_ENABLED" "$W_SNAT" "$W_IFACE" "$targets" "$W_VERSION")
        [[ $W_VERSION == 1 ]] || row+=$'\t'"$W_OPTIONS"
        [[ $W_VERSION != 4 ]] || row+=$'\t'"$W_ROUTING"
        gtm_record_validate "$row" || { gtm_error 'Check the address family, ports and destinations.'; return 1; }
        GTM_FORM_ROWS+=("$row")
    done
}

gtm_form_save() {
    local line id result=1 last_id
    gtm_prepare && gtm_install_component "$W_ENGINE" || return 1
    for line in "${GTM_FORM_ROWS[@]}"; do
        gtm_record_validate "$line" || return 1
        gtm_legacy_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" || return 1
        if [[ $R_ENABLED == 1 && ( -z $W_EDIT || $R_BIND != "$W_OLD_BIND" || $R_PORT != "$W_OLD_PORT" || $R_PROTO != "$W_OLD_PROTO" ) ]]; then
            gtm_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" || return 1
        fi
    done
    gtm_lock || return 1
    if ! gtm_load_records; then gtm_unlock; return 1; fi
    for line in "${GTM_FORM_ROWS[@]}"; do
        if [[ -n $W_EDIT ]]; then
            line="$W_EDIT${line#F000000}"
            gtm_replace_record "$W_ORIGINAL" "$line" || { gtm_unlock; return 1; }
        else
            id=$(gtm_new_id) || { gtm_unlock; return 1; }
            line="$id${line#F000000}"
            GTM_RECORDS+=("$line"); last_id=$id
        fi
    done
    if [[ -n $last_id ]]; then
        printf '%d\n' "$((10#${last_id#F}))" > "$GTM_CONFIG_DIR/id-counter.tmp" && mv "$GTM_CONFIG_DIR/id-counter.tmp" "$GTM_CONFIG_DIR/id-counter" || { gtm_unlock; return 1; }
    fi
    gtm_commit; result=$?
    gtm_unlock
    return "$result"
}

gtm_new_forward() {
    local W_ENGINE=${1:-iptables} W_EDIT=${2:-} W_MODE=${3:-single} W_TITLE line target choice result
    local W_NAME='' W_BIND='' W_TARGETS='' W_PROTO=tcp W_STRATEGY=single W_ENABLED=1 W_SNAT=masquerade W_IFACE=any W_VERSION=1 W_OPTIONS='' W_ROUTING='' W_MAP=one
    local -a W_MAPPED=()
    local W_ORIGINAL='' W_OLD_BIND='' W_OLD_PORT='' W_OLD_PROTO=''
    local W_REMOTE_IP W_REMOTE_PORT W_REMOTE_WEIGHT
    local -a W_PORTS=() review_targets=()
    case $W_ENGINE in haproxy) W_TITLE=HAProxy; W_SNAT=preserve;; realm) W_TITLE=Realm; W_SNAT=preserve;; *) W_TITLE='Port Forwarding';; esac
    if [[ -n $W_EDIT ]]; then
        gtm_records || return 1
        for line in "${GTM_RECORDS[@]}"; do
            gtm_record_validate "$line" || return 1
            [[ $R_ID == "$W_EDIT" ]] || continue
            W_ORIGINAL=$line; W_NAME=$R_NAME; W_BIND=$R_BIND; W_PORTS=("$R_PORT"); W_TARGETS=$R_TARGETS
            W_PROTO=$R_PROTO; W_STRATEGY=$R_STRATEGY; W_ENABLED=$R_ENABLED; W_SNAT=$R_SNAT; W_IFACE=$R_IFACE; W_VERSION=$R_VERSION; W_OPTIONS=$R_OPTIONS; W_ROUTING=$R_ROUTING
            W_OLD_BIND=$R_BIND; W_OLD_PORT=$R_PORT; W_OLD_PROTO=$R_PROTO
            [[ $R_TARGETS != *,* ]] || W_MODE=balance
        done
        [[ -n $W_ORIGINAL ]] || { gtm_error 'Tunnel no longer exists.'; return 1; }
    fi
    if [[ -z $W_EDIT ]]; then
        case $W_ENGINE in
            haproxy) W_VERSION=2; W_OPTIONS='maxconn=0;server_maxconn=0;check_mode=off;log=off';;
            realm) W_VERSION=3; W_OPTIONS='log=off';;
        esac
    fi
    gtm_header "$W_TITLE / $([[ -n $W_EDIT ]] && printf 'Edit tunnel' || printf 'Add tunnel')"
    gtm_form_ports && gtm_form_targets && gtm_form_bind || return 1
    W_NAME=${W_NAME:-$W_ENGINE-${W_PORTS[0]}}
    while true; do
        gtm_header "$W_TITLE / Review"
        gtm_step 3 3 'Review & create'
        gtm_form_rows || return 1
        for line in "${GTM_FORM_ROWS[@]}"; do
            gtm_record_validate "$line" || return 1
            IFS=, read -r -a review_targets <<< "$R_TARGETS"
            for target in "${review_targets[@]}"; do
                gtm_target "$target" || return 1
                gtm_panel_wrap "Local $R_PORT  ->  $(gtm_address "$EP_IP" "$(gtm_span_text "$EP_PORT" "$EP_LAST")")"
                ((EP_WEIGHT==1)) || gtm_panel_wrap "  Target weight: $EP_WEIGHT"
            done
        done
        printf '\n  Name: %s\n  Protocol: %s\n' "$W_NAME" "${W_PROTO^^}"
        if [[ $W_BIND == 0.0.0.0 ]]; then printf '  Listen on: all IPv4 addresses\n'
        elif [[ $W_BIND == :: ]]; then printf '  Listen on: all IPv6 addresses\n'
        else printf '  Listen on: %s\n' "$W_BIND"; fi
        printf '  State: %s\n\n' "$([[ $W_ENABLED == 1 ]] && printf Enabled || printf Disabled)"
        [[ $W_TARGETS != *,* ]] || printf '  Balance: %s\n\n' "$W_STRATEGY"
        if [[ $W_ENGINE == iptables || $W_ENGINE == nftables ]]; then
            [[ $W_SNAT != preserve ]] || printf '  Client IP preserved / return route required\n'
            [[ $W_IFACE == any ]] || printf '  Interface: %s\n' "$W_IFACE"
        fi
        gtm_option 1 'Save & apply'
        gtm_option 2 'Change local ports'
        gtm_option 3 'Change remote server'
        gtm_option 4 'Optional settings' 'Name / listen address'
        gtm_option 0 Cancel
        gtm_read 'Select option' choice || return 1
        case $choice in
            1) gtm_form_save; result=$?; gtm_pause; return "$result";;
            2) gtm_form_ports || return 1;;
            3) gtm_form_targets && gtm_form_bind || return 1;;
            4) gtm_form_advanced || return 1;;
            0) return 0;;
            *) gtm_error 'Choose a number from the menu.';;
        esac
    done
}

# BEGIN MODULE: optimize
# Server optimization: opt-in sysctl groups for tunnel and forwarding servers.
# Nothing changes until a group is applied. Every applied key is journaled
# with its value from before the manager first changed it, each apply/remove
# saves an undo step, and Reset returns every key and removes every file.
# The drop-in sorts after other drop-ins (zz-), so these values win at boot;
# other files that set the same keys are reported, never edited. Caller locks.

gtm_optimize_paths() {
    GTM_OPT_DIR="$GTM_CONFIG_DIR/optimize"
    GTM_OPT_JOURNAL="$GTM_OPT_DIR/journal.tsv"
    GTM_OPT_STEPS="$GTM_OPT_DIR/steps"
    GTM_OPT_FILE="$GTM_SYSCTL_DIR/zz-gre-manager-optimize.conf"
    GTM_OPT_MODULES="$GTM_MODULES_DIR/gre-manager-optimize.conf"
    # Files written by the tuning menu of v1.3.7 and earlier; imported once.
    GTM_OPT_OLD_JOURNAL="$GTM_CONFIG_DIR/tuning.tsv"
    GTM_OPT_OLD_FILE="$GTM_SYSCTL_DIR/99-z-gre-manager-owned.conf"
    # Link settings (queue length, packet steering) are not sysctls: a
    # oneshot unit replays them at boot.
    GTM_OPT_LINK_SCRIPT="${GTM_RUNTIME%/*}/optimize-links.sh"
    GTM_OPT_LINK_UNIT="$GTM_SERVICE_DIR/gre-manager-optimize.service"
    GTM_SYSFS_NET=${GTM_SYSFS_NET:-/sys/class/net}
    # Host facts are read once per call: the catalog is rendered many times.
    [[ -n ${GTM_OPT_LINK_LIST+set} ]] || GTM_OPT_LINK_LIST=$(gtm_optimize_links)
    [[ -n ${GTM_OPT_CPU_COUNT:-} ]] || GTM_OPT_CPU_COUNT=$(gtm_optimize_cpus)
}

# Uplinks: interfaces of the IPv4/IPv6 default routes, at most four.
gtm_optimize_links() {
    local name
    {
        awk '$2 == "00000000" && $8 == "00000000" {print $1}' "${GTM_PROC_ROUTE:-/proc/net/route}" 2>/dev/null
        awk '$1 == "00000000000000000000000000000000" && $2 == "00" && $10 != "lo" {print $10}' "${GTM_PROC_ROUTE6:-/proc/net/ipv6_route}" 2>/dev/null
    } | awk '!seen[$0]++' | head -n 4 | while IFS= read -r name; do
        [[ $name =~ ^[A-Za-z0-9_.-]{1,15}$ && $name != lo && $name != gre* && -d $GTM_SYSFS_NET/$name ]] && printf '%s\n' "$name"
    done
}

gtm_optimize_cpus() {
    local cpus=${GTM_CPUS:-${GTM_OPT_CPU_COUNT:-}}
    [[ -n $cpus ]] || cpus=$(nproc 2>/dev/null) || cpus=1
    [[ $cpus =~ ^[0-9]{1,4}$ ]] || cpus=1
    printf '%d' "$((10#$cpus))"
}

# The CPU mask of every CPU, in lowercase hex without separators.
gtm_optimize_mask() {
    local cpus=$1 out='' index
    ((cpus % 4 == 0)) || out=$(printf '%x' "$(( (1 << (cpus % 4)) - 1 ))")
    for ((index = 0; index < cpus / 4; index++)); do out+=f; done
    printf '%s' "$out"
}

# Prints the receive queue count of a link.
gtm_optimize_rx_queues() {
    local queue count=0
    for queue in "$GTM_SYSFS_NET/$1"/queues/rx-*; do [[ ! -d $queue ]] || ((count+=1)); done
    printf '%d' "$count"
}

# group|key|value|mode|reason for the chosen profile (GTM_OPT_LEVEL and
# GTM_OPT_GOAL). No mode ever makes the server's own value worse, including
# the provider's image defaults: the original value is compared first and
# kept when it is already as good.
#   raise   only grow (limits, queues, buffers)
#   lower   only shrink (timeouts)
#   raise3  "min default max" triples, each field only grows
#   range   "low high" port range: low only drops, high only grows
#   prefer=A,B  keep the value when it is one of the listed equivalents
#   loose   reverse-path filter: strict (1) becomes loose (2); off (0) stays
#   rps     a CPU mask: kept when the server already steers packets
# A value of "-" means the profile leaves the key at its original value.
# Every profile lists the same keys, so switching profiles can return a key.
GTM_OPT_LEVELS='conservative balanced aggressive'
GTM_OPT_GOALS='general users latency'
# Below this, aggressive keeps balanced table and buffer sizes (a "2 GB" plan
# reports about 1.9 GiB, so it is not capped).
GTM_OPT_SMALL=$((1792 * 1048576))
declare -gA GTM_OPT_SET=()

gtm_optimize_profile_valid() {
    [[ $1 =~ ^[a-z]+$ && $2 =~ ^[a-z]+$ && " $GTM_OPT_LEVELS " == *" $1 "* && " $GTM_OPT_GOALS " == *" $2 "* ]]
}

# Prints 1 when the aggressive level is capped on this host.
gtm_optimize_capped() {
    local memory
    [[ ${GTM_OPT_LEVEL:-balanced} == aggressive ]] || { printf 0; return; }
    memory=$(gtm_optimize_memory) || memory=0
    if ((memory < GTM_OPT_SMALL)); then printf 1; else printf 0; fi
}

gtm_optimize_catalog() {
    local level=${GTM_OPT_LEVEL:-balanced} goal=${GTM_OPT_GOAL:-general}
    local memory limit=131072 cap=4194304 bucket_cap=2097152 buckets percent
    local established close backlog budget usecs somax syn buffer rmem wmem notsent ka kai kap fin
    local udp=60 stream=180 tw=- ports=-
    memory=$(gtm_optimize_memory) || memory=0
    case $level in
        conservative)
            percent=4 established=7200 close=60 backlog=8192 budget=400 usecs=4000 somax=4096 syn=4096
            buffer=16777216 rmem='4096 131072 16777216' wmem='4096 65536 16777216' notsent=-
            ka=1800 kai=60 kap=6 fin=30;;
        aggressive)
            percent=16 cap=8388608 bucket_cap=4194304 established=1800 close=15 backlog=65536 budget=1000 usecs=8000
            somax=65535 syn=65535 buffer=67108864 rmem='8192 262144 67108864' wmem='8192 131072 67108864'
            notsent=131072 ka=300 kai=15 kap=5 fin=10
            if [[ $(gtm_optimize_capped) == 1 ]]; then
                percent=8 cap=4194304 bucket_cap=2097152 backlog=32768
                buffer=33554432 rmem='4096 131072 33554432' wmem='4096 65536 33554432'
            fi;;
        *)
            percent=8 established=3600 close=30 backlog=16384 budget=600 usecs=8000 somax=8192 syn=8192
            buffer=33554432 rmem='4096 131072 33554432' wmem='4096 65536 33554432' notsent=131072
            ka=600 kai=30 kap=5 fin=15;;
    esac
    case $goal in
        users)
            ((somax >= 16384)) || somax=16384
            ((syn >= 16384)) || syn=16384
            ports='16384 65535'
            case $level in conservative) tw=262144;; aggressive) tw=1048576;; *) tw=524288;; esac;;
        latency) notsent=16384 udp=120 stream=300;;
    esac
    # About 350 bytes per tracked flow, within the level's share of memory, as a power of two.
    while ((limit * 2 <= memory * percent / 100 / 350 && limit < cap)); do limit=$((limit * 2)); done
    buckets=$(( limit / 2 > bucket_cap ? bucket_cap : limit / 2 ))
    printf '%s\n' \
        "conntrack|net.netfilter.nf_conntrack_max|$limit|raise|flow-limit" \
        "conntrack|net.netfilter.nf_conntrack_buckets|$buckets|raise|flow-buckets" \
        "conntrack|net.netfilter.nf_conntrack_tcp_timeout_established|$established|lower|idle-tcp" \
        "conntrack|net.netfilter.nf_conntrack_tcp_timeout_time_wait|$close|lower|closing-tcp" \
        "conntrack|net.netfilter.nf_conntrack_tcp_timeout_fin_wait|$close|lower|closing-tcp" \
        "conntrack|net.netfilter.nf_conntrack_tcp_timeout_close_wait|$close|lower|closing-tcp" \
        "conntrack|net.netfilter.nf_conntrack_udp_timeout|$udp|raise|udp" \
        "conntrack|net.netfilter.nf_conntrack_udp_timeout_stream|$stream|raise|udp-stream" \
        "queues|net.core.netdev_max_backlog|$backlog|raise|backlog" \
        "queues|net.core.netdev_budget|$budget|raise|budget" \
        "queues|net.core.netdev_budget_usecs|$usecs|raise|budget" \
        "queues|net.core.somaxconn|$somax|raise|accept-queue" \
        "queues|net.ipv4.tcp_max_syn_backlog|$syn|raise|syn-queue" \
        'relay|net.core.default_qdisc|fq|prefer=fq,cake,fq_pie|pacing' \
        'relay|net.ipv4.tcp_congestion_control|bbr|prefer=bbr,bbr2,bbr3|bbr' \
        "relay|net.core.rmem_max|$buffer|raise|buffers" \
        "relay|net.core.wmem_max|$buffer|raise|buffers" \
        "relay|net.ipv4.tcp_rmem|$rmem|raise3|buffers" \
        "relay|net.ipv4.tcp_wmem|$wmem|raise3|buffers" \
        "relay|net.ipv4.tcp_notsent_lowat|$notsent|lower|notsent" \
        'relay|net.ipv4.tcp_mtu_probing|1|raise|mtu-probing' \
        'relay|net.ipv4.tcp_slow_start_after_idle|0|lower|idle-restart' \
        "relay|net.ipv4.tcp_keepalive_time|$ka|lower|keepalive" \
        "relay|net.ipv4.tcp_keepalive_intvl|$kai|lower|keepalive" \
        "relay|net.ipv4.tcp_keepalive_probes|$kap|lower|keepalive" \
        "relay|net.ipv4.tcp_fin_timeout|$fin|lower|fin-timeout" \
        'relay|net.ipv4.tcp_tw_reuse|1|prefer=1|tw-reuse' \
        "relay|net.ipv4.ip_local_port_range|$ports|range|ports" \
        "relay|net.ipv4.tcp_max_tw_buckets|$tw|raise|tw-buckets" \
        'routing|net.ipv4.conf.all.rp_filter|2|loose|rp-filter' \
        'routing|net.ipv4.conf.default.rp_filter|2|loose|rp-filter' \
        'routing|net.ipv4.conf.all.send_redirects|0|lower|redirects' \
        'routing|net.ipv4.conf.default.send_redirects|0|lower|redirects' \
        'routing|net.ipv4.conf.all.accept_redirects|0|lower|accept-redirects' \
        'routing|net.ipv4.conf.default.accept_redirects|0|lower|accept-redirects'
    gtm_optimize_links_catalog
}

# A longer transmit queue absorbs bursts on fast uplinks; Low latency keeps
# the server's queue. Packet steering (RPS) spreads receive work of a
# single-queue card across every CPU; it is listed only where it helps.
gtm_optimize_links_catalog() {
    local level=${GTM_OPT_LEVEL:-balanced} goal=${GTM_OPT_GOAL:-general} link cpus txq rps
    cpus=$(gtm_optimize_cpus)
    case $level in conservative) txq=2000 rps=-;; aggressive) txq=10000 rps='';; *) txq=5000 rps='';; esac
    [[ $goal != latency ]] || txq=-
    while IFS= read -r link; do
        [[ -n $link ]] || continue
        [[ ! -f $GTM_SYSFS_NET/$link/tx_queue_len ]] || printf 'nic|link.%s.txqueuelen|%s|raise|txqueuelen\n' "$link" "$txq"
        if ((cpus >= 2 && cpus <= 1024)) && [[ $(gtm_optimize_rx_queues "$link") == 1 && -f $GTM_SYSFS_NET/$link/queues/rx-0/rps_cpus ]]; then
            printf 'nic|link.%s.rps|%s|rps|rps\n' "$link" "${rps:-$(gtm_optimize_mask "$cpus")}"
        fi
    done < <(if [[ -n ${GTM_OPT_LINK_LIST+set} ]]; then printf '%s\n' "$GTM_OPT_LINK_LIST"; else gtm_optimize_links; fi)
}

# Custom-value bounds: "n MIN MAX" (number), "n3 MIN MAX" (each field of a
# triple, ascending), "n2 MIN MAX" (low below high) or "c A,B" (choices).
gtm_optimize_bounds() {
    local memory flows
    case $1 in
        net.netfilter.nf_conntrack_max)
            memory=$(gtm_optimize_memory) || memory=0
            flows=$((memory / 4 / 350))
            ((flows <= 16777216)) || flows=16777216
            ((flows >= 65536)) || flows=65536
            printf 'n 32768 %d' "$flows";;
        net.netfilter.nf_conntrack_buckets) printf 'n 8192 4194304';;
        net.netfilter.nf_conntrack_tcp_timeout_established) printf 'n 300 432000';;
        net.netfilter.nf_conntrack_tcp_timeout_*) printf 'n 5 300';;
        net.netfilter.nf_conntrack_udp_timeout) printf 'n 10 600';;
        net.netfilter.nf_conntrack_udp_timeout_stream) printf 'n 30 3600';;
        net.core.netdev_max_backlog) printf 'n 1000 262144';;
        net.core.netdev_budget) printf 'n 300 5000';;
        net.core.netdev_budget_usecs) printf 'n 2000 32000';;
        net.core.somaxconn) printf 'n 128 65535';;
        net.ipv4.tcp_max_syn_backlog) printf 'n 128 262144';;
        net.core.default_qdisc) printf 'c fq,cake,fq_pie,fq_codel,pfifo_fast';;
        net.ipv4.tcp_congestion_control)
            printf 'c %s' "$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null | awk '{$1=$1; gsub(/ /, ","); print}')";;
        net.core.rmem_max|net.core.wmem_max) printf 'n 212992 268435456';;
        net.ipv4.tcp_rmem|net.ipv4.tcp_wmem) printf 'n3 4096 268435456';;
        net.ipv4.tcp_notsent_lowat) printf 'n 16384 4294967295';;
        net.ipv4.tcp_mtu_probing|net.ipv4.tcp_tw_reuse|net.ipv4.conf.all.rp_filter|net.ipv4.conf.default.rp_filter) printf 'n 0 2';;
        net.ipv4.tcp_slow_start_after_idle|net.ipv4.conf.*.send_redirects|net.ipv4.conf.*.accept_redirects) printf 'n 0 1';;
        net.ipv4.tcp_keepalive_time) printf 'n 60 7200';;
        net.ipv4.tcp_keepalive_intvl) printf 'n 5 120';;
        net.ipv4.tcp_keepalive_probes) printf 'n 3 10';;
        net.ipv4.tcp_fin_timeout) printf 'n 5 60';;
        net.ipv4.ip_local_port_range) printf 'n2 1024 65535';;
        net.ipv4.tcp_max_tw_buckets) printf 'n 4096 4194304';;
        link.*.txqueuelen) printf 'n 100 100000';;
        link.*.rps) printf 'c 0,%s' "$(gtm_optimize_mask "$(gtm_optimize_cpus)")";;
        *) return 1;;
    esac
}

# A custom value is valid for its key and inside its bounds.
gtm_optimize_custom_valid() {
    local key=$1 value=$2 bounds kind low high field previous=-1
    local -a fields=()
    gtm_optimize_value "$key" "$value" || return 1
    bounds=$(gtm_optimize_bounds "$key") || return 1
    read -r kind low high <<< "$bounds"
    case $kind in
        c) [[ -n $low && ",$low," == *",$value,"* ]];;
        n) ((10#$value >= low && 10#$value <= high));;
        n2|n3)
            read -r -a fields <<< "$value"
            for field in "${fields[@]}"; do
                ((10#$field >= low && 10#$field <= high)) || return 1
                if [[ $kind == n2 ]]; then ((10#$field > previous)) || return 1; else ((10#$field >= previous)) || return 1; fi
                previous=$((10#$field))
            done;;
        *) return 1;;
    esac
}

# Reads "key=value" custom values into GTM_OPT_SET; refuses unknown keys or
# values outside their bounds.
gtm_optimize_custom() {
    local pair key value
    declare -gA GTM_OPT_SET=()
    (($# <= 40)) || { gtm_error 'Too many custom values.'; return 2; }
    for pair in "$@"; do
        [[ $pair == *=* ]] || { gtm_error 'Custom values are key=value.'; return 2; }
        key=${pair%%=*} value=${pair#*=}
        gtm_optimize_custom_valid "$key" "$value" || { gtm_error "Custom value for $key is outside its allowed range."; return 2; }
        GTM_OPT_SET[$key]=$value
    done
}

# Keys this module may write: the catalog plus keys imported from v1.3.7.
gtm_optimize_key() {
    case $1 in
        net.netfilter.nf_conntrack_max|net.netfilter.nf_conntrack_buckets|net.netfilter.nf_conntrack_tcp_timeout_established|\
        net.netfilter.nf_conntrack_tcp_timeout_time_wait|net.netfilter.nf_conntrack_tcp_timeout_fin_wait|\
        net.netfilter.nf_conntrack_tcp_timeout_close_wait|net.netfilter.nf_conntrack_udp_timeout|\
        net.netfilter.nf_conntrack_udp_timeout_stream|net.core.netdev_max_backlog|net.core.netdev_budget|\
        net.core.netdev_budget_usecs|net.core.somaxconn|net.ipv4.tcp_max_syn_backlog|net.core.default_qdisc|\
        net.ipv4.tcp_congestion_control|net.core.rmem_max|net.core.wmem_max|net.ipv4.tcp_rmem|net.ipv4.tcp_wmem|\
        net.ipv4.tcp_mtu_probing|net.ipv4.tcp_slow_start_after_idle|net.ipv4.tcp_keepalive_time|\
        net.ipv4.tcp_keepalive_intvl|net.ipv4.tcp_keepalive_probes|net.ipv4.tcp_fin_timeout|net.ipv4.tcp_tw_reuse|\
        net.ipv4.tcp_notsent_lowat|net.ipv4.conf.all.rp_filter|net.ipv4.conf.default.rp_filter|\
        net.ipv4.conf.all.send_redirects|net.ipv4.conf.default.send_redirects|\
        net.ipv4.conf.all.accept_redirects|net.ipv4.conf.default.accept_redirects|\
        net.ipv4.ip_local_port_range|net.ipv4.tcp_max_tw_buckets) return 0;;
    esac
    [[ $1 =~ ^link\.[A-Za-z0-9_.-]{1,15}\.(txqueuelen|rps)$ ]]
}

gtm_optimize_value() {
    gtm_optimize_key "$1" || return 1
    case $1 in
        net.core.default_qdisc|net.ipv4.tcp_congestion_control) [[ $2 =~ ^[a-z0-9_]{1,16}$ ]];;
        net.ipv4.tcp_rmem|net.ipv4.tcp_wmem) [[ $2 =~ ^[0-9]{1,10}\ [0-9]{1,10}\ [0-9]{1,10}$ ]];;
        net.ipv4.ip_local_port_range) [[ $2 =~ ^[0-9]{1,5}\ [0-9]{1,5}$ ]];;
        link.*.txqueuelen) [[ $2 =~ ^[0-9]{1,6}$ ]];;
        link.*.rps) [[ $2 =~ ^(0|[1-9a-f][0-9a-f]{0,255})$ ]];;
        *) [[ $2 =~ ^[0-9]{1,10}$ ]];;
    esac
}

gtm_optimize_memory() { awk '$1 == "MemTotal:" {printf "%d", $2 * 1024; found=1; exit} END {exit !found}' "${GTM_MEMINFO:-/proc/meminfo}" 2>/dev/null; }

gtm_optimize_link_of() { local key=${1#link.}; printf '%s' "${key%.*}"; }

gtm_optimize_read() {
    local value link
    local -a parts=()
    if [[ $1 == link.* ]]; then
        gtm_optimize_key "$1" || return 1
        link=$(gtm_optimize_link_of "$1")
        if [[ $1 == *.txqueuelen ]]; then
            [[ -r $GTM_SYSFS_NET/$link/tx_queue_len ]] && value=$(< "$GTM_SYSFS_NET/$link/tx_queue_len") || return 1
        else
            # sysfs prints comma-separated 32-bit groups with leading zeros.
            value=$(cat "$GTM_SYSFS_NET/$link/queues/rx-0/rps_cpus" 2>/dev/null) || return 1
            value=$(tr -d ', \n' <<< "$value" | tr 'A-F' 'a-f' | sed 's/^0*//')
            value=${value:-0}
        fi
        read -r -a parts <<< "$value"; value=${parts[*]}
        gtm_optimize_value "$1" "$value" || return 1
        printf '%s' "$value"; return 0
    fi
    value=$(sysctl -n "$1" 2>/dev/null) || return 1
    read -r -a parts <<< "$value"; value=${parts[*]}
    gtm_optimize_value "$1" "$value" || return 1
    printf '%s' "$value"
}

# The flow limit may never drop below the flows tracked right now.
# A CPU mask in the comma-separated 32-bit groups sysfs expects.
gtm_optimize_mask_groups() {
    local mask=$1 out=''
    while ((${#mask} > 8)); do out=",${mask: -8}$out"; mask=${mask:0:${#mask}-8}; done
    printf '%s%s' "$mask" "$out"
}

gtm_optimize_write_link() {
    local link queue
    link=$(gtm_optimize_link_of "$1")
    if [[ $1 == *.txqueuelen ]]; then
        printf '%s' "$2" > "$GTM_SYSFS_NET/$link/tx_queue_len" 2>/dev/null; return
    fi
    for queue in "$GTM_SYSFS_NET/$link"/queues/rx-*/rps_cpus; do
        [[ -f $queue ]] || return 1
        printf '%s' "$(gtm_optimize_mask_groups "$2")" > "$queue" 2>/dev/null || return 1
    done
}

gtm_optimize_write() {
    local count
    [[ $1 != link.* ]] || { gtm_optimize_write_link "$1" "$2"; return; }
    if [[ $1 == net.netfilter.nf_conntrack_max ]]; then
        count=$(sysctl -n net.netfilter.nf_conntrack_count 2>/dev/null) && [[ $count =~ ^[0-9]{1,10}$ ]] || { gtm_error 'Cannot read the tracked flow count; limit kept.'; return 1; }
        ((10#$2 >= 10#$count)) || { gtm_error "Flow limit $2 is below the $count tracked flows; limit kept."; return 1; }
    fi
    sysctl -w "$1=$2" >/dev/null
}

# Journal rows: key, before, applied, group. Loads into GTM_OPT_ROWS.
gtm_optimize_load() {
    local file=${1:-$GTM_OPT_JOURNAL} key before applied group extra
    local -A seen=()
    GTM_OPT_ROWS=()
    [[ -e $file || -L $file ]] || return 0
    [[ -f $file && ! -L $file ]] || { gtm_error 'Optimization journal is not a regular file.'; return 1; }
    while IFS=$'\t' read -r key before applied group extra || [[ -n $key ]]; do
        [[ -n $key && $key != '#'* ]] || continue
        if [[ -n $extra || ${seen[$key]+set} || ! $group =~ ^(conntrack|queues|relay|routing|nic|previous)$ ]] || ! gtm_optimize_value "$key" "$before" || ! gtm_optimize_value "$key" "$applied"; then
            gtm_error 'Invalid optimization journal. Nothing was changed.'; return 1
        fi
        seen[$key]=1; GTM_OPT_ROWS+=("$key"$'\t'"$before"$'\t'"$applied"$'\t'"$group")
    done < "$file"
}

gtm_optimize_save_rows() {
    local target=$1 temp
    mkdir -p "${target%/*}" && chmod 700 "$GTM_OPT_DIR" || return 1
    temp=$(mktemp "${target%/*}/.journal.XXXXXX") || return 1
    { printf '# Traffic Manager optimization v2: key / before / applied / group\n'
      ((${#GTM_OPT_ROWS[@]} == 0)) || printf '%s\n' "${GTM_OPT_ROWS[@]}" | LC_ALL=C sort; } > "$temp"
    chmod 600 "$temp" && mv "$temp" "$target" || { rm -f "$temp"; return 1; }
}

gtm_optimize_render() {
    local row key before applied group
    printf '# Traffic Manager owned. Change or remove it from the panel (Optimization).\n'
    while IFS=$'\t' read -r key before applied group; do
        [[ -n $key && $key != link.* ]] && printf '%s = %s\n' "$key" "$applied"
    done < <(((${#GTM_OPT_ROWS[@]} == 0)) || printf '%s\n' "${GTM_OPT_ROWS[@]}" | LC_ALL=C sort)
}

# The boot script for link rows; empty when none are applied. Link names
# and values are validated, so they are safe inside double quotes.
gtm_optimize_links_render() {
    local key before applied group link found=0
    while IFS=$'\t' read -r key before applied group; do
        [[ $key == link.* ]] || continue
        ((found)) || printf '#!/bin/sh\n# Traffic Manager owned. Change or remove it from the panel (Optimization).\nn=%s\n' "$GTM_SYSFS_NET"
        found=1; link=$(gtm_optimize_link_of "$key")
        if [[ $key == *.txqueuelen ]]; then
            printf '[ -w "$n/%s/tx_queue_len" ] && printf %%s %s > "$n/%s/tx_queue_len"\n' "$link" "$applied" "$link"
        else
            printf 'for q in "$n/%s"/queues/rx-*/rps_cpus; do [ -w "$q" ] && printf %%s %s > "$q"; done\n' "$link" "$(gtm_optimize_mask_groups "$applied")"
        fi
    done < <(((${#GTM_OPT_ROWS[@]} == 0)) || printf '%s\n' "${GTM_OPT_ROWS[@]}" | LC_ALL=C sort)
    ((found == 0)) || printf 'exit 0\n'
}

gtm_optimize_unit_render() {
    printf '%s\n' '[Unit]' 'Description=Traffic Manager link optimization (queue length, packet steering)' \
        'After=network-online.target' 'Wants=network-online.target' '' '[Service]' 'Type=oneshot' \
        "ExecStart=/bin/sh $GTM_OPT_LINK_SCRIPT" 'RemainAfterExit=yes' '' '[Install]' 'WantedBy=multi-user.target'
}

gtm_optimize_modules_render() {
    local row needs_conntrack=0 needs_bbr=0
    for row in "${GTM_OPT_ROWS[@]}"; do
        [[ $row != net.netfilter.* ]] || needs_conntrack=1
        [[ $row != net.ipv4.tcp_congestion_control$'\t'*$'\t'bbr$'\t'* ]] || needs_bbr=1
    done
    ((needs_conntrack || needs_bbr)) || return 0
    printf '# Traffic Manager owned: load modules before sysctl at boot.\n'
    ((needs_conntrack == 0)) || printf 'nf_conntrack\n'
    ((needs_bbr == 0)) || printf 'tcp_bbr\n'
}

# Writes (or removes) an owned file unless someone edited it since.
gtm_optimize_owned_file() {
    local path=$1 content=$2 previous=$3 temp
    if [[ -e $path || -L $path ]]; then
        [[ -f $path && ! -L $path ]] && cmp -s "$path" <(printf '%s' "$previous") || { gtm_error "Kept the edited file $path; reconcile it by hand."; return 1; }
    fi
    if [[ -z $content ]]; then rm -f "$path"; return; fi
    [[ -d ${path%/*} ]] || return 0
    temp=$(mktemp "${path%/*}/.gre-manager.XXXXXX") || return 1
    printf '%s' "$content" > "$temp" && chmod 644 "$temp" && mv "$temp" "$path" || { rm -f "$temp"; return 1; }
}

# Persists GTM_OPT_ROWS: journal, drop-in and module list. GTM_OPT_PREVIOUS
# holds the rows the files on disk were rendered from.
gtm_optimize_persist() {
    local -a next=("${GTM_OPT_ROWS[@]}") prior=(${GTM_OPT_PREVIOUS[@]+"${GTM_OPT_PREVIOUS[@]}"})
    local conf='' modules='' old_conf old_modules links old_links unit='' old_unit=''
    GTM_OPT_ROWS=("${prior[@]}"); old_conf=''; old_modules=$(gtm_optimize_modules_render); old_links=$(gtm_optimize_links_render)
    ((${#prior[@]} == 0)) || old_conf=$(gtm_optimize_render; printf x); old_conf=${old_conf%x}
    GTM_OPT_ROWS=("${next[@]}"); modules=$(gtm_optimize_modules_render); links=$(gtm_optimize_links_render)
    ((${#next[@]} == 0)) || conf=$(gtm_optimize_render; printf x); conf=${conf%x}
    [[ -z $modules ]] || modules+=$'\n'; [[ -z $old_modules ]] || old_modules+=$'\n'
    [[ -z $links ]] || { links+=$'\n'; unit=$(gtm_optimize_unit_render)$'\n'; }
    [[ -z $old_links ]] || { old_links+=$'\n'; old_unit=$(gtm_optimize_unit_render)$'\n'; }
    [[ -z $links ]] || mkdir -p "${GTM_OPT_LINK_SCRIPT%/*}" || return 1
    gtm_optimize_save_rows "$GTM_OPT_JOURNAL" && gtm_optimize_owned_file "$GTM_OPT_FILE" "$conf" "$old_conf" &&
        gtm_optimize_owned_file "$GTM_OPT_MODULES" "$modules" "$old_modules" &&
        gtm_optimize_owned_file "$GTM_OPT_LINK_SCRIPT" "$links" "$old_links" || return 1
    [[ -n $unit || -n $old_unit ]] || return 0
    gtm_optimize_owned_file "$GTM_OPT_LINK_UNIT" "$unit" "$old_unit" || return 1
    [[ -z $unit || -z $old_unit ]] || return 0
    command -v systemctl >/dev/null 2>&1 || return 0
    if [[ -n $unit ]]; then systemctl daemon-reload && systemctl enable gre-manager-optimize.service >/dev/null 2>&1
    else systemctl disable gre-manager-optimize.service >/dev/null 2>&1; systemctl daemon-reload; fi ||
        printf 'Warning: the boot unit for link settings could not be updated; the settings apply until reboot.\n' >&2
    return 0
}

# Saves the journal as the newest undo step; keeps the last 20.
gtm_optimize_push_step() {
    local name file last stamp seq=1
    mkdir -p "$GTM_OPT_STEPS" && chmod 700 "$GTM_OPT_DIR" "$GTM_OPT_STEPS" || return 1
    # Names sort in save order: a sequence number after the UTC second keeps
    # two steps saved within one second (or after a clock step back) in order.
    last=$(gtm_optimize_last_step); last=${last##*/}; last=${last%.tsv}
    stamp=$(date -u +%Y%m%dT%H%M%S)
    if [[ $last =~ ^([0-9]{8}T[0-9]{6})-([0-9]{6})$ ]]; then
        seq=$(( (10#${BASH_REMATCH[2]} + 1) % 1000000 ))
        [[ ! $stamp < ${BASH_REMATCH[1]} ]] || stamp=${BASH_REMATCH[1]}
    fi
    name=$stamp-$(printf '%06d' "$seq")
    GTM_OPT_ROWS=(${GTM_OPT_PREVIOUS[@]+"${GTM_OPT_PREVIOUS[@]}"})
    gtm_optimize_save_rows "$GTM_OPT_STEPS/$name.tsv" || return 1
    while IFS= read -r file; do rm -f "$file"; done < <(ls -1 "$GTM_OPT_STEPS"/*.tsv 2>/dev/null | LC_ALL=C sort | head -n -20)
}

gtm_optimize_last_step() { ls -1 "$GTM_OPT_STEPS"/*.tsv 2>/dev/null | LC_ALL=C sort | tail -n 1; }

# Imports the v1.3.7 tuning journal once: its original values stay the
# baseline, its drop-in is replaced by ours. Unknown edits stop the import.
gtm_optimize_import() {
    local row key before applied backup
    local -a imported=()
    [[ -f $GTM_OPT_OLD_JOURNAL ]] || return 0
    while IFS=$'\t' read -r key before applied || [[ -n $key ]]; do
        [[ -n $key && $key != '#'* ]] || continue
        gtm_optimize_value "$key" "$before" && gtm_optimize_value "$key" "$applied" || { gtm_error "The old tuning journal has an unknown entry ($key); review $GTM_OPT_OLD_JOURNAL."; return 1; }
        imported+=("$key"$'\t'"$before"$'\t'"$applied"$'\tprevious')
    done < "$GTM_OPT_OLD_JOURNAL"
    gtm_optimize_load || return 1
    for row in "${GTM_OPT_ROWS[@]}"; do [[ " ${imported[*]%%$'\t'*} " != *" ${row%%$'\t'*} "* ]] && imported+=("$row"); done
    backup="$GTM_CONFIG_DIR/backups/tuning-import-$(date -u +%Y%m%dT%H%M%S)-$$"
    mkdir -p "$backup" && chmod 700 "$backup" && cp "$GTM_OPT_OLD_JOURNAL" "$backup/" || return 1
    [[ ! -f $GTM_OPT_OLD_FILE ]] || cp "$GTM_OPT_OLD_FILE" "$backup/" || return 1
    GTM_OPT_PREVIOUS=(${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"}); GTM_OPT_ROWS=("${imported[@]}")
    gtm_optimize_persist || return 1
    rm -f "$GTM_OPT_OLD_FILE" "$GTM_OPT_OLD_JOURNAL" "$GTM_CONFIG_DIR/tuning-previous.tsv"
    printf 'Imported the earlier tuning; its original values remain the reset target. Backup: %s\n' "$backup"
}

# Fills GTM_OPT_OTHERS[key]="file<TAB>value" with the last other drop-in that
# sets key. Ours sorts after them, so ours wins at boot; they are only shown.
gtm_optimize_others() {
    local LC_ALL=C dir file name line key ours
    local -A first=()
    declare -gA GTM_OPT_OTHERS=()
    ours=${GTM_OPT_FILE##*/}
    for dir in $GTM_SYSCTL_SCAN; do
        for file in "$dir"/*.conf; do
            [[ -f $file ]] || continue
            name=${file##*/}
            [[ $name == "$ours" || ${first[$name]+set} ]] || first[$name]=$file
        done
    done
    while IFS= read -r name; do
        [[ -n $name ]] || continue
        while IFS= read -r line || [[ -n $line ]]; do
            [[ $line =~ ^[[:space:]]*-?([a-z0-9_./]+)[[:space:]]*=[[:space:]]*(.*[^[:space:]])[[:space:]]*$ ]] || continue
            key=${BASH_REMATCH[1]//\//.}
            gtm_optimize_key "$key" && GTM_OPT_OTHERS[$key]="${first[$name]}"$'\t'"${BASH_REMATCH[2]}"
        done < "${first[$name]}"
    done < <(printf '%s\n' "${!first[@]}" | sort)
}

# ServerTools (github.com/Sir-Adnan/server-tools) tunes the same subsystems.
gtm_optimize_servertools() {
    local file
    for file in "$GTM_SYSCTL_DIR"/99-zz-server-tools*.conf "$GTM_MODULES_DIR/server-tools.conf"; do
        [[ ! -f $file ]] || printf '%s\n' "$file"
    done
}

# The recommended value for key given its live value and mode: never worse
# than what the server already has.
gtm_optimize_better() {
    local current=$1 wanted=$2 mode=$3 a b out='' index
    local -a have=() want=()
    case $mode in
        raise) ((10#$current >= 10#$wanted)) && printf '%s' "$current" || printf '%s' "$wanted";;
        lower) ((10#$current <= 10#$wanted)) && printf '%s' "$current" || printf '%s' "$wanted";;
        raise3)
            read -r -a have <<< "$current"; read -r -a want <<< "$wanted"
            for index in 0 1 2; do
                a=${have[$index]}; b=${want[$index]}
                out+="$(( 10#$a > 10#$b ? 10#$a : 10#$b ))"; ((index == 2)) || out+=' '
            done
            printf '%s' "$out";;
        range)
            read -r -a have <<< "$current"; read -r -a want <<< "$wanted"
            printf '%d %d' "$(( 10#${have[0]} < 10#${want[0]} ? 10#${have[0]} : 10#${want[0]} ))" "$(( 10#${have[1]} > 10#${want[1]} ? 10#${have[1]} : 10#${want[1]} ))";;
        prefer=*) [[ ",${mode#prefer=}," == *",$current,"* ]] && printf '%s' "$current" || printf '%s' "$wanted";;
        loose) [[ $current == 1 ]] && printf 2 || printf '%s' "$current";;
        rps) [[ $current != 0 ]] && printf '%s' "$current" || printf '%s' "$wanted";;
        *) printf '%s' "$wanted";;
    esac
}

# A wider port range never takes a port a service listens on right now: the
# low end then stays where it is.
gtm_optimize_ports() {
    local now_low now_high low high port
    read -r now_low now_high <<< "$1"; read -r low high <<< "$2"
    if ((10#$low < 10#$now_low)); then
        while IFS= read -r port; do
            [[ $port =~ ^[0-9]{1,5}$ ]] && ((10#$port >= 10#$low && 10#$port < 10#$now_low)) && { low=$now_low; break; }
        done < <(ss -Hltnu 2>/dev/null | awk '{n = split($5, part, ":"); print part[n]}')
    fi
    printf '%s %s' "$low" "$high"
}

# Sets GTM_OPT_PLAN rows "group key current value reason note" for groups.
# Note: change, same (already the recommendation), kept (the server's own
# value is already better and stays), off (the profile leaves the key at its
# original value), custom (a custom value), worse (a custom value worse than
# the original) or missing (no such key or algorithm). Keys the panel applied
# compare against their original value, so a lighter profile can return them.
gtm_optimize_compute() {
    local groups=" $* " group key wanted value mode reason current note base row before applied
    local -A before_of=() applied_of=()
    GTM_OPT_PLAN=()
    for row in ${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"}; do
        IFS=$'\t' read -r key before applied group <<< "$row"
        before_of[$key]=$before applied_of[$key]=$applied
    done
    # BBR may be a module that is not loaded yet; loading it changes nothing else.
    if [[ ${GTM_OPT_READONLY:-0} == 0 && $groups == *' relay '* && " $(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null) " != *' bbr '* ]]; then
        command -v modprobe >/dev/null 2>&1 && modprobe tcp_bbr 2>/dev/null
    fi
    while IFS='|' read -r group key wanted mode reason; do
        [[ $groups == *" $group "* ]] || continue
        value=$wanted; note=change
        if ! current=$(gtm_optimize_read "$key"); then
            current=-; note=missing
        else
            # Only while the live value is still what the panel applied.
            base=$current
            [[ ${applied_of[$key]-} != "$current" ]] || base=${before_of[$key]}
            if [[ ${GTM_OPT_SET[$key]+set} ]]; then
                value=${GTM_OPT_SET[$key]} note=custom
                [[ $(gtm_optimize_better "$base" "$value" "$mode") == "$value" ]] || note=worse
                [[ $value != "$current" ]] || note=same
            elif [[ $wanted == - ]]; then
                value=$base
                [[ $value != "$current" ]] || note=off
            elif [[ $key == net.ipv4.tcp_congestion_control && " $(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null) " != *" $wanted "* && $mode != *",$current"* && $mode != *"=$current"* ]]; then
                note=missing
            else
                value=$(gtm_optimize_better "$base" "$wanted" "$mode")
                [[ $key != net.ipv4.ip_local_port_range ]] || value=$(gtm_optimize_ports "$current" "$value")
                if [[ $value == "$current" ]]; then
                    note=kept; [[ $current != "$wanted" ]] || note=same
                fi
            fi
        fi
        GTM_OPT_PLAN+=("$group"$'\t'"$key"$'\t'"$current"$'\t'"$value"$'\t'"$reason"$'\t'"$note")
    done < <(gtm_optimize_catalog)
}

# The profile last applied ("level goal"); balanced general before any.
gtm_optimize_saved_profile() {
    local level goal
    [[ -f $GTM_OPT_DIR/profile ]] && read -r level goal < "$GTM_OPT_DIR/profile" && gtm_optimize_profile_valid "$level" "$goal" ||
        { level=balanced goal=general; }
    printf '%s %s' "$level" "$goal"
}

# Selects the profile for this call: "LEVEL GOAL", or the saved one for "-".
gtm_optimize_use_profile() {
    local level=$1 goal=$2
    gtm_optimize_paths
    [[ $level != - ]] || read -r level goal <<< "$(gtm_optimize_saved_profile)"
    gtm_optimize_profile_valid "$level" "$goal" || { gtm_error 'Unknown optimization profile.'; return 2; }
    GTM_OPT_LEVEL=$level GTM_OPT_GOAL=$goal
}

gtm_optimize_groups_valid() {
    local group
    (($#)) || return 1
    for group in "$@"; do [[ $group =~ ^(conntrack|queues|relay|routing|nic)$ ]] || return 1; done
}

# Read-only preview: one "change" row per catalog key of the groups.
gtm_optimize_plan() {
    local row key
    gtm_optimize_groups_valid "$@" || { gtm_error 'Unknown optimization group.'; return 2; }
    gtm_optimize_paths
    gtm_optimize_load || return 1
    gtm_optimize_compute "$@"
    gtm_optimize_others
    for row in "${GTM_OPT_PLAN[@]}"; do
        key=$(cut -f2 <<< "$row")
        printf 'change\t%s\t%s\t%s\n' "$row" "${GTM_OPT_OTHERS[$key]:-$'-\t-'}" "$(gtm_optimize_bounds "$key" || printf -)"
    done
}

# Read-only state: host facts, owned files, undo depth and every catalog key
# with its recommendation for this server (value, reason, note).
gtm_optimize_status() {
    local row key before applied group current steps=0 file value reason note
    local -A journal=() advice=()
    gtm_optimize_paths
    gtm_optimize_load || return 1
    for row in "${GTM_OPT_ROWS[@]}"; do IFS=$'\t' read -r key before applied group <<< "$row"; journal[$key]="$before"$'\t'"$applied"$'\t'"$group"; done
    printf 'meta\tmemory\t%s\n' "$(gtm_optimize_memory || printf 0)"
    printf 'meta\tflows\t%s\n' "$(sysctl -n net.netfilter.nf_conntrack_count 2>/dev/null || printf -)"
    printf 'meta\tcongestion\t%s\n' "$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null || printf -)"
    [[ -d $GTM_OPT_STEPS ]] && steps=$(ls -1 "$GTM_OPT_STEPS"/*.tsv 2>/dev/null | wc -l)
    printf 'meta\tsteps\t%d\n' "$steps"
    file=$(gtm_optimize_last_step)
    [[ -z $file ]] || printf 'meta\tlast\t%s\n' "$(stat -c %Y "$file" 2>/dev/null || printf 0)"
    printf 'meta\tprofile\t%s\n' "$(gtm_optimize_saved_profile)"
    printf 'meta\tview\t%s %s\n' "${GTM_OPT_LEVEL:-balanced}" "${GTM_OPT_GOAL:-general}"
    printf 'meta\tcapped\t%s\n' "$(gtm_optimize_capped)"
    printf 'meta\tcpus\t%s\n' "$(gtm_optimize_cpus)"
    while IFS= read -r file; do [[ -z $file ]] || printf 'meta\tlink\t%s %s\n' "$file" "$(gtm_optimize_rx_queues "$file")"; done <<< "$GTM_OPT_LINK_LIST"
    printf 'meta\tfile\t%s\n' "$GTM_OPT_FILE"
    [[ ! -f $GTM_OPT_OLD_JOURNAL ]] || printf 'meta\timport\t%s\n' "$GTM_OPT_OLD_JOURNAL"
    while IFS= read -r file; do [[ -z $file ]] || printf 'meta\tservertools\t%s\n' "$file"; done < <(gtm_optimize_servertools)
    gtm_optimize_others
    GTM_OPT_READONLY=1 gtm_optimize_compute conntrack queues relay routing nic
    for row in "${GTM_OPT_PLAN[@]}"; do
        IFS=$'\t' read -r group key current value reason note <<< "$row"
        advice[$key]="$current"$'\t'"$value"$'\t'"$reason"$'\t'"$note"
    done
    while IFS='|' read -r group key _; do
        IFS=$'\t' read -r current value reason note <<< "${advice[$key]}"
        printf 'key\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$group" "$key" "$current" "${journal[$key]:-$'-\t-\t-'}" "${GTM_OPT_OTHERS[$key]:-$'-\t-'}" "$value" "$reason" "$note"
        unset 'journal[$key]'
    done < <(gtm_optimize_catalog)
    # Imported keys outside the catalog stay visible until reset.
    for key in "${!journal[@]}"; do
        current=$(gtm_optimize_read "$key") || current=-
        printf 'key\tprevious\t%s\t%s\t%s\t-\t-\t-\t-\t-\n' "$key" "$current" "${journal[$key]}"
    done
}

# Rows whose live value differs from what the manager applied were changed
# by someone else: those keys are released (left as they are), not reverted.
gtm_optimize_check_live() {
    local row key before applied group current
    GTM_OPT_LIVE=()
    GTM_OPT_RELEASED=()
    for row in "${GTM_OPT_ROWS[@]}"; do
        IFS=$'\t' read -r key before applied group <<< "$row"
        current=$(gtm_optimize_read "$key") || current=-
        if [[ $current == "$applied" ]]; then GTM_OPT_LIVE+=("$row")
        else GTM_OPT_RELEASED+=("$key"); printf 'Left %s = %s; it was changed outside the panel.\n' "$key" "$current"; fi
    done
}

gtm_optimize_apply() {
    local row group key current value reason note failed=0 written=0
    local -a attempts=() done_rows=()
    local -A rows=()
    gtm_optimize_groups_valid "$@" || { gtm_error 'Unknown optimization group.'; return 2; }
    gtm_optimize_paths
    gtm_optimize_import && gtm_optimize_load || return 1
    GTM_OPT_PREVIOUS=(${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"})
    gtm_optimize_check_live
    for row in ${GTM_OPT_LIVE[@]+"${GTM_OPT_LIVE[@]}"}; do rows[${row%%$'\t'*}]=$row; done
    gtm_optimize_compute "$@"
    printf 'Profile %s / %s. Server-wide settings (they do not promise a number of users):\n' "${GTM_OPT_LEVEL:-balanced}" "${GTM_OPT_GOAL:-general}"
    for row in "${GTM_OPT_PLAN[@]}"; do
        IFS=$'\t' read -r group key current value reason note <<< "$row"
        case $note in
            same) printf '  %s = %s (already set)\n' "$key" "$current"; continue;;
            kept) printf '  %s = %s (the server value is already better; kept)\n' "$key" "$current"; continue;;
            off) continue;;
            missing) printf '  %s: not available on this kernel; skipped\n' "$key"; continue;;
            worse) [[ ${GTM_OPT_ALLOW_WORSE:-0} == 1 ]] || { gtm_error "The custom value for $key is worse than the server's original value; confirm it to apply."; return 1; }
                printf '  %s: %s -> %s (custom; worse than the original value)\n' "$key" "$current" "$value";;
            *) printf '  %s: %s -> %s\n' "$key" "$current" "$value";;
        esac
        attempts+=("$key"$'\t'"$current"$'\t'"$value"$'\t'"$group")
    done
    ((${#attempts[@]})) || { printf 'Nothing to change.\n'; return 0; }
    gtm_confirm || return 1
    # The undo step and journal are durable before the first live write. A
    # key that returns to its original value is no longer tracked.
    for row in "${attempts[@]}"; do
        IFS=$'\t' read -r key current value group <<< "$row"
        if [[ ${rows[$key]+set} ]]; then IFS=$'\t' read -r _ current _ _ <<< "${rows[$key]}"; fi
        if [[ $value == "$current" ]]; then unset 'rows[$key]'; continue; fi
        rows[$key]="$key"$'\t'"$current"$'\t'"$value"$'\t'"$group"
    done
    GTM_OPT_ROWS=(); for key in "${!rows[@]}"; do GTM_OPT_ROWS+=("${rows[$key]}"); done
    local -a planned=(${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"})
    gtm_optimize_push_step && GTM_OPT_ROWS=(${planned[@]+"${planned[@]}"}) && gtm_optimize_save_rows "$GTM_OPT_JOURNAL" || return 1
    for row in "${attempts[@]}"; do
        IFS=$'\t' read -r key current value group <<< "$row"
        if gtm_optimize_write "$key" "$value"; then done_rows+=("$row"); ((written+=1)); else failed=1; break; fi
    done
    if ((failed == 0)) && GTM_OPT_ROWS=(${planned[@]+"${planned[@]}"}) && gtm_optimize_persist; then
        printf '%s %s\n' "${GTM_OPT_LEVEL:-balanced}" "${GTM_OPT_GOAL:-general}" > "$GTM_OPT_DIR/profile" && chmod 600 "$GTM_OPT_DIR/profile"
        printf 'Applied %d setting(s). Undo or Reset restores them.\n' "$written"; return 0
    fi
    gtm_error 'Applying stopped; reverting the settings written in this step.'
    for row in ${done_rows[@]+"${done_rows[@]}"}; do
        IFS=$'\t' read -r key current value group <<< "$row"
        [[ $(gtm_optimize_read "$key") != "$value" ]] || gtm_optimize_write "$key" "$current" || failed=2
    done
    GTM_OPT_ROWS=(${GTM_OPT_PREVIOUS[@]+"${GTM_OPT_PREVIOUS[@]}"})
    gtm_optimize_save_rows "$GTM_OPT_JOURNAL" && rm -f "$(gtm_optimize_last_step)" || failed=2
    ((failed < 2)) || gtm_error "Recovery needs attention; see $GTM_OPT_DIR."
    return 1
}

# Moves live values to the target rows: a key in target takes its applied
# value; a key only in the current journal returns to its original value.
gtm_optimize_move() {
    local -n wanted_rows=$1
    local row key before applied group goal failed=0
    local -A goal_of=() released=()
    local -a kept=()
    for row in ${wanted_rows[@]+"${wanted_rows[@]}"}; do IFS=$'\t' read -r key before applied group <<< "$row"; goal_of[$key]=$applied; done
    GTM_OPT_PREVIOUS=(${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"})
    gtm_optimize_check_live
    for key in ${GTM_OPT_RELEASED[@]+"${GTM_OPT_RELEASED[@]}"}; do released[$key]=1; done
    for row in ${GTM_OPT_LIVE[@]+"${GTM_OPT_LIVE[@]}"}; do
        IFS=$'\t' read -r key before applied group <<< "$row"
        goal=${goal_of[$key]-$before}
        [[ $goal == "$applied" ]] || gtm_optimize_write "$key" "$goal" || { kept+=("$row"); failed=1; }
    done
    GTM_OPT_ROWS=()
    for row in ${wanted_rows[@]+"${wanted_rows[@]}"}; do [[ ${released[${row%%$'\t'*}]+set} ]] || GTM_OPT_ROWS+=("$row"); done
    for row in ${kept[@]+"${kept[@]}"}; do
        key=${row%%$'\t'*}
        local -a filtered=()
        for applied in "${GTM_OPT_ROWS[@]}"; do [[ ${applied%%$'\t'*} == "$key" ]] || filtered+=("$applied"); done
        GTM_OPT_ROWS=(${filtered[@]+"${filtered[@]}"} "$row")
    done
    gtm_optimize_persist || return 1
    return "$failed"
}

gtm_optimize_undo() {
    local step
    local -a earlier=()
    gtm_optimize_paths
    gtm_optimize_load || return 1
    step=$(gtm_optimize_last_step)
    [[ -n $step ]] || { gtm_error 'There is no step to undo.'; return 1; }
    local -a current=("${GTM_OPT_ROWS[@]}")
    gtm_optimize_load "$step" || return 1
    earlier=(${GTM_OPT_ROWS[@]+"${GTM_OPT_ROWS[@]}"}); GTM_OPT_ROWS=(${current[@]+"${current[@]}"})
    gtm_confirm || return 1
    gtm_optimize_move earlier || { gtm_error 'Some settings could not be reverted; they stay tracked. Try again.'; return 1; }
    rm -f "$step"
    printf 'Undid the last step.\n'
}

# Returns one group's keys (or every key with "all") to their original values.
gtm_optimize_remove() {
    local which=$1 row
    local -a remaining=()
    [[ $which =~ ^(conntrack|queues|relay|routing|nic|previous|all)$ ]] || { gtm_error 'Unknown optimization group.'; return 2; }
    gtm_optimize_paths
    gtm_optimize_import && gtm_optimize_load || return 1
    ((${#GTM_OPT_ROWS[@]})) || { printf 'Nothing is applied.\n'; [[ $which != all ]] || rm -rf "$GTM_OPT_STEPS" "$GTM_OPT_DIR/profile"; return 0; }
    for row in "${GTM_OPT_ROWS[@]}"; do [[ $which != all && ${row##*$'\t'} != "$which" ]] && remaining+=("$row"); done
    gtm_confirm || return 1
    GTM_OPT_PREVIOUS=("${GTM_OPT_ROWS[@]}")
    if [[ $which != all ]]; then gtm_optimize_push_step || return 1; GTM_OPT_ROWS=("${GTM_OPT_PREVIOUS[@]}"); fi
    gtm_optimize_move remaining || { gtm_error 'Some settings could not be restored; they stay tracked. Try again.'; return 1; }
    if [[ $which == all ]]; then
        rm -rf "$GTM_OPT_STEPS"; rm -f "$GTM_OPT_JOURNAL" "$GTM_OPT_DIR/profile"
        printf 'Every setting is back to its original value; the panel files were removed.\n'
    else
        printf 'Settings of %s are back to their original values.\n' "$which"
    fi
}

gtm_optimize_menu() {
    local choice level goal
    local -a groups=(conntrack queues relay routing nic)
    gtm_optimize_use_profile - - || return
    while true; do
        gtm_header 'Server optimization / opt-in, reversible'
        gtm_help tuning
        printf '  Profile: %s / %s\n\n' "$GTM_OPT_LEVEL" "$GTM_OPT_GOAL"
        gtm_option 1 'Show settings' 'Current, original and applied values'
        gtm_option 2 'Connection tracking' 'Recommended for forwarders: fixes rising latency'
        gtm_option 3 'Packet queues' 'High packet rates'
        gtm_option 4 'Relay TCP' 'HAProxy / Realm / FRP: BBR, buffers, keepalive'
        gtm_option 5 'Tunnels & routing' 'Loose reverse-path filter, no ICMP redirects'
        gtm_option 6 'Network card' 'Transmit queue length; spread receive work across CPUs (RPS)'
        gtm_option 7 'Undo last step'
        gtm_option 8 'Reset everything' 'Original values; remove panel files'
        gtm_option 9 'Change profile' 'conservative / balanced / aggressive; general / users / latency'
        gtm_option 0 Back
        gtm_read 'Choose: ' choice || return
        case $choice in
            1) gtm_optimize_status | awk -F '\t' '$1 == "key" {printf "  %-52s %-22s (original %s)\n", $3, $4, $5}'; gtm_pause;;
            2|3|4|5|6) gtm_prepare && gtm_lock || return; gtm_optimize_apply "${groups[$((choice-2))]}"; gtm_unlock; gtm_pause;;
            7) gtm_prepare && gtm_lock || return; gtm_optimize_undo; gtm_unlock; gtm_pause;;
            8) gtm_prepare && gtm_lock || return; gtm_optimize_remove all; gtm_unlock; gtm_pause;;
            9) gtm_read 'Level (conservative, balanced, aggressive): ' level || continue
               gtm_read 'Goal (general, users, latency): ' goal || continue
               gtm_optimize_use_profile "$level" "$goal" || gtm_pause;;
            0) return;;
        esac
    done
}

# BEGIN MODULE: sysdns
# Server DNS: the resolvers this host itself uses. With systemd-resolved a
# drop-in sets global servers for every domain; with a plain /etc/resolv.conf
# the file is rewritten and a boot unit writes it again after DHCP. The original
# configuration is kept and restored exactly. resolvconf and NetworkManager
# hosts are reported, not changed.
GTM_SYSDNS_UNIT=gre-manager-resolv

gtm_sysdns_paths() {
    GTM_RESOLV=${GTM_RESOLV:-/etc/resolv.conf}
    GTM_RESOLVED_DIR=${GTM_RESOLVED_DIR:-/etc/systemd/resolved.conf.d}
    GTM_RESOLVED_UPSTREAM=${GTM_RESOLVED_UPSTREAM:-/run/systemd/resolve/resolv.conf}
    GTM_SYSDNS_DIR="$GTM_CONFIG_DIR/dns"
    GTM_SYSDNS_DROPIN="$GTM_RESOLVED_DIR/90-gre-manager.conf"
    GTM_SYSDNS_SCRIPT="${GTM_RUNTIME%/*}/resolv.sh"
    GTM_SYSDNS_SERVICE="$GTM_SERVICE_DIR/$GTM_SYSDNS_UNIT.service"
}

# A public resolver address: no loopback, unspecified, link-local or multicast.
gtm_sysdns_server() {
    local key
    if gtm_ipv4 "$1"; then [[ $1 != 0.* && $1 != 127.* && $1 != 169.254.* ]] && (( ${1%%.*} < 224 ))
    else
        gtm_ipv6 "$1" && gtm_key_of "$1" || return 1
        key=$GTM_KEY
        [[ $key != 0000000000000000000000000000000[01] && $key != ff* && $key != fe[89ab]* && $key != 00000000000000000000ffff* ]]
    fi
}

# resolved, file, resolvconf, networkmanager or unknown.
gtm_sysdns_mode() {
    local target
    gtm_sysdns_paths
    if [[ -L $GTM_RESOLV ]]; then
        target=$(readlink -f "$GTM_RESOLV" 2>/dev/null) || target=''
        case $target in
            */systemd/resolve/*) systemctl is-active --quiet systemd-resolved && { printf resolved; return; } ;;
            */resolvconf/*) printf resolvconf; return ;;
            */NetworkManager/*) printf networkmanager; return ;;
        esac
        printf unknown; return
    fi
    if [[ -f $GTM_RESOLV ]]; then
        if grep -q '^# Generated by NetworkManager' "$GTM_RESOLV" 2>/dev/null; then printf networkmanager; else printf file; fi
        return
    fi
    printf unknown
}

gtm_sysdns_nameservers() { [[ -r $1 ]] && awk '$1 == "nameserver" && NF >= 2 {print $2}' "$1" | head -n 8 | paste -sd' ' -; }

gtm_sysdns_resolved_query() {
    command -v resolvectl >/dev/null 2>&1 || return 2
    local output
    output=$(LC_ALL=C timeout 3 resolvectl dns 2>/dev/null) || return 1
    awk '$1 == "Global:" {$1=""; sub(/^ /, ""); print; found=1; exit} END {if (!found) exit 1}' <<< "$output"
}

gtm_sysdns_resolved_verify() {
    local actual status address key wanted='' observed=''
    actual=$(gtm_sysdns_resolved_query); status=$?
    ((status != 2)) || return 0 # Older hosts may not ship the optional status CLI.
    ((status == 0)) || { gtm_error 'Could not verify the active global DNS settings.'; return 1; }
    for address in "$@"; do key=$(gtm_ip_key "$address") || return 1; wanted+="$key"$'\n'; done
    for address in $actual; do key=$(gtm_ip_key "$address") || return 1; observed+="$key"$'\n'; done
    [[ $(sort -u <<< "$wanted") == "$(sort -u <<< "$observed")" ]] || { gtm_error 'The resolver did not activate the selected DNS servers; inspect later resolved drop-ins.'; return 1; }
}

# Prints: mode, managed (0/1), current, upstream (resolved only), servers, original.
gtm_sysdns_status() {
    local mode managed=0 saved='' original='' active=''
    gtm_sysdns_paths
    mode=$(gtm_sysdns_mode)
    [[ -f $GTM_SYSDNS_DIR/servers ]] && { managed=1; saved=$(head -n 1 "$GTM_SYSDNS_DIR/servers"); }
    [[ -f $GTM_SYSDNS_DIR/resolv.conf.orig ]] && original=$(gtm_sysdns_nameservers "$GTM_SYSDNS_DIR/resolv.conf.orig")
    [[ -f $GTM_SYSDNS_DIR/original ]] && original=$(head -n 1 "$GTM_SYSDNS_DIR/original")
    printf 'mode\t%s\nmanaged\t%s\n' "$mode" "$managed"
    printf 'current\t%s\n' "$(gtm_sysdns_nameservers "$GTM_RESOLV")"
    [[ $mode != resolved ]] || printf 'upstream\t%s\n' "$(gtm_sysdns_nameservers "$GTM_RESOLVED_UPSTREAM")"
    if [[ $mode == resolved ]]; then
        active=$(gtm_sysdns_resolved_query) || active=''
    elif [[ $mode == file ]]; then active=$(gtm_sysdns_nameservers "$GTM_RESOLV"); fi
    printf 'active\t%s\n' "$active"
    printf 'servers\t%s\noriginal\t%s\n' "$saved" "$original"
}

# Renders a resolv.conf with SERVERS, keeping search/domain/options of BASE.
gtm_sysdns_resolv_render() {
    local base=$1 server; shift
    printf '# Managed by Traffic Manager (Optimization -> DNS). Restore there to undo.\n'
    for server in "$@"; do printf 'nameserver %s\n' "$server"; done
    [[ -r $base ]] && grep -E '^(search|domain|options)[[:space:]]' "$base" | head -n 6
    return 0
}

gtm_sysdns_apply_checked() {
    local mode server tmp
    local -a servers=()
    (( $# >= 1 && $# <= 4 )) || { gtm_error 'Choose one to four DNS servers.'; return 2; }
    for server in "$@"; do
        gtm_sysdns_server "$server" || { gtm_error "Not a usable DNS server address: $server"; return 2; }
        [[ " ${servers[*]} " == *" $server "* ]] || servers+=("$server")
    done
    gtm_root || return 1
    mode=$(gtm_sysdns_mode)
    mkdir -p "$GTM_SYSDNS_DIR" && chmod 700 "$GTM_SYSDNS_DIR" || return 1
    case $mode in
        resolved)
            [[ -f $GTM_SYSDNS_DIR/original ]] || gtm_sysdns_nameservers "$GTM_RESOLVED_UPSTREAM" > "$GTM_SYSDNS_DIR/original" || return 1
            mkdir -p "$GTM_RESOLVED_DIR" || return 1
            if [[ ! -f $GTM_SYSDNS_DIR/resolved.conf.present ]]; then
                if [[ -f $GTM_SYSDNS_DROPIN && ! -f $GTM_SYSDNS_DIR/servers ]]; then
                    cp -p "$GTM_SYSDNS_DROPIN" "$GTM_SYSDNS_DIR/resolved.conf.orig" && printf '1\n' > "$GTM_SYSDNS_DIR/resolved.conf.present" || return 1
                else printf '0\n' > "$GTM_SYSDNS_DIR/resolved.conf.present" || return 1; fi
            fi
            tmp=$(mktemp "$GTM_SYSDNS_DROPIN.XXXXXX") || return 1
            # "~." routes every domain to these servers ahead of DHCP-provided ones.
            # List settings accumulate across drop-ins unless explicitly reset.
            printf '# Managed by Traffic Manager (Optimization -> DNS).\n[Resolve]\nDNS=\nDNS=%s\nFallbackDNS=\nDomains=\nDomains=~.\n' "${servers[*]}" > "$tmp" &&
                chmod 644 "$tmp" && mv "$tmp" "$GTM_SYSDNS_DROPIN" || { rm -f "$tmp"; return 1; }
            systemctl restart systemd-resolved && gtm_sysdns_resolved_verify "${servers[@]}" || return 1 ;;
        file)
            [[ -f $GTM_SYSDNS_DIR/resolv.conf.orig ]] || cp -p "$GTM_RESOLV" "$GTM_SYSDNS_DIR/resolv.conf.orig" || return 1
            gtm_sysdns_publish "${servers[@]}" || return 1 ;;
        resolvconf|networkmanager) gtm_error "DNS on this server is managed by $mode; change it there."; return 1 ;;
        *) gtm_error 'Unknown resolver setup; DNS was not changed.'; return 1 ;;
    esac
    printf '%s\n' "${servers[*]}" > "$GTM_SYSDNS_DIR/servers" && chmod 600 "$GTM_SYSDNS_DIR/servers" || return 1
    printf 'DNS servers set to %s (%s).\n' "${servers[*]}" "$mode"
}

# Writes resolv.conf and a boot unit that writes it again after the network
# (DHCP clients may replace the file at boot).
gtm_sysdns_publish() {
    local tmp script
    tmp=$(mktemp "$GTM_RESOLV.XXXXXX") || return 1
    gtm_sysdns_resolv_render "$GTM_SYSDNS_DIR/resolv.conf.orig" "$@" > "$tmp" && chmod 644 "$tmp" && mv "$tmp" "$GTM_RESOLV" || { rm -f "$tmp"; return 1; }
    mkdir -p "${GTM_SYSDNS_SCRIPT%/*}" || return 1
    script=$(mktemp "$GTM_SYSDNS_SCRIPT.XXXXXX") || return 1
    {
        printf '#!/bin/sh\n# Generated by Traffic Manager: server DNS after boot.\n'
        printf '[ -L %s ] && exit 0\n' "$GTM_RESOLV"
        printf "cat > %s.gtm <<'GTM_EOF'\n" "$GTM_RESOLV"
        gtm_sysdns_resolv_render "$GTM_SYSDNS_DIR/resolv.conf.orig" "$@"
        printf 'GTM_EOF\nchmod 644 %s.gtm && mv %s.gtm %s\n' "$GTM_RESOLV" "$GTM_RESOLV" "$GTM_RESOLV"
    } > "$script" && chmod 700 "$script" && mv "$script" "$GTM_SYSDNS_SCRIPT" || { rm -f "$script"; return 1; }
    cat > "$GTM_SYSDNS_SERVICE" <<EOF
[Unit]
Description=Traffic Manager server DNS
Wants=network-online.target
After=network-online.target
[Service]
Type=oneshot
ExecStart=/bin/sh $GTM_SYSDNS_SCRIPT
[Install]
WantedBy=multi-user.target
EOF
    systemctl daemon-reload && systemctl enable "$GTM_SYSDNS_UNIT.service" >/dev/null
}

gtm_sysdns_restore_checked() {
    local tmp
    gtm_root || return 1
    [[ -f $GTM_SYSDNS_DIR/servers ]] || { printf 'DNS is not managed here; nothing to restore.\n'; return 0; }
    if [[ -e $GTM_SYSDNS_DROPIN ]]; then
        if [[ -f $GTM_SYSDNS_DIR/resolved.conf.orig ]]; then
            cp -p "$GTM_SYSDNS_DIR/resolved.conf.orig" "$GTM_SYSDNS_DROPIN" || return 1
        else rm -f "$GTM_SYSDNS_DROPIN" || return 1; fi
        systemctl restart systemd-resolved || return 1
    fi
    if [[ -e $GTM_SYSDNS_SERVICE ]]; then
        systemctl disable "$GTM_SYSDNS_UNIT.service" >/dev/null 2>&1 || true
        rm -f "$GTM_SYSDNS_SERVICE" "$GTM_SYSDNS_SCRIPT" && systemctl daemon-reload || return 1
    fi
    if [[ -f $GTM_SYSDNS_DIR/resolv.conf.orig && ! -L $GTM_RESOLV ]]; then
        tmp=$(mktemp "$GTM_RESOLV.XXXXXX") || return 1
        cp -p "$GTM_SYSDNS_DIR/resolv.conf.orig" "$tmp" && mv "$tmp" "$GTM_RESOLV" || { rm -f "$tmp"; return 1; }
    fi
    rm -f "$GTM_SYSDNS_DIR/servers" "$GTM_SYSDNS_DIR/original" "$GTM_SYSDNS_DIR/resolv.conf.orig" "$GTM_SYSDNS_DIR/resolved.conf.orig" "$GTM_SYSDNS_DIR/resolved.conf.present" || return 1
    printf 'Original DNS configuration restored.\n'
}

# Capture only the exact files owned by this operation. A failed restart or boot
# unit publication restores the configuration from immediately before the request.
gtm_sysdns_transaction() {
    local operation=$1 stage file index mode had_service=0 enabled=0 result recovery=0
    shift
    gtm_root || return 1
    gtm_sysdns_paths
    mode=$(gtm_sysdns_mode)
    for file in "$GTM_SYSDNS_DIR" "$GTM_RESOLVED_DIR" "${GTM_SYSDNS_SCRIPT%/*}" "$GTM_SERVICE_DIR"; do
        [[ ! -L $file && ( ! -e $file || -d $file ) ]] || { gtm_error "Unsafe DNS directory: $file"; return 1; }
    done
    local -a files=("$GTM_SYSDNS_DROPIN" "$GTM_SYSDNS_SCRIPT" "$GTM_SYSDNS_SERVICE" "$GTM_SYSDNS_DIR/servers" "$GTM_SYSDNS_DIR/original" "$GTM_SYSDNS_DIR/resolv.conf.orig" "$GTM_SYSDNS_DIR/resolved.conf.orig" "$GTM_SYSDNS_DIR/resolved.conf.present")
    [[ $mode != file ]] || files+=("$GTM_RESOLV")
    [[ ! -f $GTM_SYSDNS_SERVICE ]] || { had_service=1; systemctl is-enabled --quiet "$GTM_SYSDNS_UNIT.service" && enabled=1; }
    stage=$(mktemp -d "$GTM_RUN_DIR/sysdns.XXXXXX") || return 1
    chmod 700 "$stage" || return 1
    for index in "${!files[@]}"; do
        file=${files[$index]}
        if [[ -L $file || ( -e $file && ! -f $file ) ]]; then gtm_error "Unsafe DNS artifact: $file"; rmdir "$stage" 2>/dev/null || true; return 1; fi
        [[ ! -f $file ]] || cp -p "$file" "$stage/$index" || return 1
    done
    case $operation in
        apply) gtm_sysdns_apply_checked "$@"; result=$?;;
        restore) gtm_sysdns_restore_checked; result=$?;;
        *) return 2;;
    esac
    if ((result)); then
        for index in "${!files[@]}"; do
            file=${files[$index]}
            if [[ -f $stage/$index ]]; then cp -p "$stage/$index" "$file" || recovery=1
            else rm -f -- "$file" || recovery=1; fi
        done
        if [[ $mode == resolved ]]; then systemctl restart systemd-resolved || recovery=1; fi
        if ((had_service)); then
            systemctl daemon-reload || recovery=1
            if ((enabled)); then systemctl enable "$GTM_SYSDNS_UNIT.service" >/dev/null || recovery=1; fi
        else systemctl disable "$GTM_SYSDNS_UNIT.service" >/dev/null 2>&1 || true; systemctl daemon-reload || recovery=1; fi
        gtm_error 'DNS change failed; the previous configuration was restored.'
        ((recovery == 0)) || gtm_error 'DNS recovery needs attention; inspect the resolver service.'
    fi
    for index in "${!files[@]}"; do rm -f -- "$stage/$index" || return 1; done
    rmdir "$stage" || return 1
    return "$result"
}

gtm_sysdns_apply() { gtm_sysdns_transaction apply "$@"; }
gtm_sysdns_restore() { gtm_sysdns_transaction restore; }

# Same presets as panel/internal/model/dns_presets.json (a test keeps them equal).
GTM_SYSDNS_PRESETS=(
    'Cloudflare|1.1.1.1 1.0.0.1' 'Google|8.8.8.8 8.8.4.4' 'Quad9|9.9.9.9 149.112.112.112'
    'AdGuard|94.140.14.14 94.140.15.15' 'OpenDNS|208.67.222.222 208.67.220.220'
    'Shecan|178.22.122.100 185.51.200.2' 'Electro|78.157.42.100 78.157.42.101'
    'Radar Game|10.202.10.10 10.202.10.11' '403.online|10.202.10.202 10.202.10.102'
    'Begzar|185.55.226.26 185.55.225.25'
)

# Prints "server<TAB>ms" or "server<TAB>-" per server: one lookup of NAME each.
gtm_sysdns_probe() {
    local server start end
    command -v dig >/dev/null 2>&1 || { printf 'Install dnsutils (dig) for a speed test; the panel tests without it.\n'; return 0; }
    for server in "$@"; do
        start=$(date +%s%N)
        if dig +time=2 +tries=1 +short "@$server" example.com A >/dev/null 2>&1; then
            end=$(date +%s%N); printf '  %-16s %4d ms\n' "$server" "$(( (end - start) / 1000000 ))"
        else printf '  %-16s failed\n' "$server"; fi
    done
}

gtm_sysdns_menu() {
    local choice index entry input
    local -a servers=()
    gtm_sysdns_paths
    while true; do
        gtm_header 'Server DNS'
        gtm_sysdns_status | while IFS=$'\t' read -r key value; do printf '  %-9s %s\n' "$key" "${value:--}"; done
        printf '\n'
        index=0
        for entry in "${GTM_SYSDNS_PRESETS[@]}"; do ((index+=1)); gtm_option "$index" "${entry%%|*}" "${entry#*|}"; done
        gtm_option 11 'Manual servers'
        gtm_option 12 'Speed test (all presets)'
        gtm_option 13 'Restore original DNS'
        gtm_option 0 Back
        gtm_read 'Choose: ' choice || return
        case $choice in
            0) return;;
            11) gtm_default 'DNS servers (space separated, up to 4)' input '' || continue
                read -r -a servers <<< "$input";;
            12) for entry in "${GTM_SYSDNS_PRESETS[@]}"; do printf '%s\n' "${entry%%|*}"; read -r -a servers <<< "${entry#*|}"; gtm_sysdns_probe "${servers[@]}"; done
                gtm_pause; continue;;
            13) gtm_prepare && gtm_lock || continue; gtm_sysdns_restore; gtm_unlock; gtm_pause; continue;;
            *) gtm_uint "$choice" 1 "${#GTM_SYSDNS_PRESETS[@]}" || { gtm_error 'Choose one of the shown options.'; continue; }
               entry=${GTM_SYSDNS_PRESETS[$((10#$choice-1))]}; read -r -a servers <<< "${entry#*|}";;
        esac
        ((${#servers[@]})) || continue
        gtm_sysdns_probe "${servers[@]}"
        printf '  Apply %s?\n' "${servers[*]}"
        gtm_confirm || continue
        gtm_prepare && gtm_lock || continue
        gtm_sysdns_apply "${servers[@]}"; gtm_unlock; gtm_pause
    done
}

gtm_sysdns_api() {
    local operation=$1; shift
    gtm_sysdns_paths
    case $operation in
        dns-status) (($#==0)) && gtm_sysdns_status;;
        dns-apply) gtm_prepare && gtm_lock || return 1; gtm_sysdns_apply "$@"; local result=$?; gtm_unlock; return "$result";;
        dns-restore) (($#==0)) || return 2; gtm_prepare && gtm_lock || return 1; gtm_sysdns_restore; local result=$?; gtm_unlock; return "$result";;
        *) return 2;;
    esac
}

# BEGIN MODULE: cleanup
# Retirement of installations made before the record-based manager (v13.x
# scripts, Simple GRE, historical tuning files). Only generator-owned syntax
# is recognized; anything unknown is reported and kept for the operator.
FW_SCRIPT=/usr/local/bin/gre_custom_rules.sh
FW_SERVICE=/etc/systemd/system/gre-custom-rules.service
SYSCTL_FILE=/etc/sysctl.d/99-gre-tuning.conf
PERF_SYSCTL_FILE=/etc/sysctl.d/98-gre-highload.conf
PERF_MODULES_FILE=/etc/modules-load.d/gre-conntrack.conf
PERF_SCRIPT=/usr/local/bin/gre_perf.sh
PERF_SERVICE=/etc/systemd/system/gre-perf.service

# New listeners must not collide with forwards an old script still adds at boot.
gtm_legacy_listener_check() {
    local protocol=$1 bind=$2 port=$3 file line
    local -a words=()
    for file in "$FW_SCRIPT" /opt/simple_gre_script.sh; do
        [[ -r $file ]] || continue
        while IFS= read -r line; do
            read -r -a words <<< "$line"
            [[ ${#words[@]} == 13 && ${words[0]} =~ ^(iptables|ip6tables)$ && ${words[1]} == -t && ${words[2]} == nat && ${words[3]} == -A && ${words[4]} == PREROUTING && ${words[5]} == -p && ${words[7]} == --dport && ${words[9]} == -j && ${words[10]} == DNAT && ${words[11]} == --to-destination ]] || continue
            if [[ $bind == *:* ]]; then [[ ${words[0]} == ip6tables ]] || continue; else [[ ${words[0]} == iptables ]] || continue; fi
            [[ $protocol == both || $protocol == "${words[6]}" ]] || continue
            gtm_port "${words[8]}" && gtm_port_span "$port" || continue
            ((PS_FIRST <= 10#${words[8]} && 10#${words[8]} <= PS_LAST)) || continue
            gtm_error "An existing legacy forward already uses this entrance port. Retire it under Tools -> Retire old installation first."
            return 1
        done < "$file"
    done
    gtm_portfw_listener_check "$protocol" "$bind" "$port"
}

# Strictly recognize generator-owned legacy DNAT syntax. Unknown/manual lines stay.
gtm_legacy_delete_group() {
    local line cmd localport dest choice index=0 key file deleted=0 failed=0
    local -a keys=() lines=() keep=() args=()
    local -A seen=()
    [[ -f $FW_SCRIPT ]] || { printf 'No legacy rules file.\n'; return; }
    mapfile -t lines < "$FW_SCRIPT"
    for line in "${lines[@]}"; do
        read -r -a args <<< "$line"
        # The normal generated line has 13 words, including the destination.
        [[ ${#args[@]} == 13 && ${args[0]} =~ ^(iptables|ip6tables)$ && ${args[1]} == -t && ${args[2]} == nat && ${args[3]} == -A && ${args[4]} == PREROUTING && ${args[5]} == -p && ${args[6]} =~ ^(tcp|udp)$ && ${args[7]} == --dport && ${args[9]} == -j && ${args[10]} == DNAT && ${args[11]} == --to-destination ]] || continue
        gtm_port "${args[8]}" && gtm_endpoint "${args[12]}" || continue
        key="${args[0]}|${args[8]}|${args[12]}"
        [[ ${seen[$key]+set} ]] && continue
        seen[$key]=1; keys+=("$key"); ((index+=1)); printf '  [%d] %s -> %s (%s)\n' "$index" "${args[8]}" "${args[12]}" "${args[0]}"
    done
    ((index>0)) || { printf 'No recognized generated groups. Manual rules were kept.\n'; return; }
    gtm_read 'Delete group row [0 cancels]: ' choice || return
    gtm_uint "$choice" 1 "$index" || return
    key=${keys[$((10#$choice-1))]}; IFS='|' read -r cmd localport dest <<< "$key"
    gtm_need "$cmd" && "$cmd" -t nat -S PREROUTING >/dev/null || return 1
    gtm_endpoint "$dest" || return
    local dest_ip=$EP_IP dest_port=$EP_PORT proto shared=0 other other_cmd other_port other_dest
    for other in "${keys[@]}"; do
        [[ $other != "$key" ]] || continue
        IFS='|' read -r other_cmd other_port other_dest <<< "$other"
        [[ $other_cmd != "$cmd" || $other_dest != "$dest" ]] || shared=1
    done
    printf 'Remove both TCP/UDP forwarding for :%s -> %s\n' "$localport" "$dest"
    gtm_confirm || return
    cp "$FW_SCRIPT" "$GTM_CONFIG_DIR/backups/legacy-$(date -u +%Y%m%dT%H%M%S)-$$.sh" || return
    for line in "${lines[@]}"; do
        local owned=0
        for proto in tcp udp; do
            if [[ $line == "$cmd -t nat -A PREROUTING -p $proto --dport $localport -j DNAT --to-destination $dest" ]]; then owned=1; fi
            if ((shared==0)) && [[ $line == "$cmd -t nat -A POSTROUTING -d $dest_ip -p $proto --dport $dest_port -j MASQUERADE" || $line == "$cmd -I FORWARD -d $dest_ip -p $proto --dport $dest_port -j ACCEPT" ]]; then owned=1; fi
        done
        if ((owned)); then
            read -r -a args <<< "$line"
            for index in "${!args[@]}"; do [[ ${args[$index]} != -A && ${args[$index]} != -I ]] || { args[$index]=-D; break; }; done
            # Check existence, then require deletion to succeed; drain duplicates.
            local -a check=("${args[@]}")
            for index in "${!check[@]}"; do [[ ${check[$index]} != -D ]] || { check[$index]=-C; break; }; done
            while "$cmd" "${check[@]:1}" 2>/dev/null; do
                "$cmd" "${args[@]:1}" || { failed=1; break; }
                ((deleted+=1)); ((deleted<10000)) || { failed=1; break; }
            done
        else keep+=("$line"); fi
    done
    ((failed==0)) || { gtm_error 'Too many duplicate rules; configuration kept for inspection.'; return; }
    file=$(mktemp "${FW_SCRIPT}.XXXXXX") || return
    printf '%s\n' "${keep[@]}" > "$file" && chmod 700 "$file" && mv "$file" "$FW_SCRIPT"
    printf 'Removed legacy group and its duplicates.\n'
}

# Closed legacy inventory. Never execute a saved shell line or flush host tables.
gtm_legacy_inspect() {
    [[ -f $FW_SCRIPT && -r $FW_SCRIPT ]] || { printf 'No readable legacy forwarding file.\n'; return; }
    printf 'Legacy persistence / read only: %s\n' "$FW_SCRIPT"
    cat "$FW_SCRIPT"
    printf '\nUse grouped deletion or recognized-resource cleanup; add new connections in Traffic connections.\nRaw saved scripts are not executed by this inspection.\n'
    gtm_pause
}

gtm_legacy_dnat() {
    local line=$1
    read -r -a L_ARGS <<< "$line"
    [[ ${#L_ARGS[@]} == 13 && ${L_ARGS[0]} =~ ^(iptables|ip6tables)$ && ${L_ARGS[1]} == -t && ${L_ARGS[2]} == nat && ${L_ARGS[3]} == -A && ${L_ARGS[4]} == PREROUTING && ${L_ARGS[5]} == -p && ${L_ARGS[6]} =~ ^(tcp|udp)$ && ${L_ARGS[7]} == --dport && ${L_ARGS[9]} == -j && ${L_ARGS[10]} == DNAT && ${L_ARGS[11]} == --to-destination && ${L_ARGS[12]} != *@* ]] || return 1
    gtm_port "${L_ARGS[8]}" && gtm_endpoint "${L_ARGS[12]}" || return 1
    if [[ ${L_ARGS[0]} == iptables ]]; then [[ $EP_IP != *:* ]]; else [[ $EP_IP == *:* ]]; fi
}

gtm_legacy_drain_rule() {
    local line=$1 index count=0 status
    local -a args=() check=()
    read -r -a args <<< "$line"
    for index in "${!args[@]}"; do [[ ${args[$index]} != -A && ${args[$index]} != -I ]] || { args[$index]=-D; break; }; done
    check=("${args[@]}"); check[$index]=-C
    while true; do
        if "${check[@]}" 2>/dev/null; then
            "${args[@]}" || return 1
            ((count+=1)); ((count<10000)) || { gtm_error 'Rule duplicate limit exceeded; persistence was kept.'; return 1; }
        else
            status=$?
            ((status==1)) || { gtm_error 'Firewall check failed; persistence was kept.'; return 1; }
            break
        fi
    done
}

gtm_legacy_forward_unit() {
    cat <<EOF
[Unit]
Description=GRE Custom Forwarding Rules
After=network.target
[Service]
Type=oneshot
ExecStart=$FW_SCRIPT
RemainAfterExit=yes
[Install]
WantedBy=multi-user.target
EOF
}

gtm_simple_unit() {
    cat <<EOF
[Unit]
Description=Simple GRE Tunnel Setup
After=network.target
[Service]
Type=oneshot
ExecStart=$GTM_SIMPLE_SCRIPT
RemainAfterExit=yes
[Install]
WantedBy=multi-user.target
EOF
}

gtm_cleanup_backup() {
    local source=$1 unit=$2
    GTM_CLEANUP_BACKUP="$GTM_CONFIG_DIR/backups/cleanup-$(date -u +%Y%m%dT%H%M%S)-$$-$RANDOM"
    mkdir "$GTM_CLEANUP_BACKUP" && chmod 700 "$GTM_CLEANUP_BACKUP" && cp "$source" "$GTM_CLEANUP_BACKUP/source.sh" || return 1
    [[ ! -f $unit ]] || cp "$unit" "$GTM_CLEANUP_BACKUP/source.service" || return 1
    chmod 600 "$GTM_CLEANUP_BACKUP"/*
}

gtm_legacy_plan_all() {
    local line target proto cmd unknown=0
    local -a lines=()
    local -A target_rules=() commands=()
    L_RULES=()
    [[ -f $FW_SCRIPT && ! -L $FW_SCRIPT ]] || { gtm_error 'No regular legacy forwarding script.'; return 1; }
    grep -Fxq '# Custom GRE Forwarding Rules' "$FW_SCRIPT" || { gtm_error 'Legacy generator header missing; file kept.'; return 1; }
    mapfile -t lines < "$FW_SCRIPT"
    for line in "${lines[@]}"; do
        if gtm_legacy_dnat "$line"; then target_rules["${L_ARGS[0]}|${L_ARGS[6]}|$EP_IP|$EP_PORT"]=1; fi
    done
    for line in "${lines[@]}"; do
        [[ -n $line && $line != '#'* ]] || continue
        case $line in
            'sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1'|'sysctl -w net.ipv6.conf.all.forwarding=1 >/dev/null 2>&1'|'[ -f /etc/sysctl.d/98-gre-highload.conf ] || sysctl -w net.netfilter.nf_conntrack_max=262144 >/dev/null 2>&1') continue;;
        esac
        if gtm_legacy_dnat "$line"; then commands["$line"]=1; continue; fi
        local matched=0 ip port
        for target in "${!target_rules[@]}"; do
            IFS='|' read -r cmd proto ip port <<< "$target"
            if [[ $line == "$cmd -t nat -A POSTROUTING -d $ip -p $proto --dport $port -j MASQUERADE" || $line == "$cmd -I FORWARD -d $ip -p $proto --dport $port -j ACCEPT" ]]; then commands["$line"]=1; matched=1; break; fi
        done
        if ((matched==0)); then ((unknown+=1)); printf 'Unrecognized line retained: %s\n' "$line"; fi
    done
    ((unknown==0)) || { gtm_error 'Bulk cleanup refused because the file contains unknown/manual commands. Use grouped deletion for recognized forwards.'; return 1; }
    mapfile -t L_RULES < <(if ((${#commands[@]})); then printf '%s\n' "${!commands[@]}" | LC_ALL=C sort; fi)
    if [[ -e $FW_SERVICE || -L $FW_SERVICE ]]; then
        [[ -f $FW_SERVICE && ! -L $FW_SERVICE ]] && cmp -s "$FW_SERVICE" <(gtm_legacy_forward_unit) || { gtm_error 'Legacy unit was customized; files and live rules were kept.'; return 1; }
    fi
    printf 'Recognized legacy forwarding commands: %d\n' "${#L_RULES[@]}"
    printf '  Remove %s and %s; standard GRE and modern connections stay.\n' "$FW_SCRIPT" "$FW_SERVICE"
}

gtm_legacy_cleanup_all() {
    local line cmd
    [[ -e $FW_SCRIPT || -L $FW_SCRIPT ]] || { printf 'No legacy forwarding script.\n'; return; }
    gtm_legacy_plan_all || return 1
    for line in "${L_RULES[@]}"; do
        cmd=${line%% *}; gtm_need "$cmd" && "$cmd" -t nat -S PREROUTING >/dev/null || return 1
    done
    gtm_confirm && gtm_cleanup_backup "$FW_SCRIPT" "$FW_SERVICE" || return 1
    # A verified oneshot unit has no ExecStop; stopping prevents an in-flight replay.
    [[ ! -f $FW_SERVICE ]] || systemctl stop gre-custom-rules.service || return 1
    for line in "${L_RULES[@]}"; do
        if ! gtm_legacy_drain_rule "$line"; then
            gtm_error "Cleanup incomplete; persistence and backup kept: $GTM_CLEANUP_BACKUP"; return 1
        fi
    done
    [[ ! -f $FW_SERVICE ]] || systemctl disable gre-custom-rules.service || return 1
    rm -f "$FW_SCRIPT" "$FW_SERVICE" && systemctl daemon-reload || return 1
    printf 'Removed recognized legacy forwarding and duplicates. Backup: %s\n' "$GTM_CLEANUP_BACKUP"
    printf 'Existing conntrack sessions can retain their old mapping until expiry.\n'
}

gtm_simple_plan() {
    local line local_port='' remote_port='' proto role='' tunnels=0 links=0 addresses=0 sysctls=0 masquerades=0 dnats=0 forwards=0 signature=0
    local -a words=()
    L_RULES=(); L_SIMPLE_LOCAL=''; L_SIMPLE_REMOTE=''
    [[ -f $GTM_SIMPLE_SCRIPT && ! -L $GTM_SIMPLE_SCRIPT ]] || return 1
    while IFS= read -r line || [[ -n $line ]]; do
        [[ $line != '# Generated by GRE Master - Simple Mode v12' ]] || signature=1
        [[ -n $line && $line != '#'* ]] || continue
        read -r -a words <<< "$line"
        if [[ ${#words[@]} == 12 && ${words[*]:0:7} == 'ip tunnel add gre_simp mode gre local' && ${words[8]} == remote && ${words[10]} == ttl && ${words[11]} == 255 ]]; then
            gtm_ipv4 "${words[7]}" && gtm_ipv4 "${words[9]}" || return 1
            L_SIMPLE_LOCAL=${words[7]}; L_SIMPLE_REMOTE=${words[9]}; ((tunnels+=1)); continue
        fi
        case $line in
            'ip addr add 172.16.200.1/30 dev gre_simp') role=sender; ((addresses+=1)); continue;;
            'ip addr add 172.16.200.2/30 dev gre_simp') role=receiver; ((addresses+=1)); continue;;
            'ip link set gre_simp up') ((links+=1)); continue;;
            'sysctl -w net.ipv4.ip_forward=1') ((sysctls+=1)); continue;;
            'iptables -t nat -A POSTROUTING -o gre_simp -j MASQUERADE') L_RULES+=("$line"); ((masquerades+=1)); continue;;
        esac
        if gtm_legacy_dnat "$line" && [[ ${L_ARGS[0]} == iptables && $EP_IP == 172.16.200.2 ]]; then
            [[ -z $local_port || $local_port == "${L_ARGS[8]}" ]] && [[ -z $remote_port || $remote_port == "$EP_PORT" ]] || return 1
            local_port=${L_ARGS[8]}; remote_port=$EP_PORT; L_RULES+=("$line"); ((dnats+=1)); continue
        fi
        local matched=0
        for proto in tcp udp; do
            if [[ -n $remote_port && $line == "iptables -C FORWARD -d 172.16.200.2 -p $proto --dport $remote_port -j ACCEPT 2>/dev/null || iptables -I FORWARD -d 172.16.200.2 -p $proto --dport $remote_port -j ACCEPT" ]]; then
                L_RULES+=("iptables -I FORWARD -d 172.16.200.2 -p $proto --dport $remote_port -j ACCEPT"); ((forwards+=1)); matched=1; break
            fi
        done
        ((matched)) || { gtm_error 'Simple GRE script contains an unrecognized command; nothing removed.'; return 1; }
    done < "$GTM_SIMPLE_SCRIPT"
    ((signature==1 && tunnels==1 && addresses==1 && links==1)) || return 1
    if [[ $role == sender ]]; then ((dnats==2 && forwards==2 && sysctls==1 && masquerades==1)) || return 1
    else ((dnats==0 && forwards==0 && sysctls==0 && masquerades==0)) || return 1; fi
    if [[ -e $GTM_SIMPLE_UNIT || -L $GTM_SIMPLE_UNIT ]]; then
        [[ -f $GTM_SIMPLE_UNIT && ! -L $GTM_SIMPLE_UNIT ]] && cmp -s "$GTM_SIMPLE_UNIT" <(gtm_simple_unit) || { gtm_error 'Simple GRE unit was customized; nothing removed.'; return 1; }
    fi
    printf 'Recognized Simple GRE: %s -> %s (%s), %d forwarding commands.\n' "$L_SIMPLE_LOCAL" "$L_SIMPLE_REMOTE" "$role" "${#L_RULES[@]}"
}

gtm_simple_dependencies() {
    local line target
    local -a targets=()
    gtm_load_records || return 1
    for line in "${GTM_RECORDS[@]}"; do
        gtm_record_validate "$line" || return 1
        [[ $R_IFACE != gre_simp ]] || { gtm_error "Simple GRE is referenced by $R_ID."; return 1; }
        IFS=, read -r -a targets <<< "$R_TARGETS"; targets+=("$(gtm_address "$R_BIND" "$R_PORT")")
        for target in "${targets[@]}"; do
            gtm_target "$target" || return 1
            ((EP_HOST == 0)) || continue
            [[ $EP_IP != 172.16.200.[0-3] ]] || { gtm_error "Simple GRE address is referenced by $R_ID (disabled records count)."; return 1; }
        done
    done
    if [[ -r $FW_SCRIPT ]]; then
        while IFS= read -r line || [[ -n $line ]]; do
            if gtm_legacy_dnat "$line" && [[ $EP_IP == 172.16.200.[0-3] ]]; then gtm_error 'A legacy forward depends on Simple GRE; remove it first.'; return 1; fi
        done < "$FW_SCRIPT"
    fi
}

gtm_simple_cleanup() {
    local line description local_ip remote_ip
    [[ -e $GTM_SIMPLE_SCRIPT || -L $GTM_SIMPLE_SCRIPT ]] || { printf 'No Simple GRE script.\n'; return; }
    gtm_simple_plan && gtm_simple_dependencies && gtm_need ip || return 1
    if ip link show dev gre_simp >/dev/null 2>&1; then
        description=$(ip tunnel show gre_simp) || return 1
        local_ip=$(awk '{for(i=1;i<NF;i++) if($i=="local") print $(i+1)}' <<< "$description")
        remote_ip=$(awk '{for(i=1;i<NF;i++) if($i=="remote") print $(i+1)}' <<< "$description")
        [[ $local_ip == "$L_SIMPLE_LOCAL" && $remote_ip == "$L_SIMPLE_REMOTE" && $description == 'gre_simp: gre/ip '* ]] || { gtm_error 'gre_simp does not match the saved peer; interface kept.'; return 1; }
    fi
    printf 'Custom routes/manual references need separate review. Global firewall/sysctls are retained.\n'
    gtm_confirm && gtm_cleanup_backup "$GTM_SIMPLE_SCRIPT" "$GTM_SIMPLE_UNIT" || return 1
    [[ ! -f $GTM_SIMPLE_UNIT ]] || systemctl stop simple-gre.service || return 1
    for line in "${L_RULES[@]}"; do gtm_legacy_drain_rule "$line" || { gtm_error "Cleanup incomplete; source and backup kept: $GTM_CLEANUP_BACKUP"; return 1; }; done
    if ip link show dev gre_simp >/dev/null 2>&1; then ip link delete gre_simp || return 1; fi
    [[ ! -f $GTM_SIMPLE_UNIT ]] || systemctl disable simple-gre.service || return 1
    rm -f "$GTM_SIMPLE_SCRIPT" "$GTM_SIMPLE_UNIT" && systemctl daemon-reload || return 1
    printf 'Removed Simple GRE. Backup: %s\n' "$GTM_CLEANUP_BACKUP"
}

gtm_legacy_sysctl_owned() {
    local source=$1 kind=$2 key value extra count=0
    local -A seen=()
    [[ -f $source && ! -L $source ]] || return 1
    while IFS='=' read -r key value extra || [[ -n $key ]]; do
        key=$(awk '{$1=$1;print}' <<< "$key"); value=$(awk '{$1=$1;print}' <<< "$value")
        [[ -n $key && $key != '#'* ]] || continue
        [[ -z $extra && ! ${seen[$key]+set} ]] || return 1
        seen[$key]=1; ((count+=1))
        case "$kind|$key|$value" in
            'tcp|net.ipv4.ip_forward|1'|'tcp|net.ipv6.conf.all.forwarding|1'|'tcp|net.core.default_qdisc|fq'|'tcp|net.ipv4.tcp_congestion_control|bbr'|'tcp|net.core.rmem_max|16777216'|'tcp|net.core.wmem_max|16777216'|'tcp|net.ipv4.tcp_rmem|4096 87380 16777216'|'tcp|net.ipv4.tcp_wmem|4096 65536 16777216') :;;
            'capacity|net.netfilter.nf_conntrack_max|524288'|'capacity|net.netfilter.nf_conntrack_max|1048576'|'capacity|net.netfilter.nf_conntrack_buckets|131072'|'capacity|net.netfilter.nf_conntrack_buckets|262144'|'capacity|net.netfilter.nf_conntrack_tcp_timeout_established|7200'|'capacity|net.netfilter.nf_conntrack_tcp_timeout_time_wait|30'|'capacity|net.netfilter.nf_conntrack_tcp_timeout_fin_wait|30'|'capacity|net.ipv4.ip_local_port_range|1024 65535'|'capacity|net.core.somaxconn|65535'|'capacity|net.core.netdev_max_backlog|16384'|'capacity|net.ipv4.tcp_max_syn_backlog|8192'|'capacity|net.ipv4.tcp_slow_start_after_idle|0'|'capacity|net.ipv4.tcp_mtu_probing|1') :;;
            *) return 1;;
        esac
    done < "$source"
    if [[ $kind == tcp ]]; then ((count==8)); else ((count==11)); fi
}

gtm_legacy_retire_tuning() {
    local file index=0 backup
    local -a files=()
    for file in "$SYSCTL_FILE" "$PERF_SYSCTL_FILE" "$PERF_MODULES_FILE" "$PERF_SCRIPT" "$PERF_SERVICE"; do
        [[ -e $file || -L $file ]] || continue
        [[ -f $file && ! -L $file ]] || { gtm_error "Not a regular owned file: $file"; return 1; }
        case $file in
            "$SYSCTL_FILE") gtm_legacy_sysctl_owned "$file" tcp || { gtm_error "Custom tuning file kept: $file"; return 1; };;
            "$PERF_SYSCTL_FILE") gtm_legacy_sysctl_owned "$file" capacity || { gtm_error "Custom tuning file kept: $file"; return 1; };;
            "$PERF_MODULES_FILE") [[ $(cat "$file") == nf_conntrack ]] || return 1;;
            "$PERF_SCRIPT") [[ $(sha256sum "$file" | awk '{print $1}') == 93562fcaae0586a4152e6d9c30cb71a02c228524a55c543fdc1c041d657070fc ]] || { gtm_error 'Historical performance script differs from the known generator; kept.'; return 1; };;
            "$PERF_SERVICE") cmp -s "$file" <(printf '[Unit]\nDescription=GRE Manager High-Load Tuning (RPS + NOTRACK)\nAfter=network.target\n[Service]\nType=simple\nExecStart=%s boot\n[Install]\nWantedBy=multi-user.target\n' "$PERF_SCRIPT") || { gtm_error 'Historical performance unit was customized; kept.'; return 1; };;
        esac
        files+=("$file"); printf '  Retire: %s\n' "$file"
    done
    ((${#files[@]})) || { printf 'No recognized historical tuning files.\n'; return; }
    printf 'Previous runtime values were not recorded. Runtime sysctls/RPS/untagged NOTRACK stay; no guessed defaults are written.\n'
    printf 'Retirement prevents these files from reapplying at boot; review remaining host policy before reboot.\n'
    gtm_confirm || return
    backup="$GTM_CONFIG_DIR/backups/retired-tuning-$(date -u +%Y%m%dT%H%M%S)-$$-$RANDOM"
    mkdir "$backup" && chmod 700 "$backup" || return 1
    for file in "${files[@]}"; do cp "$file" "$backup/$index-${file##*/}" || return 1; ((index+=1)); done
    [[ ! -f $PERF_SERVICE ]] || systemctl disable --now gre-perf.service || return 1
    for file in "${files[@]}"; do rm -f "$file" || return 1; done
    systemctl daemon-reload || return 1
    printf 'Historical tuning persistence retired. Backup: %s\n' "$backup"
}

gtm_legacy_cleanup_menu() {
    local choice
    gtm_header 'Retire old installation / preview before removal'
    gtm_option 1 'Remove all recognized v13.x forwards' 'Refuses unknown/manual commands'
    gtm_option 2 'Remove one v13.x forward group' 'TCP and UDP by entrance + destination'
    gtm_option 3 'Remove Simple GRE' 'Checks saved script, unit, peer and known dependencies'
    gtm_option 4 'Retire old tuning files' 'Backup first; unknown runtime values stay'
    gtm_option 0 Back
    gtm_read 'Choose: ' choice || return
    case $choice in 1) gtm_legacy_cleanup_all;; 2) gtm_legacy_delete_group;; 3) gtm_simple_cleanup;; 4) gtm_legacy_retire_tuning;; esac
}

# BEGIN MODULE: links
# Noninteractive GRE operations preserve keyed v13.7+ wire defaults.
gtm_link_render() {
    local tid=$((10#$1)) role=$2 remote=$3 bind=$4 mtu=$((10#$5)) suffix=1 iface="gre$((10#$1))"
    [[ $role != iran ]] || { suffix=2; iface="gre-out-$tid"; }
    printf '# GTM managed GRE v1\n[Unit]\nDescription=GRE Tunnel %s\nWants=network-online.target\nAfter=network-online.target\n[Service]\nType=oneshot\nRemainAfterExit=yes\n' "$iface"
    if [[ $remote == *:* ]]; then printf 'ExecStart=/sbin/ip -6 tunnel add %s mode ip6gre remote %s local %s hoplimit 255 key %d\n' "$iface" "$remote" "$bind" "$tid"
    else printf 'ExecStart=/sbin/ip tunnel add %s mode gre remote %s local %s ttl 255 key %d\n' "$iface" "$remote" "$bind" "$tid"; fi
    printf 'ExecStart=/sbin/ip link set dev %s mtu %d\nExecStart=/sbin/ip link set dev %s up\n' "$iface" "$mtu" "$iface"
    printf 'ExecStart=/sbin/ip addr add 10.0.%d.%d/30 dev %s\nExecStart=/sbin/ip -6 addr add fd00:%d::%d/64 dev %s\n' "$tid" "$suffix" "$iface" "$tid" "$suffix" "$iface"
    printf 'ExecStop=/sbin/ip link del dev %s\nExecStopPost=-/sbin/ip link del dev %s\n[Install]\nWantedBy=multi-user.target\n' "$iface" "$iface"
}

gtm_link_create() {
    local tid=$1 role=$2 remote=$3 bind=$4 mtu=$5 family=4 maximum=1472 suffix=1 peer=2 iface unit tmp
    gtm_uint "$tid" 1 250 && [[ $role == kharej || $role == iran ]] && gtm_ip "$remote" && gtm_ip "$bind" || return 1
    tid=$((10#$tid))
    if [[ $remote == *:* ]]; then family=6; maximum=1452; [[ $bind == *:* ]] || return 1
    else [[ $bind != *:* ]] || return 1; fi
    gtm_uint "$mtu" 1280 "$maximum" && gtm_local_address "$bind" || return 1
    mtu=$((10#$mtu)); iface="gre$tid"
    if [[ $role == iran ]]; then suffix=2; peer=1; iface="gre-out-$tid"; fi
    unit="$GTM_SERVICE_DIR/gre-tun-$tid.service"
    [[ ! -e $unit && ! -L $unit ]] && ! ip link show "$iface" >/dev/null 2>&1 || { gtm_error 'GRE ID already exists.'; return 1; }
    gtm_need ip && gtm_need systemctl || return 1
    tmp=$(mktemp "$GTM_RUN_DIR/gre-unit.XXXXXX") || return 1
    gtm_link_render "$tid" "$role" "$remote" "$bind" "$mtu" > "$tmp" || { rm -f "$tmp"; return 1; }
    chmod 644 "$tmp" && mv "$tmp" "$unit" || { rm -f "$tmp"; return 1; }
    if ! { systemctl daemon-reload && systemctl enable --now "gre-tun-$tid"; }; then
        systemctl disable --now "gre-tun-$tid" || { gtm_error 'GRE startup failed and cleanup needs attention; unit kept.'; return 1; }
        rm -f "$unit"; systemctl daemon-reload; return 1
    fi
    printf 'GRE %d configured. Peer: 10.0.%d.%d. Allow protocol 47 on both servers.\n' "$tid" "$tid" "$peer"
}

gtm_link_delete() {
    local tid=$1
    gtm_uint "$tid" 1 250 || return 1
    tid=$((10#$tid))
    [[ -f $GTM_SERVICE_DIR/gre-tun-$tid.service ]] && gtm_link_remove_guard "$tid" || return 1
    # Only known manager units; custom ExecStart commands are never executed here.
    gtm_owned_gre "$tid" || { gtm_error 'Unrecognized GRE unit; inspect it manually.'; return 1; }
    if [[ -f $GTM_SERVICE_DIR/gre-keepalive-$tid.service ]]; then
        systemctl disable --now "gre-keepalive-$tid" || return 1
    fi
    systemctl disable --now "gre-tun-$tid" || return 1
    rm -f "$GTM_SERVICE_DIR/gre-tun-$tid.service" "$GTM_SERVICE_DIR/gre-keepalive-$tid.service" || return 1
    gtm_metadata_forget "gre-tun-$tid" || return 1
    systemctl daemon-reload
}

gtm_owned_gre() {
    local tid=$1 line count=0
    while IFS= read -r line || [[ -n $line ]]; do
        [[ $line == ExecStart=* || $line == ExecStop=* || $line == ExecStopPost=* ]] || continue
        [[ $line =~ ^Exec(Start|Stop|StopPost)=-?/sbin/ip[[:space:]] ]] || return 1
        [[ $line != *';'* && $line != *'`'* && $line != *'$'* && $line != *'%'* ]] || return 1
        [[ $line == *"gre$tid "* || $line == *"gre-out-$tid "* || $line == *"gre$tid" || $line == *"gre-out-$tid" ]] || return 1
        ((count+=1))
    done < "$GTM_SERVICE_DIR/gre-tun-$tid.service"
    ((count>=5))
}

# BEGIN MODULE: reverse_api
# Reverse adapters share the existing renderers and instance ownership rules.
gtm_api_reverse() {
    local engine line extra keys public_key result
    IFS= read -r line || return 1
    [[ $line != *$'\r'* && ${#line} -le 4096 ]] || return 1
    IFS= read -r extra && return 1
    local name role host control public local_ip local_port proto transport mux token group key cert internal fields
    fields=${line//[^$'\t']/}; ((${#fields}==15)) || return 1
    IFS=$'\t' read -r engine name role host control public local_ip local_port proto transport mux token group key cert internal <<< "$line"
    [[ $name =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    gtm_prepare && gtm_lock || return 1
    case $engine in
        frp)
            P_NAME=$name; P_ROLE=$role; P_HOST=$host; P_CONTROL=$control; P_PUBLIC=$public
            P_LOCAL_IP=$local_ip; P_LOCAL_PORT=$local_port; P_PROTO=$proto; P_TRANSPORT=$transport
            P_MUX=$mux; P_TOKEN=$token; P_GROUP=$group; P_INTERNAL=$internal
            P_GATEWAY_CERT=$cert; P_TLS_CA=$cert
            gtm_frp_create; result=$?;;
        rathole)
            RATH_NAME=$name; RATH_ROLE=$role; RATH_HOST=$host; RATH_CONTROL=$control; RATH_PUBLIC=$public
            RATH_LOCAL_IP=$local_ip; RATH_LOCAL_PORT=$local_port; RATH_PROTO=$proto; RATH_TOKEN=$token; RATH_KEY=$key
            if [[ $role == entrance ]]; then
                keys=$(rathole --genkey) || { gtm_unlock; return 1; }
                RATH_KEY=$(awk '/^Private Key:/ {getline; print; exit}' <<< "$keys")
                public_key=$(awk '/^Public Key:/ {getline; print; exit}' <<< "$keys")
                gtm_rathole_key "$public_key" || { gtm_unlock; return 1; }
            fi
            gtm_rathole_create; result=$?
            if ((result==0)) && [[ $role == entrance ]]; then printf 'Noise public key: %s\n' "$public_key"; fi;;
        *) result=1;;
    esac
    unset RATH_KEY RATH_TOKEN P_TOKEN keys token key
    gtm_unlock
    return "$result"
}

# Paired FRP accepts the same closed TSV layout; the caller already holds flock.
# Rathole key exchange and operator certificate paths are intentionally excluded.
gtm_pair_frp_parse() {
    local line extra fields engine name role host control public local_ip local_port proto transport mux token group key cert internal
    IFS= read -r line || return 1
    [[ $line != *$'\r'* && ${#line} -le 4096 ]] || return 1
    IFS= read -r extra && return 1
    fields=${line//[^$'\t']/}; ((${#fields}==15)) || return 1
    IFS=$'\t' read -r engine name role host control public local_ip local_port proto transport mux token group key cert internal <<< "$line"
    [[ $engine == frp && $name =~ ^[a-zA-Z0-9_-]{1,32}$ && $transport =~ ^(tcp|websocket|quic|kcp)$ && $key == - && $cert == - && $internal == 0 ]] || return 1
    P_NAME=$name; P_ROLE=$role; P_HOST=$host; P_CONTROL=$control; P_PUBLIC=$public
    P_LOCAL_IP=$local_ip; P_LOCAL_PORT=$local_port; P_PROTO=$proto; P_TRANSPORT=$transport
    P_MUX=$mux; P_TOKEN=$token; P_GROUP=$group
    gtm_frp_validate
}

# Caller holds the manager lock; used by both web and terminal flows.
gtm_frp_create() {
    local id="gtm-frp-$P_ROLE-$P_NAME" file unit bin gateway gateway_config result=0
    gtm_frp_validate || return 1
    [[ $P_NAME =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    file="$GTM_CONFIG_DIR/$id.toml"; unit="$GTM_SERVICE_DIR/$id.service"
    [[ ! -e $file && ! -L $file && ! -e $unit && ! -L $unit ]] || { gtm_error 'Reverse instance already exists.'; return 1; }
    if [[ $P_ROLE == entrance ]]; then
        gtm_local_address "$P_HOST" && gtm_port_available tcp "$P_HOST" "$P_CONTROL" && gtm_port_available "$P_PROTO" "$P_HOST" "$P_PUBLIC" || return 1
        [[ $P_TRANSPORT != quic && $P_TRANSPORT != kcp ]] || gtm_port_available udp "$P_HOST" "$P_CONTROL" || return 1
        [[ $P_TRANSPORT != wss ]] || gtm_port_available tcp 127.0.0.1 "$P_INTERNAL" || return 1
        bin=$(command -v frps) || return 1
    else bin=$(command -v frpc) || return 1; fi
    gateway="gtm-gateway-$P_NAME"; gateway_config="$GTM_CONFIG_DIR/$gateway.conf"
    gtm_frp_render > "$file.tmp" && "$bin" verify -c "$file.tmp" || { rm -f "$file.tmp"; return 1; }
    if [[ $P_TRANSPORT == wss && $P_ROLE == entrance ]]; then
        [[ ! -e $GTM_SERVICE_DIR/$gateway.service && ! -e $gateway_config ]] || { rm -f "$file.tmp"; return 1; }
        gtm_wss_haproxy_render > "$gateway_config.tmp" && haproxy -c -f "$gateway_config.tmp" || { rm -f "$file.tmp" "$gateway_config.tmp"; return 1; }
        mv "$gateway_config.tmp" "$gateway_config" && chmod 600 "$gateway_config" || return 1
        gtm_wss_gateway_unit "$(command -v haproxy)" "$gateway_config" "$P_NAME" "$id" > "$GTM_SERVICE_DIR/$gateway.service" || return 1
    fi
    mv "$file.tmp" "$file" && chmod 600 "$file" && gtm_relay_unit "$bin" "$file" "$P_NAME" > "$unit" || return 1
    [[ $P_TRANSPORT != wss || $P_ROLE != entrance ]] || sed -i "/After=network-online.target/a Wants=$gateway.service" "$unit"
    systemctl daemon-reload && systemctl enable --now "$id" || result=1
    if ((result==0)); then
        sleep 1
        systemctl is-active --quiet "$id" || result=1
        [[ $P_TRANSPORT != wss || $P_ROLE != entrance ]] || systemctl is-active --quiet "$gateway" || result=1
    fi
    if ((result)); then gtm_reverse_delete "$id" || gtm_error 'Reverse cleanup needs attention; files kept.'; return 1; fi
    printf 'Reverse connection configured. Verify the peer separately.\n'
}

gtm_reverse_delete() {
    local id=$1 gateway
    [[ $id =~ ^gtm-(frp|rathole)-(entrance|destination)-[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    [[ -f $GTM_SERVICE_DIR/$id.service && -f $GTM_CONFIG_DIR/$id.toml ]] || return 1
    if [[ $id == gtm-rathole-* ]]; then gtm_rathole_cleanup "$id" && gtm_metadata_forget "$id"; return $?; fi
    systemctl disable --now "$id" || return 1
    if [[ $id == gtm-frp-entrance-* ]]; then
        gateway="gtm-gateway-${id#gtm-frp-entrance-}"
        if [[ -f $GTM_SERVICE_DIR/$gateway.service ]]; then
            systemctl disable --now "$gateway" || return 1
            rm -f "$GTM_SERVICE_DIR/$gateway.service" "$GTM_CONFIG_DIR/$gateway.conf" || return 1
        fi
    fi
    rm -f "$GTM_SERVICE_DIR/$id.service" "$GTM_CONFIG_DIR/$id.toml" && gtm_metadata_forget "$id" && systemctl daemon-reload
}

# BEGIN MODULE: pair_api
# Closed paired-create boundary. Every check, compare and mutation runs under
# the existing manager lock. Fingerprints never contain native config text.
gtm_pair_service() {
    [[ $1 =~ ^gre-tun-([1-9][0-9]{0,2})$ ]] && gtm_uint "${BASH_REMATCH[1]}" 1 250 && return 0
    [[ $1 =~ ^gtm-frp-(entrance|destination)-[a-zA-Z0-9_-]{1,32}$ ]]
}

# These paired presets never create keepalives or WSS gateways. Existing or
# subsequently introduced siblings must not be removed by legacy delete helpers.
gtm_pair_auxiliary_absent() {
    local id=$1 auxiliary='' config=''
    case $id in
        gre-tun-*) auxiliary="gre-keepalive-${id#gre-tun-}";;
        gtm-frp-entrance-*) auxiliary="gtm-gateway-${id#gtm-frp-entrance-}"; config="$GTM_CONFIG_DIR/$auxiliary.conf";;
        *) return 0;;
    esac
    [[ ! -e $GTM_SERVICE_DIR/$auxiliary.service && ! -L $GTM_SERVICE_DIR/$auxiliary.service ]] || return 1
    [[ -z $config || ( ! -e $config && ! -L $config ) ]]
}

gtm_pair_fingerprint() {
    local id=$1 file parts sum
    gtm_pair_service "$id" || return 1
    gtm_pair_auxiliary_absent "$id" || return 1
    file="$GTM_SERVICE_DIR/$id.service"
    [[ -f $file && ! -L $file ]] || return 1
    if [[ $id == gre-tun-* ]]; then
        gtm_owned_gre "${id#gre-tun-}" || return 1
        parts=$(sha256sum "$file") || return 1
    else
        [[ -f $GTM_CONFIG_DIR/$id.toml && ! -L $GTM_CONFIG_DIR/$id.toml ]] || return 1
        parts=$(sha256sum "$file" "$GTM_CONFIG_DIR/$id.toml") || return 1
    fi
    sum=$(printf '%s\n' "$parts" | sha256sum) || return 1
    printf '%s\n' "${sum%% *}"
}

gtm_pair_revision() {
    local id=$1
    gtm_pair_service "$id" || return 1
    gtm_pair_auxiliary_absent "$id" || return 1
    [[ ! -e $GTM_SERVICE_DIR/$id.service && ! -L $GTM_SERVICE_DIR/$id.service && ! -e $GTM_CONFIG_DIR/$id.toml && ! -L $GTM_CONFIG_DIR/$id.toml ]] || return 1
    gtm_load_records || return 1
    { printf '%s\n' "$id"; ((${#GTM_RECORDS[@]}==0)) || printf '%s\n' "${GTM_RECORDS[@]}"; } | sha256sum | cut -d' ' -f1
}

gtm_pair_gre_check() {
    local tid=$1 role=$2 remote=$3 bind=$4 mtu=$5 iface maximum=1472
    gtm_uint "$tid" 1 250 && [[ $role == kharej || $role == iran ]] && gtm_ip "$remote" && gtm_ip "$bind" || return 1
    if [[ $remote == *:* ]]; then maximum=1452; [[ $bind == *:* ]] || return 1
    else [[ $bind != *:* ]] || return 1; fi
    gtm_uint "$mtu" 1280 "$maximum" && gtm_local_address "$bind" && gtm_need ip && gtm_need systemctl && gtm_need sha256sum || return 1
    tid=$((10#$tid)); iface="gre$tid"; [[ $role != iran ]] || iface="gre-out-$tid"
    ! ip link show "$iface" >/dev/null 2>&1 || return 1
    # No default/policy-route changes. Refuse assigned internal address conflicts;
    # GRE still creates its normal connected routes, protected by a root lease.
    ! ip -o addr show | awk '{print $4}' | grep -Eq "^(10\.0\.$tid\.|fd00:$tid:)" || return 1
    gtm_pair_revision "gre-tun-$tid"
}

gtm_pair_frp_check() {
    local bin tmp id="gtm-frp-$P_ROLE-$P_NAME"
    gtm_frp_validate && gtm_need sha256sum || return 1
    if [[ $P_ROLE == entrance ]]; then
        gtm_local_address "$P_HOST" && gtm_port_available tcp "$P_HOST" "$P_CONTROL" && gtm_port_available "$P_PROTO" "$P_HOST" "$P_PUBLIC" || return 1
        [[ $P_TRANSPORT != quic && $P_TRANSPORT != kcp ]] || gtm_port_available udp "$P_HOST" "$P_CONTROL" || return 1
        bin=$(command -v frps) || return 1
    else bin=$(command -v frpc) || return 1; fi
    tmp=$(mktemp "$GTM_RUN_DIR/pair-frp.XXXXXX") || return 1
    if ! { gtm_frp_render > "$tmp" && "$bin" verify -c "$tmp" >&2; }; then rm -f "$tmp"; return 1; fi
    rm -f "$tmp"
    gtm_pair_revision "$id"
}

gtm_pair_api() {
    # Exit 75 is reserved for refusal BEFORE any network mutation. Once create
    # begins, failures use normal failure codes and require receipt inspection.
    local operation=$1 revision='' actual id result=1
    shift
    gtm_prepare && gtm_lock || return 1
    case $operation in
        pair-check-gre|pair-apply-gre)
            if [[ $operation == pair-apply-gre ]]; then revision=${1:-}; shift; result=75; fi
            if (($#==5)); then
                actual=$(gtm_pair_gre_check "$@") || { gtm_unlock; [[ $operation != pair-apply-gre ]] || return 75; return 1; }
                if [[ $operation == pair-check-gre ]]; then printf '%s\n' "$actual"; result=0
                elif [[ $revision =~ ^[a-f0-9]{64}$ && $revision == "$actual" ]]; then
                    id="gre-tun-$((10#$1))"
                    gtm_link_create "$@" >&2 && gtm_pair_fingerprint "$id"; result=$?
                fi
            fi;;
        pair-check-frp|pair-apply-frp)
            if [[ $operation == pair-apply-frp ]]; then revision=${1:-}; shift; result=75; fi
            if (($#==0)) && gtm_pair_frp_parse; then
                actual=$(gtm_pair_frp_check) || { unset P_TOKEN; gtm_unlock; [[ $operation != pair-apply-frp ]] || return 75; return 1; }
                if [[ $operation == pair-check-frp ]]; then printf '%s\n' "$actual"; result=0
                elif [[ $revision =~ ^[a-f0-9]{64}$ && $revision == "$actual" ]]; then
                    id="gtm-frp-$P_ROLE-$P_NAME"
                    gtm_frp_create >&2 && gtm_pair_fingerprint "$id"; result=$?
                fi
                unset P_TOKEN
            fi;;
        pair-verify|pair-delete)
            if (($#==2)) && gtm_pair_service "$1" && [[ $2 =~ ^[a-f0-9]{64}$ ]]; then
                id=$1; actual=$(gtm_pair_fingerprint "$id") || { gtm_unlock; return 1; }
                if [[ $actual == "$2" ]]; then
                    if [[ $operation == pair-verify ]]; then result=0
                    elif [[ $id == gre-tun-* ]]; then
                        gtm_confirm() { return 0; }; gtm_link_delete "${id#gre-tun-}"; result=$?
                    else gtm_reverse_delete "$id"; result=$?; fi
                fi
            fi;;
    esac
    gtm_unlock
    return "$result"
}

# BEGIN MODULE: recovery
# Portable recovery accepts typed records only. No imported commands or units.
gtm_recovery_revision() (
    local file
    set -o pipefail
    {
        for file in "$GTM_STATE" "$GTM_CONFIG_DIR/id-counter" "$GTM_CONFIG_DIR/resource-names.tsv" "$GTM_SERVICE_DIR"/gre-tun-*.service "$GTM_SERVICE_DIR"/gtm-frp-*.service "$GTM_SERVICE_DIR"/gtm-rathole-*.service "$GTM_SERVICE_DIR"/gtm-gateway-*.service "$GTM_CONFIG_DIR"/gtm-frp-*.toml "$GTM_CONFIG_DIR"/gtm-rathole-*.toml "$GTM_CONFIG_DIR"/gtm-gateway-*.conf; do
            [[ -e $file || -L $file ]] || continue
            [[ -f $file && ! -L $file ]] || exit 1
            sha256sum "$file" || exit 1
        done
    } | sha256sum | cut -d ' ' -f 1
)

gtm_recovery_reverse_parse() {
    local line=$1 fields engine key cert internal
    fields=${line//[^$'\t']/}; ((${#fields}==15)) && [[ $line != *$'\r'* ]] || return 1
    IFS=$'\t' read -r engine P_NAME P_ROLE P_HOST P_CONTROL P_PUBLIC P_LOCAL_IP P_LOCAL_PORT P_PROTO P_TRANSPORT P_MUX P_TOKEN P_GROUP key cert internal <<< "$line"
    [[ $P_NAME =~ ^[a-zA-Z0-9_-]{1,32}$ ]] || return 1
    case $engine in
        frp) P_TLS_CA=$cert; P_GATEWAY_CERT=$cert; P_INTERNAL=$internal; gtm_frp_validate;;
        rathole)
            RATH_NAME=$P_NAME; RATH_ROLE=$P_ROLE; RATH_HOST=$P_HOST; RATH_CONTROL=$P_CONTROL; RATH_PUBLIC=$P_PUBLIC
            RATH_LOCAL_IP=$P_LOCAL_IP; RATH_LOCAL_PORT=$P_LOCAL_PORT; RATH_PROTO=$P_PROTO; RATH_TOKEN=$P_TOKEN; RATH_KEY=$key
            gtm_rathole_validate;;
        *) return 1;;
    esac
}

gtm_recovery_render() {
    local kind=$1 line
    IFS= read -r line || return 1
    ((${#line}<=4096)) || return 1
    case $kind in
        frp|rathole|gateway)
            if [[ $kind == gateway ]]; then [[ ${line%%$'\t'*} == frp ]] || return 1
            else [[ ${line%%$'\t'*} == "$kind" ]] || return 1; fi
            gtm_recovery_reverse_parse "$line" || return 1
            case $kind in frp) gtm_frp_render;; rathole) gtm_rathole_render;; gateway) [[ $P_TRANSPORT == wss && $P_ROLE == entrance ]] && gtm_wss_haproxy_render;; esac;;
        *) return 1;;
    esac
}

gtm_recovery_publish() {
    local source=$1 target=$2 mode=$3 candidate
    candidate=$(mktemp "${target%/*}/.recovery.XXXXXX") || return 1
    install -m "$mode" "$source" "$candidate" && mv -f "$candidate" "$target" || { rm -f "$candidate"; return 1; }
}

# Restore onto an empty managed installation. All imported resources stay paused.
# Complete validation/staging precedes the first persistent configuration write.
gtm_recovery_import() (
    local expected actual line kind data id tmp file result=0 maximum=0 value name hash count=0 counter_seen=0 resources=0
    local -a rows=() staged=() names=() state_files=(connections.tsv id-counter resource-names.tsv)
    IFS= read -r expected && [[ $expected =~ ^[a-f0-9]{64}$ ]] && gtm_prepare && gtm_lock || return 1
    actual=$(gtm_recovery_revision) && [[ $actual == "$expected" ]] || { gtm_error 'Server configuration changed; review the backup again.'; return 1; }
    gtm_load_records && ((${#GTM_RECORDS[@]}==0)) || { gtm_error 'Restore requires an empty managed installation.'; return 1; }
    for file in "$GTM_SERVICE_DIR"/gre-tun-*.service "$GTM_SERVICE_DIR"/gtm-frp-*.service "$GTM_SERVICE_DIR"/gtm-rathole-*.service "$GTM_CONFIG_DIR"/gtm-frp-*.toml "$GTM_CONFIG_DIR"/gtm-rathole-*.toml; do
        [[ ! -e $file && ! -L $file ]] || { gtm_error 'Existing tunnel files must be resolved before recovery.'; return 1; }
    done
    tmp=$(mktemp -d "$GTM_RUN_DIR/recovery.XXXXXX") || return 1
    trap 'rm -f "$tmp"/*; rmdir "$tmp"; gtm_unlock' EXIT
    local -A seen=() named=() policies=() imported_policies=()
    while IFS= read -r line || [[ -n $line ]]; do
        ((count+=1)); ((${#line}<=16384 && count<=4096)) || return 1
        [[ $line == *$'\t'* ]] || return 1
        kind=${line%%$'\t'*}; data=${line#*$'\t'}
        case $kind in
            I) ((counter_seen==0 && count==1)) && gtm_uint "$data" 0 999999 || return 1; counter_seen=1; maximum=$((10#$data));;
            D)
                local dns_name every mode extra
                IFS=$'\t' read -r dns_name every mode extra <<< "$data"
                gtm_hostname "$dns_name" && [[ -z $extra && ! ${imported_policies[$dns_name]+set} ]] && gtm_uint "$every" 1 60 && [[ $mode == all || $mode == first ]] || return 1
                imported_policies[$dns_name]="$every"$'\t'"$mode"
                ((${#imported_policies[@]}<=128)) || return 1;;
            C)
                gtm_record_validate "$data" && [[ $R_ENABLED == 0 && $R_ID != F000000 && ! ${seen[$R_ID]+set} ]] || return 1
                seen[$R_ID]=1; value=$((10#${R_ID#F})); ((value<=maximum)) || maximum=$value
                rows+=("$data"); ((${#rows[@]}<=128)) || return 1;;
            G)
                ((resources+=1)); ((resources<=512)) || return 1
                local tid role remote bind mtu extra
                IFS=$'\t' read -r tid role remote bind mtu extra <<< "$data"
                [[ -z $extra ]] && gtm_uint "$tid" 1 250 && [[ $role == kharej || $role == iran ]] && gtm_ip "$remote" && gtm_ip "$bind" || return 1
                if [[ $remote == *:* ]]; then [[ $bind == *:* ]] && gtm_uint "$mtu" 1280 1452 || return 1
                else [[ $bind != *:* ]] && gtm_uint "$mtu" 1280 1472 || return 1; fi
                id="gre-tun-$((10#$tid))"; [[ ! ${seen[$id]+set} ]] || return 1; seen[$id]=1
                gtm_link_render "$tid" "$role" "$remote" "$bind" "$mtu" > "$tmp/$id.service" || return 1
                staged+=("$id.service");;
            R)
                ((resources+=1)); ((resources<=512)) || return 1
                gtm_recovery_reverse_parse "$data" || return 1
                id="gtm-${data%%$'\t'*}-$P_ROLE-$P_NAME"; [[ ! ${seen[$id]+set} ]] || return 1; seen[$id]=1
                if [[ $id == gtm-frp-* ]]; then
                    gtm_frp_render > "$tmp/$id.toml" || return 1
                    local bin=/usr/local/bin/frpc; [[ $P_ROLE != entrance ]] || bin=/usr/local/bin/frps
                    gtm_relay_unit "$bin" "$GTM_CONFIG_DIR/$id.toml" "$P_NAME" > "$tmp/$id.service" || return 1
                    if [[ $P_TRANSPORT == wss && $P_ROLE == entrance ]]; then
                        local gateway="gtm-gateway-$P_NAME"
                        gtm_wss_haproxy_render > "$tmp/$gateway.conf" || return 1
                        gtm_wss_gateway_unit /usr/sbin/haproxy "$GTM_CONFIG_DIR/$gateway.conf" "$P_NAME" "$id" > "$tmp/$gateway.service" || return 1
                        sed -i "/After=network-online.target/a Wants=$gateway.service" "$tmp/$id.service" || return 1
                        staged+=("$gateway.conf" "$gateway.service")
                    fi
                else
                    gtm_rathole_render > "$tmp/$id.toml" && gtm_rathole_unit /usr/local/bin/rathole "$GTM_CONFIG_DIR/$id.toml" > "$tmp/$id.service" || return 1
                fi
                staged+=("$id.toml" "$id.service");;
            N)
                IFS=$'\t' read -r id name extra <<< "$data"
                gtm_metadata_id "$id" && [[ -z $extra && ${seen[$id]+set} && ! ${named[$id]+set} && -f $tmp/$id.service ]] && gtm_name "$name" || return 1
                named[$id]=1
                hash=$(sha256sum "$tmp/$id.service") || return 1; names+=("$id"$'\t'"${hash%% *}"$'\t'"$name");;
            *) return 1;;
        esac
    done
    GTM_RECORDS=("${rows[@]}")
    gtm_write_records "$tmp/connections.tsv" && gtm_load_records "$tmp/connections.tsv" || return 1
    if ((${#imported_policies[@]})); then
        local policy_line target
        local -a dns_targets=()
        local -A used_names=()
        for line in "${GTM_RECORDS[@]}"; do
            gtm_record_validate "$line" || return 1
            IFS=, read -r -a dns_targets <<< "$R_TARGETS"
            for target in "${dns_targets[@]}"; do gtm_target "$target" || return 1; ((EP_HOST==0)) || used_names[$EP_IP]=1; done
        done
        [[ ! -L $GTM_CONFIG_DIR/dns-policy.tsv ]] || return 1
        if [[ -e $GTM_CONFIG_DIR/dns-policy.tsv ]]; then
            [[ -f $GTM_CONFIG_DIR/dns-policy.tsv ]] || return 1
            while IFS=$'\t' read -r dns_name every mode extra; do
                gtm_hostname "$dns_name" && [[ -z $extra && ! ${policies[$dns_name]+set} ]] && gtm_uint "$every" 1 60 && [[ $mode == all || $mode == first ]] || return 1
                policies[$dns_name]="$every"$'\t'"$mode"
            done < "$GTM_CONFIG_DIR/dns-policy.tsv"
        fi
        for dns_name in "${!imported_policies[@]}"; do
            [[ ${used_names[$dns_name]+set} ]] || return 1
            policies[$dns_name]=${imported_policies[$dns_name]}
        done
        for dns_name in "${!policies[@]}"; do printf '%s\t%s\n' "$dns_name" "${policies[$dns_name]}"; done | sort > "$tmp/dns-policy.tsv" || return 1
        state_files+=(dns-policy.tsv)
    fi
    # Never clobber orphaned files, gateway configs or symbolic links.
    for file in "${staged[@]}"; do
        local root=$GTM_CONFIG_DIR; [[ $file != *.service ]] || root=$GTM_SERVICE_DIR
        [[ ! -e $root/$file && ! -L $root/$file ]] || { gtm_error 'Recovery file conflicts with an existing resource.'; return 1; }
        [[ $file != *.service || ( ! -e $GTM_SERVICE_DIR/multi-user.target.wants/$file && ! -L $GTM_SERVICE_DIR/multi-user.target.wants/$file ) ]] || { gtm_error 'A boot link already exists for this service; inspect it before recovery.'; return 1; }
        if [[ $file == *.service ]] && systemctl is-active --quiet "${file%.service}"; then gtm_error 'An imported service is already running; inspect the local installation.'; return 1; fi
    done
    [[ ! -L $GTM_CONFIG_DIR/id-counter && ! -L $GTM_CONFIG_DIR/resource-names.tsv ]] || return 1
    # Recovery saves desired data only: it starts no services or firewall rules.
    # Keep previous state/counter/metadata for a checked rollback on write failure.
    for file in "${state_files[@]}"; do
        [[ ! -e $GTM_CONFIG_DIR/$file ]] || cp -p "$GTM_CONFIG_DIR/$file" "$tmp/old-$file" || return 1
    done
    local -a written=()
    for file in "${staged[@]}"; do
        local root=$GTM_CONFIG_DIR mode=600; [[ $file != *.service ]] || { root=$GTM_SERVICE_DIR; mode=644; }
        if gtm_recovery_publish "$tmp/$file" "$root/$file" "$mode"; then written+=("$root/$file"); else result=1; break; fi
    done
    if ((result==0)); then
        if [[ -f $tmp/old-id-counter ]]; then
            IFS= read -r value < "$tmp/old-id-counter"
            gtm_uint "$value" 0 999999 || result=1
            [[ $result != 0 ]] || { ((10#$value<=maximum)) || maximum=$((10#$value)); }
        fi
        printf '%s\n' "$maximum" > "$tmp/id-counter"
        : > "$tmp/resource-names.tsv"
        ((${#names[@]}==0)) || printf '%s\n' "${names[@]}" > "$tmp/resource-names.tsv"
        for file in "${state_files[@]}"; do
            ((result==0)) && gtm_recovery_publish "$tmp/$file" "$GTM_CONFIG_DIR/$file" 600 || { result=1; break; }
        done
        ((result!=0)) || systemctl daemon-reload || result=1
    fi
    if ((result)); then
        for file in "${written[@]}"; do rm -f "$file" || gtm_error 'Recovery cleanup needs attention.'; done
        for file in "${state_files[@]}"; do
            if [[ -f $tmp/old-$file ]]; then gtm_recovery_publish "$tmp/old-$file" "$GTM_CONFIG_DIR/$file" 600 || gtm_error 'Recovery rollback needs attention.'
            else rm -f "$GTM_CONFIG_DIR/$file" || gtm_error 'Recovery rollback needs attention.'; fi
        done
        systemctl daemon-reload || gtm_error 'Reload needs attention.'
        return 1
    fi
    printf 'Recovery saved. All restored resources are paused. Install missing engines, review addresses and start resources explicitly.\n'
)

# BEGIN MODULE: history
# Change history: the automatic restore points gtm_commit writes before every
# forwarding change, newest first, and restoring one through the normal
# commit path. A restore saves the current state as a new restore point
# first, so it can be undone the same way.

gtm_history_name_valid() { [[ $1 =~ ^[0-9]{8}T[0-9]{6}-[0-9]+-[0-9]+\.tsv$ ]]; }

# New names contain a locked monotonic nanosecond sequence. Historical PID/random
# names use their write time as a best-effort tie-breaker within the named second.
gtm_history_points() {
    local file name modified
    for file in "$GTM_CONFIG_DIR"/backups/*.tsv; do
        [[ -f $file && ! -L $file ]] && gtm_history_name_valid "${file##*/}" || continue
        name=${file##*/}
        if [[ $name =~ ^[0-9]{8}T[0-9]{6}-([0-8][0-9]{18})-[0-9]+\.tsv$ ]]; then
            modified=${BASH_REMATCH[1]: -9}
        else
            modified=$(stat -c '%y' -- "$file") || return 1
            modified=${modified#*.}; modified=${modified:0:9}
        fi
        printf '%s\t%s\t%s\n' "${name:0:15}" "$modified" "$file"
    done | LC_ALL=C sort -r | cut -f 3-
}

# Read-only: "revision", "total", then per point "point NAME" followed by
# "row RECORD" lines (normalized records) or "invalid NAME".
gtm_history() {
    local limit=${1:-30} file line
    local -a points=()
    gtm_uint "$limit" 1 100 || { gtm_error 'History limit must be 1-100.'; return 2; }
    mapfile -t points < <(gtm_history_points)
    printf 'revision\t%s\n' "$(gtm_recovery_revision)"
    printf 'total\t%d\n' "${#points[@]}"
    for file in "${points[@]:0:10#$limit}"; do
        if ! gtm_load_records "$file" 2>/dev/null; then printf 'invalid\t%s\n' "${file##*/}"; continue; fi
        printf 'point\t%s\n' "${file##*/}"
        for line in ${GTM_RECORDS[@]+"${GTM_RECORDS[@]}"}; do printf 'row\t%s\n' "$line"; done
    done
}

# Restores one point when the configuration still has the reviewed revision.
gtm_history_restore() {
    local name=$1 expected=$2 file actual result=1
    gtm_history_name_valid "$name" && [[ $expected =~ ^[a-f0-9]{64}$ ]] || { gtm_error 'Invalid restore point.'; return 2; }
    file="$GTM_CONFIG_DIR/backups/$name"
    [[ -f $file && ! -L $file ]] || { gtm_error 'Restore point not found.'; return 1; }
    gtm_prepare && gtm_lock || return 1
    actual=$(gtm_recovery_revision) && [[ $actual == "$expected" ]] || { gtm_error 'Configuration changed; review the restore again.'; gtm_unlock; return 1; }
    if gtm_load_records "$file"; then gtm_commit; result=$?; fi
    gtm_unlock
    return "$result"
}

# BEGIN MODULE: diagnose
# Guided "why is this connection down" check for one connection or GRE
# tunnel. Read-only: it reads state, units, interfaces, rules and sysctls,
# and lists the endpoints the panel then probes. Output lines:
#   check<TAB>KEY<TAB>ok|warn|fail|info<TAB>DETAIL
#   probe<TAB>tcp|udp|icmp<TAB>ADDRESS<TAB>PORT<TAB>KEY
# KEY names the check; the panel translates it and suggests a fix.

gtm_diag() { printf 'check\t%s\t%s\t%s\n' "$1" "$2" "${3:-}"; }

gtm_diag_sysctl() { sysctl -n "$1" 2>/dev/null || cat "/proc/sys/${1//.//}" 2>/dev/null; }

# Conntrack table pressure is the most common cause of a forwarder that
# accepts some flows and silently drops new ones.
gtm_diag_conntrack() {
    local used maximum percent
    used=$(gtm_diag_sysctl net.netfilter.nf_conntrack_count) && maximum=$(gtm_diag_sysctl net.netfilter.nf_conntrack_max) || return 0
    [[ $used =~ ^[0-9]+$ && $maximum =~ ^[1-9][0-9]*$ ]] || return 0
    percent=$((10#$used * 100 / 10#$maximum))
    if ((percent >= 90)); then gtm_diag conntrack fail "$used/$maximum"
    elif ((percent >= 75)); then gtm_diag conntrack warn "$used/$maximum"
    else gtm_diag conntrack ok "$used/$maximum"; fi
}

gtm_diag_service() {
    local unit=$1 state
    command -v systemctl >/dev/null 2>&1 || { gtm_diag service info 'systemctl unavailable'; return; }
    state=$(systemctl is-active "$unit" 2>/dev/null) || :
    case $state in
        active) gtm_diag service ok "$unit";;
        activating|reloading) gtm_diag service warn "$unit $state";;
        *) gtm_diag service fail "$unit ${state:-inactive}";;
    esac
}

gtm_diag_forward_rules() {
    local id=$1 family=$2 count=0
    case $R_ENGINE in
        nftables)
            command -v nft >/dev/null 2>&1 || { gtm_diag component fail nft; return; }
            count=$(nft list table inet gre_manager 2>/dev/null | grep -c -- "\"gtm-$id\"") || :;;
        iptables)
            local tool=iptables-save
            [[ $family == 4 ]] || tool=ip6tables-save
            command -v "$tool" >/dev/null 2>&1 || { gtm_diag component fail "$tool"; return; }
            count=$("$tool" -t nat 2>/dev/null | grep -c -- "gtm-$id ") || :;;
    esac
    if ((count > 0)); then gtm_diag rules ok "$count"; else gtm_diag rules fail "$R_ENGINE"; fi
}

gtm_diag_listener() {
    local port=$1 proto=$2 flags=-Hltn
    command -v ss >/dev/null 2>&1 || return 0
    [[ $proto != udp ]] || flags=-Hlun
    if ss "$flags" "sport = :$((10#$port))" 2>/dev/null | grep -q .; then gtm_diag listener ok "$proto/$port"
    else gtm_diag listener fail "$proto/$port"; fi
}

gtm_diag_route() {
    local address=$1 route dev
    command -v ip >/dev/null 2>&1 || return 0
    route=$(ip -o route get "$address" 2>/dev/null) || { gtm_diag route fail "$address"; return; }
    [[ $route =~ \ dev\ ([^ ]+) ]] && dev=${BASH_REMATCH[1]} || dev=-
    if [[ $dev != - && -r /sys/class/net/$dev/operstate && $(cat "/sys/class/net/$dev/operstate") == down ]]; then gtm_diag route fail "$address via $dev (down)"
    else gtm_diag route ok "$address via $dev"; fi
}

gtm_diagnose_connection() {
    local id=$1 line found=0 family=4 forwarding target address port proto excluded
    local -a targets=()
    gtm_load_records || return 1
    for line in ${GTM_RECORDS[@]+"${GTM_RECORDS[@]}"}; do
        gtm_record_validate "$line" || return 1
        [[ $R_ID == "$id" ]] && { found=1; break; }
    done
    ((found)) || { gtm_error 'Connection not found.'; return 1; }
    [[ $R_BIND != *:* ]] || family=6
    if [[ $R_ENABLED == 1 ]]; then gtm_diag enabled ok; else gtm_diag enabled fail; fi
    case $R_ENGINE in
        iptables|nftables)
            if [[ $family == 4 ]]; then forwarding=$(gtm_diag_sysctl net.ipv4.ip_forward); else forwarding=$(gtm_diag_sysctl net.ipv6.conf.all.forwarding); fi
            if [[ $forwarding == 1 ]]; then gtm_diag forwarding ok "IPv$family"; else gtm_diag forwarding fail "IPv$family=${forwarding:-?}"; fi
            [[ $R_ENABLED != 1 ]] || gtm_diag_forward_rules "$id" "$family"
            excluded=$(awk -F '\t' -v id="$id" '$1 == id {print $3}' "$(gtm_exclusions_file)" 2>/dev/null)
            if [[ -n $excluded && $excluded != - ]]; then gtm_diag failover warn "$excluded"; fi;;
        *)
            gtm_diag_service "gtm-$id"
            for proto in tcp udp; do
                [[ $R_PROTO == "$proto" || $R_PROTO == both ]] && gtm_diag_listener "$R_PORT" "$proto"
            done;;
    esac
    gtm_diag_conntrack
    if [[ $R_TARGETS =~ (^|,)[a-z0-9.-]*[a-z][a-z0-9.-]*: ]]; then
        if gtm_resolve_targets; then gtm_diag dns ok "$R_TARGETS"; else gtm_diag dns fail; fi
    fi
    IFS=, read -r -a targets <<< "$R_TARGETS"
    for target in "${targets[@]:0:8}"; do
        gtm_target "$target" || continue
        address=$EP_IP port=$EP_PORT
        gtm_diag_route "$address"
        proto=tcp; [[ $R_PROTO != udp ]] || proto=udp
        printf 'probe\t%s\t%s\t%s\tdestination\n' "$proto" "$address" "$port"
    done
}

gtm_diagnose_gre() {
    local tid=$1 unit iface remote source inner peer suffix state address strict policy
    tid=$((10#$tid)); unit="$GTM_SERVICE_DIR/gre-tun-$tid.service"
    [[ -f $unit && ! -L $unit ]] || { gtm_error 'GRE tunnel not found.'; return 1; }
    iface=$(awk '$1 ~ /ExecStart=\/sbin\/ip/ && /tunnel add/ {for (i=1;i<=NF;i++) if ($i == "add") {print $(i+1); exit}}' "$unit")
    remote=$(awk '/tunnel add/ {for (i=1;i<=NF;i++) if ($i == "remote") {print $(i+1); exit}}' "$unit")
    source=$(awk '/tunnel add/ {for (i=1;i<=NF;i++) if ($i == "local") {print $(i+1); exit}}' "$unit")
    [[ $iface =~ ^gre(-out-)?[0-9]{1,3}$ ]] && gtm_ip "$remote" && gtm_ip "$source" || { gtm_error 'Unrecognized GRE unit.'; return 1; }
    suffix=1; peer=2
    [[ $iface != gre-out-* ]] || { suffix=2; peer=1; }
    inner="10.0.$tid.$peer"
    gtm_diag_service "gre-tun-$tid"
    if [[ -d /sys/class/net/$iface ]]; then
        state=$(cat "/sys/class/net/$iface/operstate" 2>/dev/null)
        # GRE links report "unknown" while up: they have no carrier.
        if [[ $state == down ]]; then gtm_diag interface fail "$iface down"; else gtm_diag interface ok "$iface"; fi
    else
        gtm_diag interface fail "$iface missing"
    fi
    if command -v ip >/dev/null 2>&1; then
        if ip -o address show 2>/dev/null | awk '{print $4}' | grep -qx -- "$source/[0-9]*"; then gtm_diag local-address ok "$source"
        else gtm_diag local-address fail "$source"; fi
        address=$(ip -o -4 address show dev "$iface" 2>/dev/null | awk '{print $4; exit}')
        if [[ $address == "10.0.$tid.$suffix/30" ]]; then gtm_diag inner-address ok "$address"; else gtm_diag inner-address fail "${address:-none}"; fi
    fi
    strict=0
    for state in all "$iface"; do [[ $(cat "/proc/sys/net/ipv4/conf/$state/rp_filter" 2>/dev/null) != 1 ]] || strict=1; done
    if ((strict)); then gtm_diag rp-filter warn strict; else gtm_diag rp-filter ok; fi
    # A DROP input policy without a GRE accept rule blocks protocol 47 here;
    # the far side's firewall is checked by the probe from that side only.
    if command -v iptables >/dev/null 2>&1 && [[ $remote != *:* ]]; then
        policy=$(iptables -S INPUT 2>/dev/null | awk '$1 == "-P" {print $3; exit}')
        if [[ $policy == DROP ]] && ! iptables -S INPUT 2>/dev/null | grep -Eq -- '-p (gre|47) .*-j ACCEPT|-s '"$remote"'(/32)? .*-j ACCEPT'; then gtm_diag gre-input warn 'INPUT policy DROP'
        else gtm_diag gre-input ok "${policy:-?}"; fi
    fi
    gtm_diag_conntrack
    printf 'probe\ticmp\t%s\t0\tpeer-public\n' "$remote"
    printf 'probe\ticmp\t%s\t0\tpeer-inner\n' "$inner"
}

gtm_diagnose() {
    local id=$1 tid=${1#gre-tun-}
    if [[ $id =~ ^F[0-9]{6}$ ]]; then gtm_diagnose_connection "$id"
    elif [[ $id == gre-tun-* && $tid =~ ^[0-9]{1,3}$ ]] && gtm_uint "$tid" 1 250; then gtm_diagnose_gre "$tid"
    else gtm_error 'Diagnosis supports connections and GRE tunnels.'; return 2; fi
}

# BEGIN MODULE: api
# Noninteractive control boundary. Input is validated TSV data, never shell code.
# The privileged local broker is the only web-panel caller; the CLI can use it too.
gtm_api_rows() {
    local GTM_COMMIT_RECEIPT=1
    local line id component result=1 count=0 expected=${1:-} actual
    local -a incoming=()
    while IFS= read -r line || [[ -n $line ]]; do
        ((count+=1)); ((count<=32)) && gtm_record_validate "$line" && [[ $R_ID == F000000 ]] || return 1
        incoming+=("$line")
    done
    ((count>0)) && gtm_prepare && gtm_lock || return 1
    if [[ -n $expected ]]; then
        actual=$(gtm_recovery_revision) && [[ $actual == "$expected" ]] || { gtm_error 'Server configuration changed; review the import again.'; gtm_unlock; return 1; }
    fi
    if ! gtm_load_records; then gtm_unlock; return 1; fi
    for line in "${incoming[@]}"; do
        gtm_record_validate "$line" || { gtm_unlock; return 1; }
        component=$R_ENGINE
        case $component in iptables) gtm_need iptables;; nftables) gtm_need nft;; *) gtm_need "$component";; esac || { gtm_unlock; return 1; }
        if [[ $R_ENABLED == 1 ]]; then
            gtm_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" && gtm_legacy_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" || { gtm_unlock; return 1; }
        fi
        id=$(gtm_new_id) || { gtm_unlock; return 1; }
        GTM_RECORDS+=("$id${line#F000000}")
    done
    printf '%d\n' "$((10#${id#F}))" > "$GTM_CONFIG_DIR/id-counter.tmp" && mv "$GTM_CONFIG_DIR/id-counter.tmp" "$GTM_CONFIG_DIR/id-counter" || { gtm_unlock; return 1; }
    gtm_commit; result=$?
    gtm_unlock
    return "$result"
}

gtm_api_change() {
    local GTM_COMMIT_RECEIPT=1
    local operation=$1 expected replacement='' line result=1 found=0 previous_bind previous_port previous_proto previous_enabled
    local -a originals=() updated=()
    while IFS= read -r line || [[ -n $line ]]; do
        gtm_record_validate "$line" && [[ $R_ID != F000000 ]] || return 1
        originals+=("$line"); ((${#originals[@]}<=128)) || return 1
    done
    if [[ $operation == update ]]; then
        ((${#originals[@]}==2)) && [[ ${originals[0]%%$'\t'*} == "${originals[1]%%$'\t'*}" ]] || return 1
        replacement=${originals[1]}; originals=("${originals[0]}")
    fi
    ((${#originals[@]}>0)) && gtm_prepare && gtm_lock || return 1
    if ! gtm_load_records; then gtm_unlock; return 1; fi
    # Verify every selected row before mutating anything, including bulk operations.
    for expected in "${originals[@]}"; do
        found=0
        for line in "${GTM_RECORDS[@]}"; do [[ $line != "$expected" ]] || found=1; done
        ((found)) || { gtm_error 'Connection changed; refresh and try again.'; gtm_unlock; return 1; }
    done
    for line in "${GTM_RECORDS[@]}"; do
        found=0
        for expected in "${originals[@]}"; do [[ $line != "$expected" ]] || found=1; done
        if ((found)); then
            gtm_record_validate "$line" || { gtm_unlock; return 1; }
            previous_bind=$R_BIND; previous_port=$R_PORT; previous_proto=$R_PROTO; previous_enabled=$R_ENABLED
            case $operation in
                delete) continue;;
                update) line=$replacement;;
                enable|disable)
                    gtm_record_validate "$line" || { gtm_unlock; return 1; }
                    R_ENABLED=0; [[ $operation != enable ]] || R_ENABLED=1
                    line=$(gtm_record_emit);;
                *) gtm_unlock; return 1;;
            esac
            gtm_record_validate "$line" || { gtm_unlock; return 1; }
            if [[ $R_ENABLED == 1 && ( $previous_enabled == 0 || $R_BIND != "$previous_bind" || $R_PORT != "$previous_port" || $R_PROTO != "$previous_proto" ) ]]; then
                gtm_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" && gtm_legacy_listener_check "$R_PROTO" "$R_BIND" "$R_PORT" || { gtm_unlock; return 1; }
            fi
        fi
        updated+=("$line")
    done
    GTM_RECORDS=("${updated[@]}")
    gtm_commit; result=$?
    gtm_unlock
    return "$result"
}

gtm_api() {
    local operation=${1:-} component
    shift || return 2
    case $operation in
        component-policy) gtm_component_policy "$@";;
        component-update) { (($#==2)) || { (($#==3)) && [[ $1 == frp ]]; }; } && gtm_component_update "$@";;
        recovery-revision) (($#==0)) && gtm_recovery_revision;;
        recovery-render) (($#==1)) && gtm_recovery_render "$1";;
        recovery-import) (($#==0)) && gtm_recovery_import;;
        resource-rename) (($#==2)) || return 2
            local display_name
            IFS= read -r display_name || return 2
            gtm_prepare && gtm_lock || return 2
            gtm_metadata_rename "$1" "$2" "$display_name"; local result=$?; gtm_unlock; return "$result";;
        pair-check-gre|pair-apply-gre|pair-check-frp|pair-apply-frp|pair-verify|pair-delete) gtm_pair_api "$operation" "$@";;
        state) (($#==0)) && gtm_load_records && { ((${#GTM_RECORDS[@]}==0)) || printf '%s\n' "${GTM_RECORDS[@]}"; };;
        create) (($#==0)) && gtm_api_rows;;
        create-reviewed) (($#==0)) || return 2
            local expected
            IFS= read -r expected && [[ $expected =~ ^[a-f0-9]{64}$ ]] || return 2
            gtm_api_rows "$expected";;
        update|enable|disable|delete) (($#==0)) && gtm_api_change "$operation";;
        plan) (($#==0)) && gtm_plan;;
        history) (($#<=1)) && gtm_history "$@";;
        history-restore) (($#==2)) && gtm_history_restore "$1" "$2";;
        diagnose) (($#==1)) && gtm_diagnose "$1";;
        dns-resolve) (($#==2)) && [[ $2 == 4 || $2 == 6 ]] && gtm_dns_lookup "$1" "$2";;
        dns-cache) (($#==0)) && gtm_dns_view;;
        dns-policy) (($#==3)) || return 2; gtm_prepare && gtm_lock || return 1
            gtm_dns_policy_set "$@"; local result=$?; gtm_unlock
            ((result == 0)) || return "$result"
            gtm_dns_refresh --force;;
        dns-refresh) (($#==0)) && gtm_dns_refresh --force;;
        dns-status|dns-apply|dns-restore) gtm_sysdns_api "$operation" "$@";;
        portfw-rules) (($#==0)) && gtm_portfw_rules;;
        # Maintenance: reapply owned kernel rules from saved state; clear one forward's flows.
        kernel-refresh) (($#==0)) && gtm_prepare && gtm_lock || return 2
            gtm_kernel_apply; local result=$?; gtm_unlock
            ((result)) || printf 'Owned kernel rules reapplied; established flows kept.\n'
            return "$result";;
        flows-reset) (($#==1)) && gtm_prepare || return 2
            gtm_flows_reset "$1";;
        # Health failover: runtime-only destination exclusions for one kernel forward.
        forward-exclude) (($#==2)) && gtm_prepare && gtm_lock || return 2
            gtm_forward_exclude "$1" "$2"; local result=$?; gtm_unlock; return "$result";;
        # Server optimization. Status and plan only read; the others lock.
        # Profiles: LEVEL GOAL ("- -" for the saved one). Plan and apply take
        # comma-separated groups and optional key=value custom values; apply
        # also takes allow|deny for custom values worse than the original.
        optimize-status) (($#==0 || $#==2)) || return 2
            gtm_optimize_use_profile "${1:--}" "${2:--}" || return 2
            gtm_optimize_status;;
        optimize-plan) (($#>=3)) || return 2
            gtm_optimize_use_profile "$1" "$2" && gtm_optimize_custom "${@:4}" || return 2
            local -a groups=(); IFS=, read -r -a groups <<< "$3"
            ((${#groups[@]} <= 5)) || return 2
            gtm_optimize_plan "${groups[@]}";;
        optimize-apply|optimize-undo|optimize-remove)
            local -a groups=()
            case $operation in
                optimize-apply) (($#>=4)) && [[ $4 =~ ^(allow|deny)$ ]] || return 2
                    gtm_optimize_use_profile "$1" "$2" && gtm_optimize_custom "${@:5}" || return 2
                    IFS=, read -r -a groups <<< "$3"
                    ((${#groups[@]} <= 5)) && gtm_optimize_groups_valid "${groups[@]}" || return 2
                    GTM_OPT_ALLOW_WORSE=0; [[ $4 != allow ]] || GTM_OPT_ALLOW_WORSE=1;;
                optimize-undo) (($#==0)) || return 2;;
                *) (($#==1)) || return 2;;
            esac
            gtm_prepare && gtm_lock || return 2
            # The panel previews the change first; this call is the confirmation.
            gtm_confirm() { return 0; }
            case $operation in
                optimize-apply) gtm_optimize_apply "${groups[@]}";;
                optimize-undo) gtm_optimize_undo;;
                *) gtm_optimize_remove "$1";;
            esac
            local result=$?; gtm_unlock; return "$result";;
        config-render) (($#==0)) && gtm_config_render;;
        doctor) (($#==0)) && gtm_doctor;;
        install)
            (($#>0 && $#<=7)) && gtm_prepare || return 2
            for component in "$@"; do
                case $component in iptables|nftables|haproxy|realm|frp|rathole) ;; *) return 2;; esac
            done
            # Explicit --api install authorizes these specific packages. No service
            # is enabled by this boundary; engine units are created only on apply.
            gtm_confirm() { return 0; }
            for component in "$@"; do gtm_install_component "$component" || return 1; done;;
        gre-create) (($#==5)) && gtm_prepare && gtm_lock || return 2
            gtm_link_create "$@"; local result=$?; gtm_unlock; return "$result";;
        gre-delete) (($#==1)) && gtm_prepare && gtm_lock || return 2
            gtm_confirm() { return 0; }
            gtm_link_delete "$1"; local result=$?; gtm_unlock; return "$result";;
        reverse-create) (($#==0)) && gtm_api_reverse;;
        reverse-delete) (($#==1)) && gtm_prepare && gtm_lock || return 2
            gtm_reverse_delete "$1"; local result=$?; gtm_unlock; return "$result";;
        *) gtm_error 'Unknown API operation.'; return 2;;
    esac
}

# BEGIN MODULE: panel
# Optional panel lifecycle; the standalone manager stays usable without Go/Node.
gtm_dependencies_menu() {
    local selection component
    local -a components=()
    printf '\n  Install optional engines now. Existing tunnels are not started or changed.\n'
    printf '  [1] All engines\n  [2] HAProxy\n  [3] Realm\n  [4] Kernel forwarding\n  [5] FRP + rathole\n  [0] Back\n'
    gtm_read 'Choose: ' selection || return
    case $selection in
        1) components=(iptables nftables haproxy realm frp rathole);;
        2) components=(haproxy);; 3) components=(realm);;
        4) components=(iptables nftables);; 5) components=(frp rathole);; *) return;;
    esac
    gtm_prepare || return
    for component in "${components[@]}"; do gtm_install_component "$component" || return 1; done
    gtm_pause
}

gtm_panel_install() {
    local tmp result
    gtm_root && gtm_need curl || return 1
    tmp=$(mktemp) || return 1
    if ! curl --proto '=https' --tlsv1.2 -fsSL --connect-timeout 15 --max-time 120 'https://raw.githubusercontent.com/Sir-Adnan/GRE-Tunnel-Manager/main/panel-install.sh' -o "$tmp"; then rm -f "$tmp"; return 1; fi
    bash -n "$tmp" && bash "$tmp" "$@"; result=$?
    rm -f "$tmp"
    return "$result"
}

